import{r}from"./react-vendor-DuJroiHx.js";import{H as P,Q as T,L as W,n as q,E as S,U,t as w,s as C,_ as f}from"./firebase-D7k-Q0Lm.js";import{z as y}from"./index-BEflPILw.js";import{Z as O}from"./AuthenticatedApp-CivYnsO6.js";import{e as d,s as Z}from"./exercise-notes-BO8Q0nTu.js";const k="exercise_notes",N=300,l=i=>O(i),R=()=>({}),A=i=>{const[t,g]=r.useState(R),[j,p]=r.useState(!1);r.useEffect(()=>{if(!i){p(!0);return}const a=P(q(y,k),W("userId","==",i),T(N)),z=S(a,e=>{const s={};e.forEach(M=>{const o=M.data(),u=String(o.exerciseName??"");u&&(s[l(u)]={userId:String(o.userId??""),exerciseName:u,note:String(o.note??""),...typeof o.machineSettings=="string"&&o.machineSettings?{machineSettings:o.machineSettings}:{},updatedAt:typeof o.updatedAt=="number"?o.updatedAt:0})}),g(s),p(!0)},e=>{console.error("[useExerciseNotes] Error:",e),p(!0)});return()=>z()},[i]);const b=r.useCallback(a=>t[l(a)],[t]),c=r.useCallback(async a=>{await U(w(y,k,d(i,a)))},[i]),h=r.useCallback(async(a,z)=>{const e=Z(z);if(!e.note&&!e.machineSettings){await c(a);return}const s={userId:i,exerciseName:a,...e,updatedAt:Date.now()};await C(w(y,k,d(i,a)),s)},[i,c]);return{getPinnedNote:b,savePinnedNote:h,deletePinnedNote:c,isLoaded:j}},m={"Wyciskanie sztangi na ławce płaskiej":{steps:["Połóż się na ławce, oczy pod gryfem, łopatki ściągnięte i wbite w ławkę, stopy mocno na podłodze.","Chwyć gryf nieco szerzej niż barki, zdejmij z asekuracji i ustaw nad klatką.","Opuść kontrolowanie sztangę do dolnej części klatki, łokcie pod kątem ok. 45 stopni do tułowia.","Wypchnij sztangę dynamicznie w górę do pełnego wyprostu, nie blokując gwałtownie łokci."],proTip:"Utrzymuj napięte łopatki i lekki most piersiowy przez cały ruch. Przerwij serię, jeśli nie utrzymujesz tej pozycji.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Sztanga olimpijska"},"Wyciskanie hantli na ławce płaskiej":{steps:["Usiądź na ławce z hantlami na udach, połóż się odbijając hantle kolanami nad klatkę.","Ściągnij łopatki, ustaw hantle na wysokości klatki, dłonie skierowane do przodu.","Opuść hantle kontrolowanie po bokach klatki, łokcie pod kątem ok. 45 stopni.","Wyciśnij hantle w górę, zbliżając je nad środkiem klatki bez stukania."],proTip:"Większy zakres ruchu niż przy sztandze, opuszczaj nieco głębiej, by maksymalnie rozciągnąć klatkę.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle"},"Wyciskanie hantli (Lekki skos)":{steps:["Ustaw oparcie ławki pod kątem 15-30 stopni.","Połóż się z hantlami nad górną częścią klatki, łopatki ściągnięte.","Opuść hantle kontrolowanie do górnej partii klatki, łokcie lekko poniżej.","Wyciśnij hantle w górę po lekkim łuku, napinając górę klatki w szczycie."],proTip:"Niewielki skos akcentuje górę klatki bez przeniesienia obciążenia na barki, jak przy stromym kącie.",targetMuscles:["Górna część klatki piersiowej","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle"},"Wyciskanie sztangi na skosie":{steps:["Ustaw ławkę pod kątem 30-45 stopni, połóż się oczami pod gryfem.","Ściągnij łopatki, chwyć gryf nieco szerzej niż barki i zdejmij z asekuracji.","Opuść sztangę kontrolowanie do górnej części klatki, tuż pod obojczyki.","Wyciśnij sztangę w górę po lekko skośnej linii do pełnego wyprostu."],proTip:"Nie ustawiaj kąta zbyt stromo (max 45 stopni), inaczej pracę przejmą barki zamiast górnej klatki.",targetMuscles:["Górna część klatki piersiowej","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Sztanga olimpijska"},"Rozpiętki hantlami":{steps:["Połóż się na ławce płaskiej z hantlami wyciśniętymi nad klatką, dłonie zwrócone do siebie.","Lekko ugnij łokcie i utrzymaj ten kąt przez cały ruch.","Rozłóż ramiona szeroko na boki po łuku, aż poczujesz rozciągnięcie klatki.","Zbliż hantle z powrotem nad klatką, ściskając mięśnie piersiowe."],proTip:"Łokcie trzymaj stale lekko ugięte, ruch ma odbywać się w stawach barkowych, a nie łokciowych.",targetMuscles:["Klatka piersiowa","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle"},"Rozpiętki na lince (Crossover)":{steps:["Ustaw uchwyty wyciągów wysoko, chwyć je i zrób krok do przodu w lekkim wykroku.","Pochyl lekko tułów, ramiona rozłożone na boki z lekko ugiętymi łokciami.","Ściągnij uchwyty po łuku w dół i do środka, krzyżując dłonie przed sobą.","Powoli wróć do rozciągnięcia, kontrolując opór linki."],proTip:"W końcowej fazie zatrzymaj się na chwilę i mocno napnij klatkę, linka daje stałe napięcie w całym zakresie.",targetMuscles:["Klatka piersiowa","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Wyciąg/linka"},Pompki:{steps:["Przyjmij podpór przodem, dłonie nieco szerzej niż barki, ciało w jednej linii.","Napnij brzuch i pośladki, łopatki lekko ściągnięte.","Opuść tułów kontrolowanie, łokcie pod kątem ok. 45 stopni do tułowia.","Wypchnij ciało w górę do wyprostu ramion, utrzymując napięty korpus."],proTip:"Nie pozwól, by biodra opadały ani wypinały się w górę, ciało ma tworzyć prostą linię od głowy do pięt.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków","Mięśnie brzucha"],primaryMuscle:"chest",equipment:"Masa ciała"},"Wyciskanie w maszynie":{steps:["Ustaw wysokość siedziska tak, by uchwyty były na wysokości środka klatki.","Usiądź, oprzyj plecy, ściągnij łopatki i chwyć uchwyty.","Wypchnij uchwyty do przodu do niemal pełnego wyprostu ramion.","Wróć kontrolowanie, nie pozwalając ciężarowi pociągnąć ramion za bardzo do tyłu."],proTip:"Nie blokuj sztywno łokci w szczycie i nie odrywaj pleców od oparcia, utrzymaj stałe napięcie klatki.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Maszyna"},"Wiosłowanie sztangą":{steps:["Stań w rozkroku, chwyć sztangę nachwytem nieco szerzej niż barki.","Pochyl tułów do ok. 45 stopni, plecy proste, biodra cofnięte.","Przyciągnij sztangę do dolnej części brzucha, ściągając łopatki.","Opuść sztangę kontrolowanie do pełnego rozciągnięcia pleców."],proTip:"Trzymaj plecy stale neutralne i prowadź ruch łokciami, nie szarpiąc ciężaru rozpędem tułowia.",targetMuscles:["Najszersze grzbietu","Mięśnie czworoboczne","Tylne aktony barków","Biceps"],primaryMuscle:"back",equipment:"Sztanga olimpijska"},"Wiosłowanie hantlami na ławce (przodem)":{steps:["Połóż się brzuchem na ławce skośnej ustawionej pod kątem ok. 30-45 stopni.","Trzymaj hantle zwisające swobodnie w dół, dłonie zwrócone do siebie.","Przyciągnij hantle do boków tułowia, ściągając łopatki.","Opuść hantle kontrolowanie do pełnego rozciągnięcia."],proTip:"Oparcie na ławce eliminuje pomaganie tułowiem, dzięki czemu cała praca przypada na mięśnie grzbietu.",targetMuscles:["Najszersze grzbietu","Mięśnie czworoboczne","Tylne aktony barków","Biceps"],primaryMuscle:"back",equipment:"Hantle"},"Wiosłowanie hantlem jednorącz (Laty)":{steps:["Oprzyj kolano i dłoń jednej strony na ławce, druga noga na podłodze.","Chwyć hantel drugą ręką, ramię zwisa swobodnie w dół, plecy proste.","Przyciągnij hantel do biodra, prowadząc łokieć blisko tułowia i ściągając łopatkę.","Opuść hantel kontrolowanie do pełnego rozciągnięcia najszerszego."],proTip:"Nie rotuj tułowia, by podrzucić ciężar, izoluj jedną stronę pleców i czuj pracę najszerszego.",targetMuscles:["Najszerszy grzbietu","Mięśnie czworoboczne","Tylne aktony barków","Biceps"],primaryMuscle:"back",equipment:"Hantle"},"Ściąganie drążka (Szeroki nachwyt)":{steps:["Usiądź przy wyciągu, ustaw wałki na udach, chwyć drążek szeroko nachwytem.","Wyprostuj tułów, lekko odchyl klatkę, ściągnij łopatki w dół.","Ściągnij drążek do górnej części klatki, prowadząc łokcie w dół.","Wróć kontrolowanie do pełnego wyprostu ramion i rozciągnięcia."],proTip:"Inicjuj ruch ściągnięciem łopatek, a nie zginaniem rąk, to angażuje najszersze, a nie biceps.",targetMuscles:["Najszersze grzbietu","Mięśnie obłe","Biceps","Tylne aktony barków"],primaryMuscle:"back",equipment:"Maszyna"},"Ściąganie drążka (Wąski nachwyt)":{steps:["Usiądź przy wyciągu, zablokuj uda wałkami, chwyć uchwyt wąsko (V-grip lub wąsko nachwytem).","Wyprostuj tułów, lekko odchyl klatkę do tyłu, ściągnij łopatki.","Ściągnij uchwyt do górnej części klatki, prowadząc łokcie blisko tułowia.","Wróć kontrolowanie do pełnego wyprostu ramion."],proTip:"Wąski chwyt zwiększa zakres ruchu i akcentuje dolną część najszerszych, pracuj pełną amplitudą.",targetMuscles:["Najszersze grzbietu","Mięśnie obłe","Biceps","Mięśnie czworoboczne"],primaryMuscle:"back",equipment:"Maszyna"},"Podciąganie na drążku":{steps:["Chwyć drążek nachwytem nieco szerzej niż barki, zwiśnij z wyprostowanymi ramionami.","Napnij brzuch, ściągnij łopatki w dół, lekko odchyl klatkę.","Podciągnij się, prowadząc łokcie w dół, aż broda minie drążek.","Opuść się kontrolowanie do pełnego zwisu."],proTip:"Unikaj bujania ciałem, kontroluj zwłaszcza fazę negatywną, by maksymalnie zaangażować najszersze.",targetMuscles:["Najszersze grzbietu","Mięśnie obłe","Biceps","Mięśnie brzucha"],primaryMuscle:"back",equipment:"Drążek"},"Wiosłowanie na lince siedząc":{steps:["Usiądź przy wyciągu dolnym, oprzyj stopy o podpórki, kolana lekko ugięte.","Chwyć uchwyt, wyprostuj plecy, lekko napięte w odcinku lędźwiowym.","Przyciągnij uchwyt do brzucha, ściągając łopatki i prowadząc łokcie blisko tułowia.","Wróć kontrolowanie, pozwalając łopatkom rozsunąć się bez garbienia pleców."],proTip:"Nie odchylaj mocno tułowia ani nie szarp rozpędem, ruch ma napędzać grzbiet, a nie biodra.",targetMuscles:["Najszersze grzbietu","Mięśnie czworoboczne","Tylne aktony barków","Biceps"],primaryMuscle:"back",equipment:"Wyciąg/linka"},"Pullover na lince":{steps:["Stań przodem do wyciągu górnego, chwyć drążek lub linkę nachwytem, ramiona lekko ugięte.","Pochyl lekko tułów, napnij brzuch, ustaw ramiona w górze przed sobą.","Ściągnij drążek łukiem w dół do ud, trzymając ramiona niemal proste.","Wróć kontrolowanie do góry, czując rozciągnięcie najszerszych."],proTip:"Utrzymuj stały, lekki kąt w łokciach, ruch wykonuj w barkach, by izolować najszersze grzbietu.",targetMuscles:["Najszersze grzbietu","Mięśnie obłe","Klatka piersiowa","Triceps"],primaryMuscle:"back",equipment:"Wyciąg/linka"},"Wyciskanie hantli nad głowę (Siedząc)":{steps:["Usiądź na ławce z pionowym oparciem, hantle na wysokości barków, dłonie do przodu.","Napnij brzuch, plecy oparte, łokcie pod hantlami.","Wyciśnij hantle nad głowę do niemal pełnego wyprostu ramion.","Opuść hantle kontrolowanie do wysokości barków."],proTip:"Nie wyginaj nadmiernie odcinka lędźwiowego, napnij brzuch i pośladki, by ustabilizować tułów.",targetMuscles:["Aktony barków","Triceps","Mięśnie czworoboczne"],primaryMuscle:"shoulders",equipment:"Hantle"},"Wyciskanie sztangi nad głowę (OHP)":{steps:["Stań w rozkroku na szerokość bioder, chwyć sztangę nieco szerzej niż barki, gryf na wysokości obojczyków.","Napnij brzuch i pośladki, łokcie skierowane do przodu i lekko pod gryf.","Wyciśnij sztangę pionowo nad głowę, lekko cofając głowę z linii ruchu.","Po minięciu czoła wsuń głowę do przodu i zablokuj sztangę nad głową, potem opuść kontrolowanie."],proTip:"Prowadź sztangę po linii prostej nad środkiem stóp i utrzymuj napięty korpus bez odchylania tułowia.",targetMuscles:["Aktony barków","Triceps","Mięśnie czworoboczne","Mięśnie brzucha"],primaryMuscle:"shoulders",equipment:"Sztanga olimpijska"},"Wznosy bokiem (Lateral Raise)":{steps:["Stań prosto z hantlami po bokach ciała, dłonie zwrócone do siebie, łokcie lekko ugięte.","Napnij brzuch, lekko pochyl tułów do przodu.","Unieś ramiona na boki do wysokości barków, prowadząc łokcie nieco wyżej niż dłonie.","Opuść hantle kontrolowanie do bioder."],proTip:"Wyobraź sobie, że nalewasz wodę z dzbanka (lekka rotacja małym palcem w górę), by trafić w boczny akton.",targetMuscles:["Boczne aktony barków","Mięśnie czworoboczne"],primaryMuscle:"shoulders",equipment:"Hantle"},"Wznosy bokiem leżąc (Y-Raise)":{steps:["Połóż się brzuchem na ławce skośnej ustawionej pod kątem ok. 30 stopni.","Trzymaj hantle zwisające w dół, kciuki skierowane w górę.","Unieś ramiona w górę i lekko na boki, tworząc kształt litery Y.","Opuść hantle kontrolowanie do pozycji wyjściowej."],proTip:"Używaj lekkiego ciężaru i kciuków w górę, by celować w tylne i boczne aktony oraz dolny czworoboczny.",targetMuscles:["Tylne aktony barków","Boczne aktony barków","Mięśnie czworoboczne"],primaryMuscle:"shoulders",equipment:"Hantle"},"Odwrotne rozpiętki (Tył barku)":{steps:["Usiądź na końcu ławki lub stań w opadzie tułowia, hantle zwisające w dół.","Pochyl tułów do przodu, plecy proste, łokcie lekko ugięte.","Rozłóż ramiona szeroko na boki, ściągając łopatki i unosząc hantle do wysokości barków.","Opuść hantle kontrolowanie do pozycji wyjściowej."],proTip:"Prowadź ruch łokciami, a nie dłońmi, i nie ściągaj mocno łopatek, by izolować tylne aktony barków.",targetMuscles:["Tylne aktony barków","Mięśnie czworoboczne","Mięśnie równoległoboczne"],primaryMuscle:"shoulders",equipment:"Hantle"},"Face Pull":{steps:["Ustaw wyciąg z liną na wysokości twarzy, chwyć oba końce liny chwytem neutralnym.","Zrób krok do tyłu, ramiona wyprostowane, lekko pochyl tułów.","Przyciągnij linę do twarzy, rozdzielając końce na boki głowy, łokcie wysoko.","Wróć kontrolowanie do wyprostu ramion."],proTip:"Prowadź łokcie wysoko i rozciągnij linę na poziomie uszu, to maksymalnie angażuje tylne aktony i rotatory.",targetMuscles:["Tylne aktony barków","Mięśnie czworoboczne","Rotatory zewnętrzne barku"],primaryMuscle:"shoulders",equipment:"Wyciąg/linka"},Arnoldki:{steps:["Usiądź na ławce z oparciem, hantle przed barkami, dłonie zwrócone do siebie.","Wyciskając hantle w górę, obracaj nadgarstki tak, by na końcu dłonie były zwrócone do przodu.","Wyciśnij hantle nad głowę do niemal pełnego wyprostu ramion.","Opuść hantle, obracając nadgarstki z powrotem do pozycji wyjściowej."],proTip:"Płynnie łącz rotację z wyciskaniem, dzięki obrotowi pracują wszystkie trzy aktony barków.",targetMuscles:["Aktony barków","Triceps","Mięśnie czworoboczne"],primaryMuscle:"shoulders",equipment:"Hantle"},"Przysiad ze sztangą (High Bar)":{steps:["Ustaw sztangę na górnej części czworobocznych, chwyt nieco szerzej niż barki.","Zdejmij sztangę, ustaw stopy na szerokość barków, palce lekko na zewnątrz.","Schodź w dół, trzymając tułów wyprostowany, kolana podążają za palcami stóp.","Zejdź co najmniej do równoległości ud z podłożem i wypchnij się w górę przez pięty."],proTip:"Przy wariancie high bar trzymaj tułów bardziej pionowo, to mocniej angażuje czworogłowe ud.",targetMuscles:["Mięśnie czworogłowe ud","Pośladki","Mięśnie dwugłowe ud","Mięśnie brzucha"],primaryMuscle:"quads",equipment:"Sztanga olimpijska"},"Przysiad ze sztangą (Low Bar)":{steps:["Ułóż sztangę niżej, na tylnych aktonach barków, chwyt mocny, łokcie pod gryfem.","Zdejmij sztangę, ustaw stopy nieco szerzej, palce na zewnątrz.","Cofaj biodra do tyłu, pochylając tułów bardziej do przodu, schodź w dół.","Zejdź do równoległości i wypchnij się w górę przez pięty, prowadząc biodra do przodu."],proTip:"Wariant low bar pozwala użyć większego ciężaru, ale wymaga większego pochylenia tułowia, akcentuje pośladki i dwugłowe.",targetMuscles:["Pośladki","Mięśnie dwugłowe ud","Mięśnie czworogłowe ud","Prostowniki grzbietu"],primaryMuscle:"quads",equipment:"Sztanga olimpijska"},"Przysiad goblet":{steps:["Chwyć hantel lub kettlebell pionowo, trzymając go oburącz przy klatce piersiowej.","Stań w rozkroku nieco szerszym niż barki, palce lekko na zewnątrz.","Schodź w dół, trzymając tułów wyprostowany, łokcie między kolanami.","Zejdź głęboko i wypchnij się w górę przez pięty do wyprostu."],proTip:"Ciężar z przodu pomaga utrzymać pionowy tułów, świetne na naukę głębokiego, czystego przysiadu.",targetMuscles:["Mięśnie czworogłowe ud","Pośladki","Mięśnie brzucha","Mięśnie dwugłowe ud"],primaryMuscle:"quads",equipment:"Hantle"},"Prasa nożna":{steps:["Usiądź na maszynie, oprzyj plecy i biodra, stopy ustaw na platformie na szerokość barków.","Zwolnij blokady, ugnij kolana, opuszczając platformę kontrolowanie.","Zejdź do kąta ok. 90 stopni w kolanach, nie odrywając bioder od oparcia.","Wypchnij platformę w górę przez całe stopy, nie blokując sztywno kolan."],proTip:"Nie prostuj kolan gwałtownie do pełnego zablokowania; zachowaj kontrolę w górnej fazie ruchu.",targetMuscles:["Mięśnie czworogłowe ud","Pośladki","Mięśnie dwugłowe ud"],primaryMuscle:"quads",equipment:"Maszyna"},"Wyprosty nóg na maszynie":{steps:["Usiądź na maszynie, oprzyj plecy, wałek ustaw nad kostkami.","Chwyć uchwyty, dosuń biodra do oparcia.","Wyprostuj nogi w kolanach, unosząc wałek do pełnego wyprostu.","Opuść wałek kontrolowanie do pozycji wyjściowej."],proTip:"Na szczycie wyprostu zatrzymaj się na chwilę i napnij czworogłowe, nie szarpiąc ruchu opadania.",targetMuscles:["Mięśnie czworogłowe ud"],primaryMuscle:"quads",equipment:"Maszyna"},"Wykroki chodzone":{steps:["Stań prosto z hantlami po bokach lub sztangą na barkach, stopy na szerokość bioder.","Zrób krok do przodu i opuść biodra, zginając oba kolana do ok. 90 stopni.","Odepchnij się przednią nogą i przejdź wykrokiem na drugą nogę.","Kontynuuj naprzemiennie, utrzymując wyprostowany tułów."],proTip:"Trzymaj przednie kolano nad kostką, a nie wysuwaj go za palce, i utrzymuj tułów pionowo.",targetMuscles:["Mięśnie czworogłowe ud","Pośladki","Mięśnie dwugłowe ud","Mięśnie brzucha"],primaryMuscle:"quads",equipment:"Hantle"},"Wykroki bułgarskie":{steps:["Stań tyłem do ławki, oprzyj na niej grzbiet jednej stopy, hantle po bokach.","Druga noga wykroczna ustawiona z przodu, tułów lekko pochylony.","Opuść biodra w dół, zginając przednie kolano do ok. 90 stopni.","Wypchnij się w górę przez piętę przedniej nogi do wyprostu."],proTip:"Ustaw przednią stopę odpowiednio daleko, by kolano nie wychodziło mocno za palce, mocniej zaangażujesz pośladek.",targetMuscles:["Mięśnie czworogłowe ud","Pośladki","Mięśnie dwugłowe ud"],primaryMuscle:"quads",equipment:"Hantle"},"Martwy Ciąg Rumuński (RDL)":{steps:["Stań ze sztangą trzymaną nachwytem na wysokości bioder, stopy na szerokość bioder.","Lekko ugnij kolana i utrzymaj ten kąt przez cały ruch.","Cofaj biodra do tyłu, opuszczając sztangę wzdłuż nóg, plecy proste.","Zejdź do odczucia rozciągnięcia dwugłowych ud, potem wróć, wypychając biodra do przodu."],proTip:"Prowadź ruch z bioder (hip hinge), nie z kolan, i trzymaj sztangę blisko nóg przez cały zakres.",targetMuscles:["Mięśnie dwugłowe ud","Pośladki","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Sztanga olimpijska"},"Martwy ciąg klasyczny":{steps:["Stań tuż przy sztandze, stopy na szerokość bioder, gryf nad środkiem stóp.","Zegnij się w biodrach i kolanach, chwyć sztangę, plecy proste, klatka wypchnięta.","Napnij korpus i oderwij sztangę od ziemi, prowadząc ją blisko nóg.","Wyprostuj się w pełni, wypychając biodra do przodu, potem opuść sztangę kontrolowanie."],proTip:"Zacznij ruch od napięcia pleców i dociśnięcia stóp do podłoża, sztanga ma sunąć wzdłuż goleni, nie po łuku.",targetMuscles:["Pośladki","Mięśnie dwugłowe ud","Prostowniki grzbietu","Najszersze grzbietu"],primaryMuscle:"hamstrings",equipment:"Sztanga olimpijska"},"Uginanie nóg na maszynie (Siedząc)":{steps:["Usiądź na maszynie, oprzyj plecy, wałek dolny ustaw nad ścięgnami Achillesa.","Opuść wałek oporowy na uda, by ustabilizować nogi.","Zegnij kolana, ściągając wałek pod siebie do maksymalnego skurczu.","Wróć kontrolowanie do wyprostu nóg, nie blokując sztywno kolan."],proTip:"Na końcu zgięcia mocno napnij dwugłowe ud i kontroluj fazę negatywną, nie pozwól ciężarowi opaść swobodnie.",targetMuscles:["Mięśnie dwugłowe ud","Mięśnie łydek"],primaryMuscle:"hamstrings",equipment:"Maszyna"},"Uginanie nóg na maszynie (Leżąc)":{steps:["Połóż się brzuchem na maszynie, wałek ustaw nad ścięgnami Achillesa.","Chwyć uchwyty, biodra dociśnięte do leżanki.","Zegnij kolana, ściągając wałek w stronę pośladków do pełnego skurczu.","Opuść wałek kontrolowanie do niemal pełnego wyprostu nóg."],proTip:"Nie odrywaj bioder od leżanki podczas zginania; utrzymuj tułów nieruchomo przez całą serię.",targetMuscles:["Mięśnie dwugłowe ud","Mięśnie łydek"],primaryMuscle:"hamstrings",equipment:"Maszyna"},"Good Morning":{steps:["Ustaw sztangę na górnej części pleców jak do przysiadu, stopy na szerokość bioder.","Lekko ugnij kolana, napnij brzuch i plecy.","Cofaj biodra do tyłu, pochylając tułów do przodu z prostymi plecami.","Zejdź do odczucia rozciągnięcia dwugłowych ud, potem wróć, wypychając biodra do przodu."],proTip:"Używaj umiarkowanego ciężaru i prowadź ruch z bioder, plecy muszą pozostać sztywne i neutralne przez cały zakres.",targetMuscles:["Mięśnie dwugłowe ud","Pośladki","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Sztanga olimpijska"},"Hip Thrust (Wypychanie bioder)":{steps:["Oprzyj górną część pleców o ławkę, sztanga na biodrach (z podkładką), stopy na podłodze.","Ustaw stopy na szerokość bioder, pięty pod kolanami.","Wypchnij biodra w górę, napinając pośladki, aż tułów i uda będą w jednej linii.","Opuść biodra kontrolowanie do pozycji wyjściowej."],proTip:"W górnej pozycji mocno ściśnij pośladki i schowaj miednicę (podwiń ją), by uniknąć przeprostu lędźwi.",targetMuscles:["Pośladki","Mięśnie dwugłowe ud","Mięśnie czworogłowe ud"],primaryMuscle:"glutes",equipment:"Sztanga olimpijska"},"Hip Thrust ze sztangą":{steps:["Oprzyj górną część pleców o ławkę, sztangę połóż na biodrach (użyj poduszki).","Stopy ustaw na szerokość bioder, pięty pod kolanami.","Napnij pośladki i wypchnij biodra w górę aż tułów i uda będą w linii.","Zatrzymaj na szczycie, kontrolowanie opuść biodra."],proTip:"Na szczycie ruchu mocno zaciśnij pośladki i lekko podwiń miednicę, by uniknąć przeprostu lędźwi.",targetMuscles:["Pośladki","Dwugłowe uda","Mięśnie głębokie tułowia"],primaryMuscle:"glutes",equipment:"Sztanga olimpijska"},"Odwodzenie na lince":{steps:["Przypnij linkę z opaską do kostki, stań bokiem do wyciągu.","Złap się konstrukcji dla stabilizacji, ciężar przenieś na nogę wewnętrzną.","Odwiedź nogę roboczą na bok w kontrolowanym ruchu.","Powoli wróć do pozycji wyjściowej bez opuszczania napięcia."],proTip:"Prowadź ruch piętą i nie przekręcaj bioder, aby izolować odwodziciele pośladka.",targetMuscles:["Pośladek średni","Pośladek mały","Naprężacz powięzi szerokiej"],primaryMuscle:"glutes",equipment:"Wyciąg/linka"},"Glute Bridge":{steps:["Połóż się na plecach, ugnij kolana, stopy płasko na podłodze.","Ramiona wzdłuż ciała, dłonie do podłogi.","Napnij pośladki i unieś biodra aż tułów będzie w linii z udami.","Przytrzymaj sekundę na górze i kontrolowanie opuść."],proTip:"Nie odpychaj się palcami stóp, nacisk trzymaj na piętach, by aktywować pośladki zamiast czworogłowych.",targetMuscles:["Pośladki","Dwugłowe uda","Mięśnie głębokie tułowia"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Uginanie hantli z supinacją (Ławka skośna)":{steps:["Usiądź na ławce skośnej, ramiona zwisają swobodnie w dół.","Trzymaj hantle chwytem neutralnym, łokcie blisko tułowia.","Uginaj ramiona, obracając nadgarstki na zewnątrz (supinacja).","Ściśnij biceps na szczycie i powoli opuść, prostując ramię."],proTip:"Rozciągnięcie na ławce skośnej maksymalizuje pracę długiej głowy bicepsa, nie skracaj zakresu na dole.",targetMuscles:["Biceps","Ramienny","Ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie sztangi stojąc":{steps:["Stań prosto, chwyć sztangę podchwytem na szerokość barków.","Łokcie przyciśnij do tułowia, klatka wypchnięta.","Uginaj ramiona, podnosząc sztangę do barków bez bujania tułowiem.","Ściśnij biceps na górze i kontrolowanie opuść sztangę."],proTip:"Trzymaj łokcie nieruchomo przy żebrach, ruch tylko w stawie łokciowym, bez wspomagania biodrami.",targetMuscles:["Biceps","Ramienny","Przedramiona"],primaryMuscle:"biceps",equipment:"Sztanga olimpijska"},"Uginanie na lince (Hammer)":{steps:["Przypnij linkę z uchwytem (sznur) do dolnego wyciągu.","Stań prosto, chwyć uchwyt chwytem neutralnym, łokcie przy tułowiu.","Uginaj ramiona, podnosząc uchwyt do barków.","Ściśnij i kontrolowanie wróć, utrzymując stałe napięcie linki."],proTip:"Stałe napięcie wyciągu na całym zakresie mocno angażuje mięsień ramienny i ramienno-promieniowy.",targetMuscles:["Ramienno-promieniowy","Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Wyciąg/linka"},"Uginanie hantli hammer":{steps:["Stań prosto z hantlami w dłoniach, chwyt neutralny (kciuki w górę).","Łokcie przyciśnij do tułowia, ramiona swobodnie w dół.","Uginaj ramiona, podnosząc hantle bez obracania nadgarstków.","Ściśnij na szczycie i powoli opuść do wyprostu."],proTip:"Chwyt młotkowy przenosi obciążenie na ramienno-promieniowy, dlatego pogrubia przedramię i podramię.",targetMuscles:["Ramienno-promieniowy","Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Hantle"},"Wyprosty francuskie zza głowy":{steps:["Chwyć jeden hantel lub sztangielkę oburącz nad głową.","Łokcie skieruj do góry, blisko głowy, ramiona pionowo.","Opuść ciężar za głowę, zginając tylko łokcie.","Wyprostuj ramiona, napinając triceps na szczycie."],proTip:"Trzymaj łokcie wąsko i nieruchomo, by w pełni rozciągnąć i zaangażować długą głowę tricepsa.",targetMuscles:["Triceps","Mięśnie głębokie tułowia"],primaryMuscle:"triceps",equipment:"Hantle"},"Wyprosty na lince (Pushdown)":{steps:["Przypnij drążek lub sznur do górnego wyciągu.","Stań prosto, łokcie przyciśnij do tułowia.","Prostuj ramiona w dół aż do pełnego wyprostu.","Ściśnij triceps na dole i kontrolowanie wróć do zgięcia 90 stopni."],proTip:"Łokcie muszą zostać przyklejone do boków, wszelkie ich odsuwanie włącza mięśnie pleców i odbiera pracę tricepsom.",targetMuscles:["Triceps","Przedramiona"],primaryMuscle:"triceps",equipment:"Wyciąg/linka"},"Dips (pompki na poręczach)":{steps:["Chwyć poręcze i unieś ciało na wyprostowanych ramionach.","Tułów lekko pochylony do przodu, nogi ugięte.","Opuść ciało, zginając łokcie aż do kąta około 90 stopni.","Wypchnij się w górę do pełnego wyprostu ramion."],proTip:"Trzymaj tułów bardziej pionowo, by akcentować triceps, mocniejsze pochylenie przenosi pracę na klatkę.",targetMuscles:["Triceps","Klatka piersiowa","Barki przednie"],primaryMuscle:"triceps",equipment:"Masa ciała"},"Skull Crushers":{steps:["Połóż się na ławce płaskiej, chwyć sztangę łamaną nad klatką.","Ramiona pionowo, łokcie skierowane do sufitu.","Opuść ciężar w stronę czoła, zginając tylko łokcie.","Wyprostuj ramiona, napinając triceps, bez ruszania łokciami."],proTip:"Prowadź sztangę za głowę, a nie tylko do czoła, aby zachować napięcie tricepsa w dolnej fazie.",targetMuscles:["Triceps","Przedramiona"],primaryMuscle:"triceps",equipment:"Sztanga olimpijska"},"Dead Bug (Robak - Brzuch)":{steps:["Połóż się na plecach, ramiona wyprostuj pionowo nad barkami.","Unieś nogi, biodra i kolana zgięte pod kątem 90 stopni.","Dociśnij lędźwie do podłogi i opuszczaj przeciwną rękę i nogę.","Wróć do pozycji startowej i powtórz na drugą stronę."],proTip:"Lędźwie muszą być stale dociśnięte do podłogi, jeśli plecy się unoszą, zmniejsz zakres ruchu kończyn.",targetMuscles:["Mięśnie głębokie tułowia","Prosty brzucha","Poprzeczny brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},Plank:{steps:["Oprzyj się na przedramionach i palcach stóp.","Łokcie pod barkami, ciało w jednej linii od głowy do pięt.","Napnij brzuch i pośladki, nie unoś bioder ani ich nie opuszczaj.","Utrzymaj pozycję przez zadany czas, oddychając spokojnie."],proTip:"Aktywnie podwiń miednicę i napnij pośladki, nie pozwalając lędźwiom zapadać się w dół.",targetMuscles:["Mięśnie głębokie tułowia","Prosty brzucha","Barki"],primaryMuscle:"core",equipment:"Masa ciała"},"Ab Rollout":{steps:["Klęknij i chwyć kółko do ćwiczeń lub sztangę z talerzami.","Napnij brzuch, trzymaj plecy w neutralnej pozycji.","Wytaczaj kółko do przodu, wydłużając ciało nisko nad podłogą.","Napięciem brzucha przyciągnij kółko z powrotem do kolan."],proTip:"Wytaczaj się tylko tak daleko, jak utrzymasz napięty brzuch bez zapadania lędźwi w przeprost.",targetMuscles:["Prosty brzucha","Mięśnie głębokie tułowia","Najszerszy grzbietu"],primaryMuscle:"core",equipment:"Masa ciała"},"Unoszenie nóg w zwisie":{steps:["Zawiśnij na drążku chwytem nachwytnym, ramiona wyprostowane.","Napnij brzuch, unieruchom barki, nie bujaj ciałem.","Unoś nogi (proste lub ugięte) w stronę klatki.","Kontrolowanie opuść nogi bez rozhuśtania tułowia."],proTip:"Na szczycie podwiń miednicę i unieś biodra, by zaangażować dolny brzuch, a nie tylko zginacze bioder.",targetMuscles:["Prosty brzucha","Zginacze bioder","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Drążek"},"Skręty rosyjskie":{steps:["Usiądź, ugnij kolana, lekko odchyl tułów do tyłu.","Trzymaj ciężar lub dłonie złączone przed klatką.","Unieś stopy (lub trzymaj na podłodze dla łatwiejszej wersji).","Rotuj tułów na boki, dotykając ciężarem obok bioder."],proTip:"Rotuj całym tułowiem od kręgosłupa, a nie tylko ramionami, by realnie zaangażować mięśnie skośne.",targetMuscles:["Skośne brzucha","Prosty brzucha","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Hantle"},"Modlitewnik (Cable Crunch)":{steps:["Przypnij sznur do górnego wyciągu, klęknij twarzą do maszyny.","Chwyć sznur i przytrzymaj go przy głowie lub karku.","Spinaj brzuch, zwijając tułów w dół, łokcie ku kolanom.","Kontrolowanie wróć do wyprostu, utrzymując napięcie linki."],proTip:"Ruch ma pochodzić ze zwijania kręgosłupa (zbliżania żeber do bioder), a nie z opuszczania bioder.",targetMuscles:["Prosty brzucha","Skośne brzucha","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Wyciąg/linka"},"Reverse Crunch na ławce":{steps:["Połóż się na ławce, chwyć jej krawędź za głową dla stabilizacji.","Unieś nogi, biodra i kolana zgięte pod kątem 90 stopni.","Napięciem dolnego brzucha podwiń miednicę i przyciągnij kolana.","Kontrolowanie opuść biodra bez odrywania ich od ławki gwałtownie."],proTip:"Skup się na podwinięciu miednicy, a nie na pociąganiu kolan, by maksymalnie aktywować dolny brzuch.",targetMuscles:["Prosty brzucha","Zginacze bioder","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Masa ciała"},"Wspięcia na palce (Nogi proste)":{steps:["Stań na podwyższeniu palcami stóp, pięty zwisają w dół.","Nogi wyprostowane, tułów stabilny, trzymaj się dla równowagi.","Wspnij się jak najwyżej na palce, napinając łydki.","Powoli opuść pięty poniżej poziomu dla pełnego rozciągnięcia."],proTip:"Wykonuj pełen zakres z głębokim rozciągnięciem na dole, by w pełni zaangażować mięsień brzuchaty.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna"},"Wspięcia na palce siedząc":{steps:["Usiądź na maszynie, wałek oprzyj na dolnej części ud nad kolanami.","Stopy ustaw palcami na podeście, pięty w dole.","Wspnij się na palce, unosząc kolana wałkiem jak najwyżej.","Kontrolowanie opuść pięty poniżej poziomu, rozciągając łydki."],proTip:"Wersja siedząca z ugiętym kolanem akcentuje mięsień płaszczkowaty, rób wolne, kontrolowane powtórzenia.",targetMuscles:["Płaszczkowaty","Brzuchaty łydki"],primaryMuscle:"calves",equipment:"Maszyna"},"Wyciskanie na maszynie Hammer":{steps:["Usiądź na maszynie, plecy oprzyj o oparcie, uchwyty na wysokości klatki.","Stopy płasko na podłodze, łopatki ściągnięte.","Wypchnij uchwyty do przodu, prostując ramiona bez blokowania łokci.","Kontrolowanie wróć, czując rozciągnięcie klatki, bez odrywania pleców."],proTip:"Na szczycie lekko zbliż uchwyty do siebie i napnij klatkę, by zmaksymalizować skurcz mięśnia.",targetMuscles:["Klatka piersiowa","Triceps","Barki przednie"],primaryMuscle:"chest",equipment:"Maszyna"},"Pec Deck (Butterfly)":{steps:["Usiądź na maszynie, plecy przy oparciu, przedramiona na podkładkach.","Łokcie na wysokości barków, klatka wypchnięta.","Zwieraj ramiona do przodu, ściskając klatkę po środku.","Kontrolowanie rozłóż ramiona, czując rozciągnięcie, bez szarpania."],proTip:"Zatrzymaj się na sekundę w pełnym zwarciu i mocno napnij klatkę, by zwiększyć aktywację mięśnia.",targetMuscles:["Klatka piersiowa","Barki przednie"],primaryMuscle:"chest",equipment:"Maszyna"},"Otwieranie klatki hantlami":{steps:["Połóż się na ławce płaskiej z hantlami nad klatką, dłonie do siebie.","Lekko ugnij łokcie i utrzymaj to zgięcie przez cały ruch.","Opuszczaj hantle łukiem na boki aż poczujesz rozciągnięcie klatki.","Zwieraj ramiona łukiem w górę, ściskając klatkę na szczycie."],proTip:"Utrzymuj stałe lekkie zgięcie łokci, prostowanie ich zamienia rozpiętki w wyciskanie i obciąża stawy.",targetMuscles:["Klatka piersiowa","Barki przednie"],primaryMuscle:"chest",equipment:"Hantle"},"Wiosłowanie na maszynie (Hammer)":{steps:["Usiądź na maszynie, klatkę oprzyj o przednią podkładkę.","Chwyć uchwyty, ramiona wyprostowane, łopatki rozluźnione.","Pociągnij uchwyty do tułowia, ściągając łopatki do siebie.","Kontrolowanie wróć, pozwalając łopatkom wysunąć się do przodu."],proTip:"Inicjuj ruch ściągnięciem łopatek, a nie szarpnięciem rękami, by skupić pracę na mięśniach pleców.",targetMuscles:["Najszerszy grzbietu","Czworoboczny","Romboidalne"],primaryMuscle:"back",equipment:"Maszyna"},"Wiosłowanie T-bar":{steps:["Stań okrakiem nad gryfem T-bar, kolana lekko ugięte, plecy proste.","Chwyć uchwyt, pochyl tułów do przodu w biodrach.","Pociągnij ciężar do tułowia, ściągając łopatki.","Kontrolowanie opuść ciężar do pełnego rozciągnięcia pleców."],proTip:"Trzymaj plecy w neutralnej pozycji i napięty brzuch, nie zaokrąglaj lędźwi pod obciążeniem.",targetMuscles:["Najszerszy grzbietu","Czworoboczny","Romboidalne"],primaryMuscle:"back",equipment:"Sztanga olimpijska"},"Wiosłowanie Pendleya":{steps:["Stań nad sztangą, pochyl tułów do równoległości z podłogą.","Chwyć sztangę nachwytem szerzej niż barki, plecy proste.","Eksplozywnie pociągnij sztangę do dolnych żeber, ściągając łopatki.","Opuść sztangę z powrotem na podłogę po każdym powtórzeniu."],proTip:"Każde powtórzenie zaczynaj z martwego ciężaru na podłodze i trzymaj tułów nieruchomo, równolegle do ziemi.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Czworoboczny"],primaryMuscle:"back",equipment:"Sztanga olimpijska"},"Podciąganie na drążku podchwytem":{steps:["Chwyć drążek podchwytem na szerokość barków, zawiśnij.","Napnij brzuch, ściągnij łopatki w dół.","Podciągnij się, prowadząc klatkę w stronę drążka.","Kontrolowanie opuść ciało do pełnego wyprostu ramion."],proTip:"Prowadź łokcie w dół i do tyłu oraz ściągaj łopatki, by zaangażować plecy, a nie tylko bicepsy.",targetMuscles:["Najszerszy grzbietu","Biceps","Czworoboczny"],primaryMuscle:"back",equipment:"Drążek"},"Ściąganie linki prostymi ramionami":{steps:["Przypnij prosty drążek do górnego wyciągu, stań prosto.","Chwyć drążek nachwytem, ramiona prawie wyprostowane.","Pochyl lekko tułów, ściągaj drążek łukiem do ud.","Kontrolowanie wróć do góry, czując rozciągnięcie najszerszego."],proTip:"Trzymaj ramiona prawie proste przez cały ruch, zginanie łokci przenosi pracę z najszerszego na triceps.",targetMuscles:["Najszerszy grzbietu","Obły większy","Mięśnie głębokie tułowia"],primaryMuscle:"back",equipment:"Wyciąg/linka"},"Przenoszenie hantla za głowę":{steps:["Połóż się w poprzek ławki, oprzyj na niej tylko górną część pleców.","Chwyć jeden hantel oburącz nad klatką, łokcie lekko ugięte.","Opuszczaj hantel łukiem za głowę aż poczujesz rozciągnięcie.","Przyciągnij hantel z powrotem nad klatkę kontrolowanym łukiem."],proTip:"Ruch ma iść z barków po szerokim łuku, utrzymuj stałe lekkie zgięcie łokci i napięty brzuch.",targetMuscles:["Najszerszy grzbietu","Klatka piersiowa","Zębaty przedni"],primaryMuscle:"back",equipment:"Hantle"},"Szrugi ze sztangą":{steps:["Stań prosto, chwyć sztangę nachwytem na szerokość barków.","Ramiona wyprostowane, sztanga przed udami.","Unieś barki prosto do góry w stronę uszu.","Ściśnij kaptury na szczycie i kontrolowanie opuść barki."],proTip:"Ruszaj barkami prosto w górę i w dół, bez wykonywania nimi okręgów.",targetMuscles:["Czworoboczny","Dźwigacz łopatki"],primaryMuscle:"back",equipment:"Sztanga olimpijska"},"Szrugi z hantlami":{steps:["Stań prosto z hantlami w dłoniach po bokach ciała, chwyt neutralny.","Ramiona wyprostowane, barki rozluźnione w dół.","Unieś barki prosto do góry w stronę uszu.","Ściśnij kaptury na szczycie i powoli opuść hantle."],proTip:"Zatrzymaj się na sekundę na górze i mocno napnij kaptury, hantle pozwalają na większy zakres niż sztanga.",targetMuscles:["Czworoboczny","Dźwigacz łopatki"],primaryMuscle:"back",equipment:"Hantle"},"Prostowniki grzbietu (Hyperextensions)":{steps:["Ustaw biodra na podkładce ławki rzymskiej, stopy zablokowane.","Skrzyżuj ręce na klatce lub trzymaj talerz dla obciążenia.","Opuść tułów w dół, zginając się w biodrach z prostymi plecami.","Unieś tułów do linii z nogami, napinając prostowniki i pośladki."],proTip:"Nie przeprostowuj się powyżej linii ciała, zatrzymaj się gdy tułów jest w jednej linii z nogami.",targetMuscles:["Prostowniki grzbietu","Pośladki","Dwugłowe uda"],primaryMuscle:"back",equipment:"Maszyna"},"Wyciskanie nad głowę na maszynie":{steps:["Usiądź na maszynie, plecy oprzyj o oparcie, uchwyty na wysokości barków.","Chwyć uchwyty nachwytem, łokcie pod nadgarstkami.","Wypchnij uchwyty pionowo nad głowę bez blokowania łokci.","Kontrolowanie opuść uchwyty z powrotem na wysokość barków."],proTip:"Trzymaj brzuch napięty i nie odrywaj pleców od oparcia, by nie przenosić obciążenia na lędźwie.",targetMuscles:["Barki przednie","Barki boczne","Triceps"],primaryMuscle:"shoulders",equipment:"Maszyna"},"Wznosy bokiem na maszynie":{steps:["Usiądź na maszynie, przedramiona oprzyj o boczne podkładki.","Tułów wyprostowany, łokcie pod podkładkami.","Unieś ramiona na boki do wysokości barków.","Kontrolowanie opuść ramiona, nie pozwalając ciężarowi opaść swobodnie."],proTip:"Prowadź ruch łokciami, a nie dłońmi, i zatrzymaj się na wysokości barków, by izolować boczny akton barku.",targetMuscles:["Barki boczne","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Maszyna"},"Wznosy bokiem na wyciągu":{steps:["Stań bokiem do dolnego wyciągu, chwyć uchwyt dłonią od strony maszyny.","Ramię robocze przed ciałem, druga ręka trzyma konstrukcję.","Unieś ramię na bok do wysokości barku, łokieć lekko ugięty.","Kontrolowanie opuść ramię, utrzymując stałe napięcie linki."],proTip:"Stałe napięcie wyciągu utrzymuje pracę barku także na dole ruchu, czego nie daje wolny ciężar.",targetMuscles:["Barki boczne","Barki tylne"],primaryMuscle:"shoulders",equipment:"Wyciąg/linka"},"Wznosy bokiem na lince (zza pleców)":{steps:["Stań bokiem do dolnego wyciągu, linkę prowadź za plecami.","Chwyć uchwyt ręką dalszą od maszyny, ramię przy biodrze.","Unieś ramię na bok i lekko do tyłu do wysokości barku.","Kontrolowanie opuść ramię, czując napięcie w bocznym barku."],proTip:"Prowadzenie linki zza pleców zmienia tor ruchu i mocniej akcentuje boczny oraz tylny akton barku.",targetMuscles:["Barki boczne","Barki tylne","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Wyciąg/linka"},"Rotacje ramienia z gumą frontem":{steps:["Stań przodem do punktu zaczepu gumy na wysokości łokcia, chwyć gumę i przyciągnij łokieć do tułowia pod kątem 90 stopni.","Trzymając łokieć przy ciele, rotuj przedramię na zewnątrz, od linii środka ciała.","Zatrzymaj ruch w maksymalnym napięciu, czując pracę z tyłu barku.","Wróć kontrolowanie do pozycji wyjściowej, nie pozwalając gumie szarpnąć ramienia."],proTip:"Trzymaj zwinięty ręcznik między łokciem a tułowiem, by wymusić izolację rotatorów zamiast pomocy mięśnia naramiennego.",targetMuscles:["Mięśnie rotatorów (pierścień rotatorów)","Mięsień podgrzebieniowy","Tylny akton naramiennego"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Aniołki i demony":{steps:["Połóż się na brzuchu, ramiona wyprostowane nad głową w kształcie litery Y.","Unieś klatkę i ramiona, prowadząc ręce po łuku w dół do bioder (aniołek), ściągając łopatki.","Z powrotem przeprowadź ramiona po tym samym łuku nad głowę (demon), cały czas trzymając je nad podłożem.","Wykonuj ruch płynnie i kontrolowanie, utrzymując napięcie górnej części pleców."],proTip:"Kciuki kieruj do sufitu przez cały zakres, by zmaksymalizować rotację zewnętrzną i pracę dolnego czworobocznego.",targetMuscles:["Mięsień czworoboczny grzbietu","Mięśnie równoległoboczne","Tylny akton naramiennego"],primaryMuscle:"back",equipment:"Masa ciała"},"Wall Angel":{steps:["Stań tyłem do ściany, dotykając jej głową, górną częścią pleców i pośladkami, stopy lekko odsunięte.","Oprzyj o ścianę przedramiona i grzbiety dłoni, łokcie zgięte pod kątem 90 stopni.","Przesuwaj ramiona w górę po ścianie aż do wyprostu, nie odrywając nadgarstków ani łokci od ściany.","Wróć kontrolowanie w dół, ściągając łopatki w dół i do siebie."],proTip:"Utrzymuj dolne żebra ściągnięte i lędźwie blisko ściany, by ruch szedł z łopatek, a nie z odcinka lędźwiowego.",targetMuscles:["Mięsień czworoboczny grzbietu (część dolna)","Mięśnie równoległoboczne","Mięśnie rotatorów"],primaryMuscle:"back",equipment:"Masa ciała"},"Rozciąganie gumy nad głową":{steps:["Chwyć gumę oburącz szerzej niż na szerokość barków, ramiona wyprostowane nad głową.","Rozciągaj gumę na boki, opuszczając proste ramiona po łuku za głowę.","Zejdź na tyle, na ile pozwala mobilność barków, utrzymując ramiona wyprostowane.","Wróć kontrolowanie nad głowę, cały czas napinając gumę."],proTip:"Im węższy chwyt, tym większe rozciągnięcie barków, dobierz rozstaw rąk tak, by nie kompensować wygięciem w plecach.",targetMuscles:["Mięśnie naramienne","Mięśnie klatki piersiowej","Mięśnie rotatorów"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Hack Squat (maszyna)":{steps:["Wejdź na platformę maszyny, oprzyj plecy i barki o poduszki, stopy na szerokość bioder.","Zwolnij zabezpieczenia i opuść się kontrolowanie, zginając kolana do kąta około 90 stopni lub niżej.","Trzymaj plecy płasko przy oparciu, a pięty wciśnięte w platformę.","Wypchnij ciężar przez pięty z powrotem do wyprostu, nie blokując całkowicie kolan."],proTip:"Ustaw stopy wyżej na platformie, by mocniej zaangażować pośladki i dwugłowe, niżej, by przenieść akcent na czworogłowe.",targetMuscles:["Mięśnie czworogłowe uda","Mięśnie pośladkowe","Mięśnie dwugłowe uda"],primaryMuscle:"quads",equipment:"Maszyna"},"Wyciskanie jednonóż na suwnicy":{steps:["Usiądź w suwnicy i ustaw jedną stopę na środku platformy, drugą nogę odstaw poza platformę.","Zwolnij zabezpieczenia i opuść ciężar, zginając kolano roboczej nogi do kąta około 90 stopni.","Pilnuj, by kolano podążało za palcami stopy i nie zapadało się do środka.","Wypchnij platformę przez piętę do niemal pełnego wyprostu, nie blokując kolana."],proTip:"Ustaw stopę centralnie na platformie, by uniknąć przeciążenia kolana, i utrzymuj biodro stabilne, nie rotując miednicy.",targetMuscles:["Mięśnie czworogłowe uda","Mięśnie pośladkowe","Mięśnie dwugłowe uda"],primaryMuscle:"quads",equipment:"Suwnica Smitha"},"Sissy Squat":{steps:["Stań wyprostowany, przytrzymując się jedną ręką stabilnego punktu dla równowagi, stopy na szerokość bioder.","Unieś pięty i jednocześnie odchylaj tułów do tyłu, prowadząc kolana do przodu.","Opuszczaj się, aż tułów i uda utworzą jedną linię, trzymając biodra wyprostowane.","Napnij czworogłowe i wróć kontrolowanie do pionu, prostując kolana."],proTip:"Utrzymuj prostą linię od kolan przez biodra do barków, nie zginaj się w biodrach, by maksymalnie rozciągnąć czworogłowe.",targetMuscles:["Mięśnie czworogłowe uda","Mięśnie brzucha","Mięśnie zginacze bioder"],primaryMuscle:"quads",equipment:"Masa ciała"},"Przywodziciele na maszynie":{steps:["Usiądź na maszynie, oprzyj plecy i ułóż uda na zewnętrznej stronie wałków, kolana rozłożone na boki.","Chwyć uchwyty i ustabilizuj tułów na oparciu.","Ściskaj uda do siebie, pokonując opór ciężaru, aż wałki niemal się zetkną.","Wróć kontrolowanie do rozłożenia, czując rozciągnięcie po wewnętrznej stronie ud."],proTip:"Nie odbijaj na końcu rozciągnięcia, zatrzymaj na chwilę napięcie przy zwarciu ud, by lepiej zaangażować przywodziciele.",targetMuscles:["Mięśnie przywodziciele uda","Mięsień smukły"],primaryMuscle:"quads",equipment:"Maszyna"},"Cossack Squat":{steps:["Stań w szerokim rozkroku, stopy lekko skierowane na zewnątrz.","Przenieś ciężar na jedną nogę, głęboko zginając jej kolano, druga noga pozostaje wyprostowana.","Schodź nisko, trzymając piętę nogi roboczej na ziemi, a tułów wyprostowany.","Wypchnij się przez piętę z powrotem do rozkroku i powtórz na drugą stronę."],proTip:"Pozwól palcom wyprostowanej nogi unieść się do góry, by zwiększyć rozciągnięcie przywodzicieli i utrzymać równowagę.",targetMuscles:["Mięśnie czworogłowe uda","Mięśnie pośladkowe","Mięśnie przywodziciele uda"],primaryMuscle:"quads",equipment:"Masa ciała"},"Przysiady wykroczne":{steps:["Stań prosto, zrób krok w przód jedną nogą na długość wykroku.","Opuść biodra w dół, zginając oba kolana do kąta około 90 stopni, tylne kolano blisko podłoża.","Trzymaj tułów wyprostowany, a przednie kolano nad linią stopy.","Odepchnij się przednią piętą i wróć do pozycji stojącej, zmieniając nogę."],proTip:"Dobierz długość kroku tak, aby utrzymać stabilną stopę i prowadzić kolano zgodnie z kierunkiem palców.",targetMuscles:["Mięśnie czworogłowe uda","Mięśnie pośladkowe","Mięśnie dwugłowe uda"],primaryMuscle:"quads",equipment:"Masa ciała"},"Zakroki sprinterskie":{steps:["Stań prosto, przenieś ciężar na jedną nogę.","Wykonaj zakrok drugą nogą w tył, opuszczając biodra aż tylne kolano zbliży się do podłoża.","Trzymaj tułów lekko pochylony do przodu, jak w pozycji sprinterskiej, przednia goleń pionowa.","Dynamicznie odepchnij się przednią nogą i wróć do pozycji wyjściowej, unosząc kolano tylnej nogi w górę."],proTip:"Mocno akcentuj fazę odepchnięcia i uniesienia kolana, by aktywować pośladki i imitować ruch biegowy.",targetMuscles:["Mięśnie pośladkowe","Mięśnie czworogłowe uda","Mięśnie dwugłowe uda"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Wejścia bokiem na skrzynię":{steps:["Stań bokiem do skrzyni, postaw na niej całą stopę bliższej nogi.","Wypchnij się przez piętę nogi na skrzyni, wchodząc na górę i prostując biodro.","Wyprostuj się na skrzyni, kontrolując pozycję drugiej nogi.","Opuść się kontrolowanie z powrotem na podłoże i powtórz, nie odpychając się dolną nogą."],proTip:"Cały napęd ma pochodzić z nogi na skrzyni, nie wybijaj się dolną nogą, by maksymalnie obciążyć pośladek nogi roboczej.",targetMuscles:["Mięśnie pośladkowe","Mięśnie czworogłowe uda","Mięśnie odwodziciele bioder"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Odwodziciele na maszynie":{steps:["Usiądź na maszynie, ułóż uda po wewnętrznej stronie wałków, kolana razem.","Chwyć uchwyty i ustabilizuj plecy na oparciu.","Rozkładaj uda na boki, pokonując opór, aż do pełnego odwiedzenia.","Wróć kontrolowanie do złączenia kolan, nie pozwalając ciężarowi szarpnąć nóg."],proTip:"Lekkie pochylenie tułowia do przodu mocniej angażuje górną część mięśnia pośladkowego wielkiego.",targetMuscles:["Mięsień pośladkowy średni","Mięsień pośladkowy wielki","Mięsień naprężacz powięzi szerokiej"],primaryMuscle:"glutes",equipment:"Maszyna"},"Glute Kickback na wyciągu":{steps:["Zapnij linkę z opaską na kostce, stań przodem do wyciągu dolnego, przytrzymaj się ramy.","Lekko pochyl tułów do przodu i ustabilizuj biodra.","Odepchnij nogę do tyłu po łuku, prostując biodro i napinając pośladek na szczycie.","Wróć kontrolowanie do przodu, nie pozwalając ciężarowi pociągnąć nogi za daleko."],proTip:"Szczyt ruchu wynika z wyprostu biodra, nie z wyginania lędźwi, zatrzymaj na chwilę i ściśnij pośladek.",targetMuscles:["Mięśnie pośladkowe","Mięśnie dwugłowe uda"],primaryMuscle:"glutes",equipment:"Wyciąg/linka"},"Pull Through":{steps:["Stań przodem od wyciągu dolnego, przełóż linkę z uchwytem między nogami, chwyć ją oburącz.","Zrób krok do przodu, stopy na szerokość barków, lekko zegnij kolana.","Odeprz biodra do tyłu (hip hinge), pozwalając linie pociągnąć ręce w tył między nogi.","Wypchnij biodra do przodu, prostując się i napinając pośladki na końcu ruchu."],proTip:"To ruch zawiasowy z bioder, nie przysiad, ręce są tylko hakiem, cała praca pochodzi z wyprostu bioder.",targetMuscles:["Mięśnie pośladkowe","Mięśnie dwugłowe uda","Mięśnie prostowniki grzbietu"],primaryMuscle:"glutes",equipment:"Wyciąg/linka"},"Wyprosty biodra z gumą":{steps:["Zaczep gumę nisko i załóż pętlę wokół jednej kostki, stań przodem do punktu zaczepu.","Przytrzymaj się stabilnego punktu i ustabilizuj tułów.","Odepchnij obciążoną nogę do tyłu, prostując biodro i napinając pośladek.","Wróć kontrolowanie do przodu, utrzymując napięcie gumy przez cały zakres."],proTip:"Trzymaj tułów wyprostowany i nie wyginaj lędźwi, ruch ma iść wyłącznie z wyprostu stawu biodrowego.",targetMuscles:["Mięśnie pośladkowe","Mięśnie dwugłowe uda"],primaryMuscle:"glutes",equipment:"Guma oporowa"},"Uginanie na modlitewniku (Preacher)":{steps:["Usiądź przy modlitewniku, oprzyj tylną część ramion płasko o poduszkę.","Chwyć ciężar (sztangielkę lub uchwyt) z ramionami niemal wyprostowanymi.","Uginaj przedramię, przyciągając ciężar do barku, trzymając łokcie na poduszce.","Opuść kontrolowanie do niemal pełnego wyprostu, nie blokując stawu."],proTip:"Nie prostuj ramienia gwałtownie; kontroluj końcowy zakres ruchu i nie odbijaj ciężaru.",targetMuscles:["Mięsień dwugłowy ramienia","Mięsień ramienny","Mięsień ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Maszyna"},"Uginania ze sztangą na modlitewniku":{steps:["Usiądź przy modlitewniku, oprzyj ramiona płasko o poduszkę, chwyć sztangę podchwytem.","Wyprostuj ramiona niemal do końca, utrzymując łokcie na poduszce.","Uginaj przedramiona, przyciągając sztangę do barków pełnym napięciem bicepsów.","Opuść kontrolowanie sztangę do niemal pełnego wyprostu, nie odbijając w dolnej fazie."],proTip:"Trzymaj łokcie i barki dociśnięte do poduszki przez cały ruch, by wyeliminować pomoc obręczy barkowej.",targetMuscles:["Mięsień dwugłowy ramienia","Mięsień ramienny","Mięsień ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Sztanga olimpijska"},"Uginania łokci z hantlami stojąc":{steps:["Stań prosto, hantle w dłoniach wzdłuż tułowia, chwyt neutralny lub podchwyt.","Trzymając łokcie przy tułowiu, uginaj przedramiona, unosząc hantle do barków.","Na szczycie ruchu napnij bicepsy, opcjonalnie supinując nadgarstki.","Opuść kontrolowanie hantle do pełnego wyprostu ramion."],proTip:"Nie bujaj tułowiem, jeśli musisz zarzucać ciężar biodrami, dobierz lżejsze hantle i izoluj bicepsy.",targetMuscles:["Mięsień dwugłowy ramienia","Mięsień ramienny","Mięsień ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie na wyciągu dolnym":{steps:["Stań przodem do wyciągu dolnego, chwyć drążek lub uchwyt podchwytem.","Trzymaj łokcie przy tułowiu, ramiona niemal wyprostowane.","Uginaj przedramiona, przyciągając uchwyt do barków pełnym napięciem bicepsów.","Opuść kontrolowanie do wyprostu, utrzymując stałe napięcie linki."],proTip:"Wyciąg utrzymuje napięcie w każdej fazie, nie pozwól ciężarowi opaść swobodnie w fazie negatywnej.",targetMuscles:["Mięsień dwugłowy ramienia","Mięsień ramienny","Mięsień ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Wyciąg/linka"},"Uginanie na maszynie":{steps:["Usiądź na maszynie, oprzyj tylną część ramion o poduszkę, chwyć uchwyty podchwytem.","Ustaw siedzisko tak, by łokcie pokrywały się z osią obrotu maszyny.","Uginaj przedramiona, przyciągając uchwyty pełnym napięciem bicepsów.","Wróć kontrolowanie do niemal pełnego wyprostu, nie blokując stawów."],proTip:"Maszyna stabilizuje ramiona, więc skup się na pełnym napięciu na szczycie i wolnej fazie ekscentrycznej.",targetMuscles:["Mięsień dwugłowy ramienia","Mięsień ramienny"],primaryMuscle:"biceps",equipment:"Maszyna"},"Wyciskanie wąsko (Close-grip)":{steps:["Połóż się na ławce, chwyć sztangę nieco węziej niż szerokość barków.","Zdejmij sztangę i ustaw ją nad klatką z wyprostowanymi ramionami.","Opuść sztangę do dolnej części klatki, trzymając łokcie blisko tułowia.","Wypchnij sztangę do wyprostu, napinając tricepsy na szczycie."],proTip:"Nie zwężaj chwytu zbyt mocno; ustaw dłonie mniej więcej na szerokość barków i utrzymuj nadgarstki nad przedramionami.",targetMuscles:["Mięsień trójgłowy ramienia","Mięśnie klatki piersiowej","Przedni akton naramiennego"],primaryMuscle:"triceps",equipment:"Sztanga olimpijska"},"Francuskie wyciskanie sztangi leżąc":{steps:["Połóż się na ławce, chwyć sztangę (najlepiej łamaną) na szerokość barków, ramiona wyprostowane nad klatką.","Trzymając łokcie nieruchomo, zginaj przedramiona, opuszczając sztangę do czoła lub za głowę.","Zatrzymaj tuż nad czołem, czując rozciągnięcie tricepsów.","Wyprostuj ramiona, wypychając sztangę z powrotem nad klatkę."],proTip:"Łokcie trzymaj nieruchomo i lekko skierowane do tyłu, by maksymalnie rozciągnąć długą głowę tricepsa.",targetMuscles:["Mięsień trójgłowy ramienia"],primaryMuscle:"triceps",equipment:"Sztanga olimpijska"},"Wyciskanie hantla oburącz w klęku":{steps:["Uklęknij lub usiądź prosto, chwyć jeden hantel oburącz za górny talerz.","Unieś hantel nad głowę z wyprostowanymi ramionami.","Zginając łokcie, opuść hantel za głowę kontrolowanie, łokcie skierowane do góry.","Wyprostuj ramiona, wypychając hantel z powrotem nad głowę."],proTip:"Trzymaj łokcie blisko głowy i skierowane do przodu, by izolować tricepsy zamiast rozkładać ruch na barki.",targetMuscles:["Mięsień trójgłowy ramienia","Mięśnie brzucha"],primaryMuscle:"triceps",equipment:"Hantle"},"Triceps na maszynie":{steps:["Usiądź na maszynie, oprzyj plecy i ułóż ramiona zgodnie z osią obrotu.","Chwyć uchwyty, łokcie zgięte.","Prostuj ramiona, wypychając uchwyty pełnym napięciem tricepsów.","Wróć kontrolowanie do zgięcia, nie pozwalając ciężarowi opaść swobodnie."],proTip:"Pełen wyprost z krótkim napięciem na końcu maksymalizuje skurcz tricepsa, nie szarpaj fazy powrotnej.",targetMuscles:["Mięsień trójgłowy ramienia"],primaryMuscle:"triceps",equipment:"Maszyna"},"Kickback z hantlą":{steps:["Pochyl tułów do przodu, oprzyj się jedną ręką o ławkę, w drugiej trzymaj hantel.","Unieś łokieć do wysokości tułowia, ramię przyciśnięte do boku, przedramię w dół.","Prostuj przedramię do tyłu, aż całe ramię będzie wyprostowane i równoległe do podłoża.","Napnij triceps na szczycie i wróć kontrolowanie do zgięcia."],proTip:"Łokieć musi pozostać nieruchomy i wysoko, ruch wykonuje tylko przedramię, zatrzymaj na chwilę przy pełnym wyproście.",targetMuscles:["Mięsień trójgłowy ramienia","Tylny akton naramiennego"],primaryMuscle:"triceps",equipment:"Hantle"},"Brzuszki na maszynie":{steps:["Usiądź na maszynie, oprzyj plecy i chwyć uchwyty lub oprzyj klatkę o wałki.","Ustaw obciążenie i ustabilizuj biodra na siedzisku.","Spinaj mięśnie brzucha, zginając tułów do przodu w odcinku piersiowym.","Wróć kontrolowanie do pozycji wyjściowej, nie odpuszczając całkowicie napięcia."],proTip:"Ruch ma pochodzić ze zwijania kręgosłupa przez mięśnie brzucha, a nie z ciągnięcia ramionami uchwytów.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Maszyna"},"Pallof Press":{steps:["Stań bokiem do wyciągu na wysokości klatki, chwyć uchwyt oburącz przy mostku.","Ustaw stopy na szerokość barków, lekko ugnij kolana, napnij brzuch.","Wypchnij ręce prosto przed siebie, opierając się rotacji, którą wymusza linka.","Przytrzymaj wyprost przez chwilę, po czym wróć kontrolowanie uchwyt do klatki."],proTip:"Im dalej staniesz od wyciągu, tym większa siła rotacyjna, dobierz dystans tak, by tułów ani razu się nie obrócił.",targetMuscles:["Mięśnie skośne brzucha","Mięsień prosty brzucha","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Wyciąg/linka"},"Cable Woodchopper":{steps:["Ustaw wyciąg wysoko, stań bokiem i chwyć uchwyt oburącz nad jednym barkiem.","Ustaw stopy na szerokość barków, napnij brzuch.","Przeciągnij uchwyt po przekątnej w dół do przeciwnego biodra, rotując tułów i biodra.","Wróć kontrolowanie po tym samym torze w górę i powtórz, potem zmień stronę."],proTip:"Rotacja ma iść z tułowia i bioder, a ramiona pozostają wyprostowane, nie ciągnij ruchu samymi rękami.",targetMuscles:["Mięśnie skośne brzucha","Mięsień prosty brzucha","Mięśnie pośladkowe"],primaryMuscle:"core",equipment:"Wyciąg/linka"},"Mountain Climbers":{steps:["Przyjmij pozycję podporu przodem, dłonie pod barkami, ciało w jednej linii.","Napnij brzuch i przyciągnij jedno kolano dynamicznie w stronę klatki.","Szybko zmień nogi, przyciągając drugie kolano i odstawiając pierwsze.","Kontynuuj naprzemienne ruchy w równym tempie, utrzymując biodra nisko."],proTip:"Nie podnoś bioder do góry, trzymaj proste plecy i stabilny tułów, by praca szła z brzucha, a nie z bujania.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha","Mięśnie zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"Hollow Hold":{steps:["Połóż się na plecach, ramiona wyprostowane za głową, nogi wyprostowane.","Dociśnij dolny odcinek pleców do podłoża, napinając brzuch.","Unieś jednocześnie barki i nogi nad podłoże, tworząc kształt łódki.","Utrzymaj napięcie i pozycję przez założony czas, oddychając spokojnie."],proTip:"Lędźwie muszą cały czas dotykać podłoża, jeśli odstają, unieś nogi wyżej, by utrzymać brzuch w napięciu.",targetMuscles:["Mięsień prosty brzucha","Mięśnie głębokie tułowia","Mięśnie zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"Wspięcia na palce na suwnicy":{steps:["Ustaw barki pod gryfem suwnicy, przodami stóp stań na podwyższeniu, pięty w powietrzu.","Zdejmij sztangę z zaczepów i ustabilizuj tułów.","Opuść pięty maksymalnie w dół, rozciągając łydki.","Wspiąż się jak najwyżej na palce, napinając łydki na szczycie i wróć kontrolowanie."],proTip:"Wykonuj pełny zakres od głębokiego rozciągnięcia po maksymalne wspięcie, z krótką pauzą na górze.",targetMuscles:["Mięsień brzuchaty łydki","Mięsień płaszczkowaty"],primaryMuscle:"calves",equipment:"Suwnica Smitha"},"Wspięcia na maszynie stojąc":{steps:["Wejdź pod poduszki maszyny do łydek stojąc, przodami stóp na podeście, pięty w powietrzu.","Wyprostuj się, by poduszki spoczęły na barkach, tułów stabilny.","Opuść pięty w dół, czując pełne rozciągnięcie łydek.","Wspiąż się maksymalnie na palce, napinając łydki, i wróć kontrolowanie w dół."],proTip:"Nie skracaj zakresu ani nie odbijaj na dole, kontrolowana faza ekscentryczna buduje łydki najlepiej.",targetMuscles:["Mięsień brzuchaty łydki","Mięsień płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna"},"Donkey Calf Raise":{steps:["Pochyl tułów do przodu w biodrach, opierając ręce o stabilną podporę, przodami stóp na podeście.","Ustaw obciążenie nisko na biodrach (maszyna lub partner), pięty zwisają poza podest.","Opuść pięty w dół, rozciągając łydki do maksimum.","Wspiąż się na palce jak najwyżej, napinając łydki na szczycie i wróć kontrolowanie."],proTip:"Pochylenie tułowia rozciąga łydki w wydłużonej pozycji, utrzymuj kolana lekko ugięte i nieruchome przez cały ruch.",targetMuscles:["Mięsień brzuchaty łydki","Mięsień płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna"},"Wyciskanie sztangi na ławce ujemnej (deklina)":{steps:["Połóż się na ławce ustawionej na ujemnym kącie i zahacz nogi pod wałkami.","Chwyć sztangę nieco szerzej niż barki i zdejmij ją ze stojaka.","Opuść sztangę kontrolowanie do dolnej części klatki.","Wyciśnij sztangę w górę napinając dolne partie klatki."],proTip:"Prowadź łokcie pod kątem około 45 stopni do tułowia i kontroluj opuszczanie gryfu.",targetMuscles:["Dolna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Sztanga"},"Wyciskanie hantli na ławce ujemnej (deklina)":{steps:["Ustaw ławkę na ujemnym kącie i zabezpiecz nogi pod wałkami.","Połóż się trzymając hantle nad klatką, dłonie skierowane do siebie lub do przodu.","Opuść hantle na boki kontrolowanie do poziomu dolnej klatki.","Wyciśnij hantle w górę i ściśnij klatkę w górnej pozycji."],proTip:"Większy zakres ruchu niż przy sztandze: pozwól hantlom zejść głębiej dla lepszego rozciągnięcia.",targetMuscles:["Dolna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Hantle"},"Wyciskanie na Smith maszynie (ławka skośna)":{steps:["Ustaw ławkę skośną pod gryfem Smith maszyny tak, by gryf opadał na górną klatkę.","Chwyć gryf nieco szerzej niż barki i obróć go, by odblokować.","Opuść gryf kontrolowanie do górnej części klatki.","Wyciśnij gryf w górę po prowadnicy, nie blokując łokci."],proTip:"Prowadzony tor ogranicza potrzebę stabilizacji; przed serią ustaw ograniczniki na odpowiedniej wysokości.",targetMuscles:["Górna część klatki piersiowej","Przedni akton barku","Triceps"],primaryMuscle:"chest",equipment:"Maszyna Smith"},"Wyciskanie na Smith maszynie (ławka płaska)":{steps:["Ustaw płaską ławkę centralnie pod gryfem Smith maszyny.","Połóż się tak, by gryf opadał na środek klatki, chwyć nieco szerzej niż barki.","Odblokuj gryf i opuść go kontrolowanie do klatki.","Wyciśnij gryf w górę po prowadnicy, napinając klatkę."],proTip:"Przed serią ustaw ograniczniki na wysokości, która pozwala odłożyć gryf bez dociskania klatki.",targetMuscles:["Klatka piersiowa","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Maszyna Smith"},"Wyciskanie na maszynie Hammer (skos góra)":{steps:["Usiądź w maszynie Hammer ze skosem w górę, plecy oprzyj o oparcie.","Chwyć uchwyty na wysokości górnej klatki.","Wypchnij ramiona w górę i do przodu po łuku maszyny.","Wróć kontrolowanie do rozciągnięcia, nie odrywając łopatek."],proTip:"Pracuj jednorącz naprzemiennie, by wyrównać dysproporcje między stronami.",targetMuscles:["Górna część klatki piersiowej","Przedni akton barku","Triceps"],primaryMuscle:"chest",equipment:"Maszyna Hammer Strength"},"Wyciskanie na maszynie Hammer (skos dół)":{steps:["Usiądź w maszynie Hammer z deklinacją (uchwyty poniżej barków).","Chwyć uchwyty na wysokości dolnej klatki, łopatki ściągnięte.","Wypchnij ramiona w dół i do przodu po łuku maszyny.","Wróć kontrolowanie do pełnego rozciągnięcia dolnej klatki."],proTip:"Skup się na ściśnięciu dolnej klatki w końcowej fazie ruchu, robiąc krótką pauzę.",targetMuscles:["Dolna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Maszyna Hammer Strength"},"Dipy na poręczach (na klatkę)":{steps:["Chwyć poręcze i podnieś się na wyprostowane ramiona.","Pochyl tułów do przodu i lekko rozchyl łokcie na boki.","Opuść ciało aż barki znajdą się nieco poniżej łokci.","Wypchnij się w górę utrzymując pochylenie tułowia do przodu."],proTip:"Pochylenie tułowia do przodu przenosi pracę z tricepsa na dolną klatkę.",targetMuscles:["Dolna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Masa ciała"},"Dipy z obciążeniem (na klatkę)":{steps:["Zapnij pas z obciążeniem i wejdź na poręcze na wyprostowane ramiona.","Pochyl tułów do przodu, by zaakcentować klatkę.","Opuść ciało kontrolowanie aż do rozciągnięcia klatki.","Wypchnij się w górę bez pełnego blokowania łokci."],proTip:"Dodawaj obciążenie dopiero gdy robisz czysto 12+ powtórzeń z masą własną.",targetMuscles:["Dolna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Pas z obciążeniem"},"Rozpiętki na wyciągu z dołu (góra klatki)":{steps:["Ustaw oba ramiona wyciągu w dolnej pozycji i chwyć uchwyty.","Stań w lekkim rozkroku, jedna noga z przodu, lekko pochyl tułów.","Z lekko ugiętymi łokciami unieś ręce po łuku w górę i do siebie.","Ściśnij górną klatkę u góry i wróć kontrolowanie."],proTip:"Prowadź ręce ku górze (jak przy klaskaniu nad głową), by celować w obojczykową część klatki.",targetMuscles:["Górna część klatki piersiowej","Przedni akton barku"],primaryMuscle:"chest",equipment:"Wyciąg"},"Rozpiętki na wyciągu z góry (dół klatki)":{steps:["Ustaw oba ramiona wyciągu w górnej pozycji i chwyć uchwyty.","Stań w lekkim rozkroku z tułowiem lekko pochylonym do przodu.","Z lekko ugiętymi łokciami sprowadź ręce w dół i do siebie przed biodrami.","Ściśnij dolną klatkę i wróć kontrolowanie do rozciągnięcia."],proTip:"Skrzyżuj dłonie na końcu ruchu, by domknąć skurcz w dolnej części klatki.",targetMuscles:["Dolna część klatki piersiowej","Środkowa część klatki"],primaryMuscle:"chest",equipment:"Wyciąg"},"Wyciskanie na wyciągu stojąc (góra klatki)":{steps:["Ustaw ramiona wyciągu na wysokości klatki i chwyć oba uchwyty.","Stań w wykroku tyłem do maszyny, uchwyty przy klatce.","Wypchnij ręce do przodu i do siebie aż do wyprostu łokci.","Wróć kontrolowanie ściągając łopatki w pozycji wyjściowej."],proTip:"Stałe napięcie liny na całym zakresie daje świetny skurcz w pozycji końcowej.",targetMuscles:["Klatka piersiowa","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Wyciąg"},"Svend Press (ściskanie talerzy)":{steps:["Stań prosto i ściśnij dwa talerze (lub jeden) między wyprostowanymi dłońmi na wysokości klatki.","Mocno dociskaj talerze do siebie przez cały ruch.","Wypchnij talerze prosto przed siebie do wyprostu ramion.","Wróć powoli do klatki nie zmniejszając docisku dłoni."],proTip:"Im mocniej ściskasz talerze, tym silniej spinasz wewnętrzną część klatki.",targetMuscles:["Wewnętrzna część klatki piersiowej","Przedni akton barku"],primaryMuscle:"chest",equipment:"Talerz"},"Wyciskanie hantli wąsko (chwyt neutralny)":{steps:["Połóż się na płaskiej ławce z hantlami trzymanymi chwytem neutralnym, talerze dotykają się.","Mocno dociśnij hantle do siebie na środku klatki.","Opuść hantle do klatki nie rozdzielając ich.","Wyciśnij w górę cały czas ściskając hantle razem."],proTip:"Stały docisk hantli do siebie maksymalizuje napięcie wewnętrznej części klatki.",targetMuscles:["Wewnętrzna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Hantle"},"Rozpiętki gumą oporową stojąc":{steps:["Zaczep gumę za sobą na wysokości klatki i chwyć oba końce.","Stań w lekkim wykroku, ręce rozłożone na boki z lekko ugiętymi łokciami.","Sprowadź ręce po łuku do przodu i połącz je przed klatką.","Ściśnij klatkę i wróć kontrolowanie do rozciągnięcia."],proTip:"Guma daje rosnący opór, więc skurcz na końcu ruchu jest najmocniejszy: zatrzymaj się tam na sekundę.",targetMuscles:["Klatka piersiowa","Przedni akton barku"],primaryMuscle:"chest",equipment:"Guma oporowa"},"Pompki na podwyższeniu (nogi w górze)":{steps:["Oprzyj stopy na ławce lub podwyższeniu, dłonie na podłodze nieco szerzej niż barki.","Napnij brzuch i pośladki utrzymując ciało w linii prostej.","Opuść klatkę do podłogi zginając łokcie pod kątem ~45 stopni.","Wypchnij się w górę do wyprostu łokci."],proTip:"Im wyżej nogi, tym większy nacisk na górną klatkę i barki.",targetMuscles:["Górna część klatki piersiowej","Przedni akton barku","Triceps"],primaryMuscle:"chest",equipment:"Masa ciała"},"Pompki diamentowe":{steps:["Przyjmij pozycję podporu z dłońmi pod klatką, kciuki i palce wskazujące stykają się tworząc romb.","Napnij brzuch i utrzymaj ciało w jednej linii.","Opuść klatkę do dłoni trzymając łokcie blisko tułowia.","Wypchnij się w górę ściskając wewnętrzną klatkę i triceps."],proTip:"Trzymaj łokcie blisko ciała: szerokie rozchylenie przenosi pracę na barki i obciąża nadgarstki.",targetMuscles:["Wewnętrzna część klatki piersiowej","Triceps","Przedni akton barku"],primaryMuscle:"chest",equipment:"Masa ciała"},"Ściąganie drążka podchwytem (wąsko)":{steps:["Chwyć drążek podchwytem na szerokość barków i usiądź, blokując uda pod wałkami.","Wypnij klatkę, ściągnij łopatki i pociągnij drążek do górnej części klatki.","Zatrzymaj się na sekundę w skurczu, czując napięcie w plecach.","Kontrolowanie wyprostuj ramiona do pełnego rozciągnięcia najszerszych."],proTip:"Prowadź łokcie blisko tułowia, aby mocniej zaangażować dolną część najszerszych.",targetMuscles:["Najszerszy grzbietu","Biceps","Obły większy"],primaryMuscle:"back",equipment:"Wyciąg górny"},"Ściąganie drążka neutralnym chwytem":{steps:["Zaczep uchwyt V do wyciągu górnego i chwyć go neutralnym chwytem.","Usiądź, zablokuj uda i lekko odchyl tułów do tyłu.","Pociągnij uchwyt do mostka, prowadząc łokcie w dół i do tyłu.","Powoli wróć do pozycji wyjściowej, kontrolując ciężar."],proTip:"Neutralny chwyt zmienia ustawienie dłoni i angażuje grzbiet oraz mięśnie ramienne.",targetMuscles:["Najszerszy grzbietu","Obły większy","Ramienny"],primaryMuscle:"back",equipment:"Wyciąg górny z uchwytem V"},"Podciąganie wspomagane na maszynie":{steps:["Ustaw ciężar wspomagający i uklęknij lub stań na poduszce maszyny.","Chwyć górne uchwyty nachwytem na szerokość barków.","Podciągnij się, prowadząc klatkę do uchwytów i ściągając łopatki.","Opuść się kontrolowanie aż do pełnego wyprostu ramion."],proTip:"Stopniowo zmniejszaj wspomaganie, aby przejść do podciągania o masie ciała.",targetMuscles:["Najszerszy grzbietu","Biceps","Obły większy"],primaryMuscle:"back",equipment:"Maszyna do podciągania wspomaganego"},"Wiosłowanie T-bar wąskim chwytem (uchwyt V)":{steps:["Stań okrakiem nad gryfem T-bar i chwyć uchwyt V wąskim, neutralnym chwytem.","Pochyl tułów do około 45 stopni z prostymi plecami i lekko ugiętymi kolanami.","Pociągnij ciężar do brzucha, ściągając łopatki.","Opuść kontrolowanie do pełnego rozciągnięcia grzbietu."],proTip:"Trzymaj klatkę uniesioną przez cały ruch, aby nie zaokrąglać kręgosłupa.",targetMuscles:["Najszerszy grzbietu","Czworoboczny","Romboidalne"],primaryMuscle:"back",equipment:"Gryf T-bar z uchwytem V"},"Wiosłowanie na maszynie jednorącz (plate-loaded)":{steps:["Usiądź bokiem do maszyny i oprzyj klatkę o podpórkę.","Chwyć jeden uchwyt i pozwól ramieniu rozciągnąć grzbiet w przód.","Pociągnij uchwyt do biodra, prowadząc łokieć blisko ciała.","Powoli wróć, kontrolując rozciąganie, i powtórz na drugą stronę."],proTip:"Praca jednostronna wyrównuje dysproporcje siłowe między stronami pleców.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Tylny akton barku"],primaryMuscle:"back",equipment:"Maszyna Hammer Strength (plate-loaded)"},"Wiosłowanie w podporze na ławce skośnej (chest-supported)":{steps:["Ustaw ławkę na około 30-45 stopni i połóż się na niej klatką w dół.","Chwyć hantle, zwisające swobodnie pod barkami.","Pociągnij hantle do bioder, ściągając łopatki.","Opuść kontrolowanie do pełnego rozciągnięcia."],proTip:"Podparcie klatki eliminuje oszukiwanie biodrami i izoluje grzbiet.",targetMuscles:["Romboidalne","Najszerszy grzbietu","Czworoboczny"],primaryMuscle:"back",equipment:"Hantle + ławka skośna"},"Wiosłowanie Meadowsa":{steps:["Stań bokiem do końca sztangi w gnieździe landmine i przyjmij pochylenie w biodrach.","Chwyć koniec gryfu nachwytem, opierając wolną rękę na udzie.","Pociągnij koniec sztangi w górę i do biodra, prowadząc łokieć wysoko.","Opuść kontrolowanie do pełnego rozciągnięcia i powtórz."],proTip:"Wysoko prowadzony łokieć i mocne rozciągnięcie na dole maksymalizują pracę najszerszych.",targetMuscles:["Najszerszy grzbietu","Tylny akton barku","Czworoboczny"],primaryMuscle:"back",equipment:"Sztanga w gnieździe (landmine)"},"Martwy ciąg częściowy z podstawek (Rack Pull)":{steps:["Ustaw sztangę na podstawkach na wysokości tuż poniżej kolan.","Chwyć gryf na szerokość barków, klatka w górę, plecy proste.","Wyprostuj biodra i kolana, ciągnąc sztangę wzdłuż ud do pełnego wyprostu.","Opuść sztangę kontrolowanie z powrotem na podstawki."],proTip:"Skrócony zakres pozwala użyć dużego ciężaru i mocno obciążyć górny grzbiet.",targetMuscles:["Prostowniki grzbietu","Czworoboczny","Najszerszy grzbietu"],primaryMuscle:"back",equipment:"Sztanga + stojaki/podstawki"},"Wiosłowanie w maszynie Smitha":{steps:["Ustaw gryf Smitha na niskiej wysokości i chwyć go nachwytem szerzej niż barki.","Pochyl tułów do około 45 stopni, plecy proste, kolana lekko ugięte.","Odblokuj gryf i pociągnij go do dolnej części klatki, ściągając łopatki.","Opuść kontrolowanie do pełnego rozciągnięcia ramion."],proTip:"Stała tor gryfu pozwala skupić się na ściąganiu łopatek bez stabilizacji.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Czworoboczny"],primaryMuscle:"back",equipment:"Maszyna Smitha"},"Australijskie podciąganie (Inverted Row)":{steps:["Ustaw gryf na wysokości bioder i połóż się pod nim, chwytając go nachwytem.","Wyprostuj ciało w linii prostej, oparty na piętach.","Podciągnij klatkę do gryfu, ściągając łopatki.","Opuść się kontrolowanie do pełnego wyprostu ramion."],proTip:"Im niżej ustawisz gryf, tym trudniejsze ćwiczenie; reguluj kąt do swojego poziomu.",targetMuscles:["Romboidalne","Najszerszy grzbietu","Tylny akton barku"],primaryMuscle:"back",equipment:"Masa ciała + gryf na stojaku"},"Szrugi w maszynie Smitha":{steps:["Ustaw gryf Smitha na wysokości ud i chwyć go nachwytem na szerokość barków.","Stań prosto, ramiona wyprostowane, gryf przed udami.","Unieś barki prosto w górę w kierunku uszu, ściskając kapturowe na szczycie.","Opuść barki kontrolowanie do pełnego rozciągnięcia."],proTip:"Nie rotuj barkami; prowadź ruch wyłącznie pionowo i kontroluj opuszczanie.",targetMuscles:["Czworoboczny (górny)","Dźwigacz łopatki"],primaryMuscle:"back",equipment:"Maszyna Smitha"},"Szrugi na wyciągu":{steps:["Zaczep drążek do dolnego wyciągu i chwyć go nachwytem, stojąc blisko bloczka.","Stań prosto z lekko ugiętymi kolanami i wyprostowanymi ramionami.","Unieś barki w górę, ściskając czworoboczne na szczycie.","Opuść barki kontrolowanie, utrzymując stałe napięcie linki."],proTip:"Wyciąg utrzymuje napięcie w dolnej fazie, czego nie daje sztanga.",targetMuscles:["Czworoboczny (górny)","Dźwigacz łopatki"],primaryMuscle:"back",equipment:"Wyciąg dolny z drążkiem"},"Pullover na maszynie":{steps:["Usiądź w maszynie i ustaw oparcie tak, by ramiona spoczęły na wałkach.","Chwyć uchwyty i pozwól ramionom wyciągnąć się w górę za głowę.","Pociągnij wałki łukiem w dół do bioder, używając najszerszych.","Powoli wróć do rozciągnięcia, kontrolując ciężar."],proTip:"Inicjuj ruch łokciami i najszerszymi, nie zginaj nadmiernie nadgarstków.",targetMuscles:["Najszerszy grzbietu","Obły większy","Klatka piersiowa"],primaryMuscle:"back",equipment:"Maszyna do pulloveru (Nautilus)"},"Wiosłowanie na lince stojąc (Face Pull do twarzy)":{steps:["Ustaw linę na wyciągu na wysokości twarzy i chwyć oba końce neutralnie.","Cofnij się, by napiąć linkę, i stań w lekkim rozkroku.","Pociągnij linę do twarzy, rozdzielając końce i rotując ramiona na zewnątrz.","Powoli wróć do wyprostu ramion, kontrolując ciężar."],proTip:"Prowadź łokcie wysoko i rozdziel końce liny przy twarzy, utrzymując tułów nieruchomo.",targetMuscles:["Tylny akton barku","Czworoboczny (środkowy)","Romboidalne"],primaryMuscle:"back",equipment:"Wyciąg górny z liną"},"Martwy ciąg sumo (akcent na plecy)":{steps:["Stań w szerokim rozkroku, stopy skierowane na zewnątrz, sztanga nad śródstopiem.","Chwyć gryf wewnątrz kolan, klatka w górę, plecy proste.","Wepchnij stopy w podłogę i wyprostuj biodra oraz kolana jednocześnie.","Zablokuj na górze i opuść sztangę kontrolowanie wzdłuż nóg."],proTip:"Krótszy zakres względem klasyki mocno angażuje prostowniki i czworoboczne.",targetMuscles:["Prostowniki grzbietu","Czworoboczny","Pośladki"],primaryMuscle:"back",equipment:"Sztanga"},"Martwy ciąg z deficytu":{steps:["Stań na podwyższeniu 3-5 cm, sztanga nad śródstopiem.","Chwyć gryf na szerokość barków, schodząc niżej niż w klasyce, plecy proste.","Napnij grzbiet i wyprostuj biodra, ciągnąc sztangę wzdłuż nóg.","Zablokuj na górze i opuść kontrolowanie z powrotem na podłogę."],proTip:"Większy zakres ruchu wzmacnia start z dołu i napięcie prostowników.",targetMuscles:["Prostowniki grzbietu","Czworoboczny","Najszerszy grzbietu"],primaryMuscle:"back",equipment:"Sztanga + podwyższenie"},"Wymachy kettlebell (posterior chain)":{steps:["Stań w rozkroku z kettlebell na podłodze przed sobą.","Wykonaj zawias biodrowy, chwyć rączkę i odepchnij kettlebell między nogami.","Dynamicznie wyprostuj biodra, wyrzucając kettlebell do wysokości klatki.","Pozwól mu opaść z powrotem i płynnie przejdź do kolejnego powtórzenia."],proTip:"Napęd pochodzi z bioder, nie z ramion; ramiona tylko prowadzą kettlebell.",targetMuscles:["Prostowniki grzbietu","Pośladki","Dwugłowe uda"],primaryMuscle:"back",equipment:"Kettlebell"},"Wyciskanie barków na maszynie Hammer Strength (jednorącz)":{steps:["Usiądź w maszynie, ustaw wysokość siedziska tak, by uchwyty były na poziomie barków.","Złap jeden uchwyt, drugą rękę oprzyj na korpusie maszyny lub kolanie.","Wyciśnij ramię w górę do niemal pełnego wyprostu, nie blokując łokcia.","Powoli opuść uchwyt do pozycji startowej, kontrolując ruch.","Wykonaj wszystkie powtórzenia na jedną stronę, potem zmień ramię."],proTip:"Trening jednorącz wyrównuje dysproporcje siłowe między barkami i mocniej angażuje core do stabilizacji.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Triceps"],primaryMuscle:"shoulders",equipment:"Maszyna Hammer Strength"},"Wyciskanie nad głowę w Smith (Smith OHP)":{steps:["Ustaw ławkę lub stań pod gryfem maszyny Smith tak, by gryf był na wysokości obojczyków.","Chwyć gryf nieco szerzej niż barki, łokcie skierowane lekko do przodu.","Odbezpiecz gryf i wyciśnij go pionowo nad głowę do wyprostu ramion.","Opuść gryf kontrolowanie do poziomu brody.","Powtórz, trzymając tułów napięty i nie odchylając się nadmiernie do tyłu."],proTip:"Prowadzony tor ogranicza potrzebę balansowania; dobierz ciężar, przy którym utrzymasz tułów bez odchylania.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Triceps"],primaryMuscle:"shoulders",equipment:"Maszyna Smith"},"Odwrotne rozpiętki na maszynie (Reverse Pec Deck)":{steps:["Usiądź przodem do oparcia maszyny pec deck, klatka oparta o poduszkę.","Złap uchwyty na wysokości barków, ramiona wyprostowane przed sobą.","Odwiedź ramiona do tyłu szerokim łukiem, ściągając łopatki.","Zatrzymaj się w maksymalnym rozwarciu na sekundę.","Powoli wróć ramiona do przodu, kontrolując opór."],proTip:"Lekko ugięte łokcie i ruch z tylnej części barku, nie z łopatek, najlepiej izolują tylny akton.",targetMuscles:["Aktony tylne barku","Mięśnie równoległoboczne","Czworoboczny (dolny)"],primaryMuscle:"shoulders",equipment:"Maszyna Pec Deck"},"Wznosy bokiem jednorącz na wyciągu dolnym":{steps:["Ustaw rączkę wyciągu w najniższej pozycji i stań bokiem do maszyny.","Złap rączkę dłonią dalszą od wyciągu, ramię opuszczone przed udem.","Unieś ramię bokiem do wysokości barku, łokieć lekko ugięty.","Zatrzymaj na szczycie ruchu, czując napięcie w bocznym aktonie.","Opuść kontrolowanie i powtórz, potem zmień stronę."],proTip:"Wyciąg utrzymuje stałe napięcie w całym zakresie, czego nie dają hantle na dole ruchu.",targetMuscles:["Aktony boczne barku","Czworoboczny (góra)"],primaryMuscle:"shoulders",equipment:"Wyciąg"},"Podciąganie sztangi wzdłuż tułowia (Upright Row)":{steps:["Stań prosto, trzymając sztangę nachwytem na szerokość barków, ramiona wyprostowane.","Prowadź sztangę pionowo w górę wzdłuż tułowia, unosząc łokcie na boki.","Podciągnij gryf do wysokości mostka, łokcie wyżej niż dłonie.","Zatrzymaj na górze i powoli opuść sztangę.","Powtórz, trzymając gryf blisko ciała przez cały ruch."],proTip:"Nie podciągaj gryfu wyżej niż do mostka, by uniknąć konfliktu w stawie barkowym.",targetMuscles:["Aktony boczne barku","Czworoboczny (góra)","Aktony przednie barku"],primaryMuscle:"shoulders",equipment:"Sztanga"},"Podciąganie wzdłuż tułowia na wyciągu (Cable Upright Row)":{steps:["Podepnij prosty drążek do dolnego wyciągu i stań przodem do maszyny.","Chwyć drążek nachwytem na szerokość barków, ramiona wyprostowane.","Podciągnij drążek pionowo wzdłuż tułowia, unosząc łokcie na boki.","Doprowadź drążek do wysokości mostka, zatrzymaj na sekundę.","Opuść kontrolowanie i powtórz."],proTip:"Stałe napięcie wyciągu utrzymuje obciążenie na barkach nawet w dolnej fazie ruchu.",targetMuscles:["Aktony boczne barku","Czworoboczny (góra)","Aktony przednie barku"],primaryMuscle:"shoulders",equipment:"Wyciąg"},"Podciąganie hantli wzdłuż tułowia (Dumbbell Upright Row)":{steps:["Stań prosto, trzymając hantle nachwytem przed udami, dłonie blisko siebie.","Podciągnij hantle pionowo wzdłuż tułowia, prowadząc łokcie na boki i w górę.","Doprowadź hantle do wysokości górnej części klatki, łokcie wyżej niż dłonie.","Zatrzymaj na szczycie i powoli opuść hantle.","Powtórz, trzymając hantle blisko ciała."],proTip:"Hantle pozwalają niezależnie ustawić dłonie; prowadź łokcie bez unoszenia barków do uszu.",targetMuscles:["Aktony boczne barku","Czworoboczny (góra)","Aktony przednie barku"],primaryMuscle:"shoulders",equipment:"Hantle"},"Cuban Press (rotacja zewnętrzna z wyciskaniem)":{steps:["Stań prosto z hantlami, unieś łokcie na boki do wysokości barków (jak na początku upright row).","Z łokci jako osi obrotu wykonaj rotację zewnętrzną przedramion do góry.","Z tej pozycji wyciśnij hantle nad głowę do wyprostu ramion.","Odwróć ruch: opuść hantle, wykonaj rotację wewnętrzną i wróć do pozycji startowej.","Powtarzaj płynnie, używając umiarkowanego ciężaru."],proTip:"To świetne ćwiczenie wzmacniające stożek rotatorów, dlatego trzymaj lekki ciężar i pełną kontrolę.",targetMuscles:["Aktony tylne barku","Mięśnie stożka rotatorów","Aktony boczne barku"],primaryMuscle:"shoulders",equipment:"Hantle"},"Z-Press (wyciskanie siedząc na podłodze)":{steps:["Usiądź na podłodze z wyprostowanymi nogami rozstawionymi w literę V.","Wyciągnij sztangę z poziomu obojczyków, łokcie skierowane do przodu.","Trzymając tułów pionowo, wyciśnij sztangę nad głowę do wyprostu ramion.","Opuść sztangę kontrolowanie do wysokości brody.","Powtórz, nie odchylając się do tyłu i nie używając rozpędu nóg."],proTip:"Brak oparcia nóg zmusza core i barki do pełnej pracy, eliminując oszukiwanie biodrami.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Mięśnie core"],primaryMuscle:"shoulders",equipment:"Sztanga"},"Landmine Press (wyciskanie jednorącz)":{steps:["Zamocuj jeden koniec sztangi w landmine, drugi unieś i przytrzymaj przy barku.","Stań w lekkim rozkroku, trzymając koniec gryfu jedną ręką przy obojczyku.","Wyciśnij gryf po skosie w górę i do przodu, prostując ramię.","Powoli wróć gryf do barku, kontrolując ruch.","Wykonaj wszystkie powtórzenia, potem zmień rękę."],proTip:"Tor ruchu przebiega po skosie; utrzymuj stabilną łopatkę i nie przechylaj tułowia.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Mięśnie core","Triceps"],primaryMuscle:"shoulders",equipment:"Sztanga (landmine)"},"Pompki w pozycji szczytowej (Pike Push-up)":{steps:["Przyjmij pozycję podporu, a następnie unieś biodra wysoko, tworząc literę V (pozycja psa z głową w dół).","Dłonie ustaw nieco szerzej niż barki, nogi wyprostowane.","Zginając łokcie, opuść głowę w kierunku podłogi między dłońmi.","Gdy czubek głowy niemal dotknie podłogi, wyciśnij się z powrotem w górę.","Powtórz, utrzymując biodra wysoko przez cały ruch."],proTip:"Im wyżej biodra i bardziej pionowy tułów, tym większe obciążenie barków, to świetna progresja do handstand push-up.",targetMuscles:["Aktony przednie barku","Triceps","Górna część klatki"],primaryMuscle:"shoulders",equipment:"Masa ciała"},"Wyciskanie hantli neutralnym chwytem nad głowę":{steps:["Usiądź na ławce z oparciem, trzymając hantle na wysokości barków chwytem neutralnym (dłonie zwrócone do siebie).","Łokcie skieruj lekko do przodu, a nie maksymalnie na boki.","Wyciśnij hantle nad głowę, utrzymując dłonie zwrócone ku sobie przez cały ruch.","Wyprostuj ramiona bez blokowania łokci, potem powoli opuść hantle.","Powtórz, trzymając tułów napięty i oparty o ławkę."],proTip:"Chwyt neutralny zmienia ustawienie ramion; prowadź łokcie pod nadgarstkami i kontroluj opuszczanie.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Triceps"],primaryMuscle:"shoulders",equipment:"Hantle"},"Wznosy bokiem z gumą oporową":{steps:["Stań na środku gumy obiema stopami, trzymając jej końce w dłoniach przy udach.","Łokcie utrzymaj lekko ugięte, dłonie zwrócone do ud.","Unieś ramiona bokiem do wysokości barków, rozciągając gumę.","Zatrzymaj na szczycie ruchu na sekundę.","Powoli opuść ramiona, kontrolując powracającą gumę."],proTip:"Opór gumy rośnie wraz z zakresem, więc napięcie jest największe na szczycie, dokładnie tam gdzie boczny akton pracuje najmocniej.",targetMuscles:["Aktony boczne barku","Czworoboczny (góra)"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Wznosy sztangi w przód (Barbell Front Raise)":{steps:["Stań prosto, trzymając sztangę nachwytem na szerokość barków, gryf na udach.","Ramiona wyprostowane, łokcie minimalnie ugięte.","Unieś sztangę przed siebie do wysokości barków, prowadząc ruch z przednich aktonów.","Zatrzymaj na chwilę, gdy gryf jest na wysokości oczu/barków.","Powoli opuść sztangę do ud i powtórz bez bujania tułowiem."],proTip:"Nie wznoś gryfu wyżej niż do linii barków, by utrzymać napięcie na aktonie przednim, a nie przerzucić go na trapezy.",targetMuscles:["Aktony przednie barku","Górna część klatki"],primaryMuscle:"shoulders",equipment:"Sztanga"},"Wznosy krążka w przód (Plate Front Raise)":{steps:["Stań prosto, trzymając krążek obiema dłońmi za boki (na godzinie 3 i 9), ramiona opuszczone.","Łokcie utrzymaj lekko ugięte, krążek przed udami.","Unieś krążek przed siebie do wysokości oczu, prowadząc ruch z przednich aktonów.","Zatrzymaj na szczycie ruchu na sekundę.","Powoli opuść krążek do ud i powtórz, nie bujając tułowiem."],proTip:"Chwyt krążka na bokach angażuje też stabilizatory nadgarstka i pozwala precyzyjnie dawkować obciążenie.",targetMuscles:["Aktony przednie barku","Górna część klatki"],primaryMuscle:"shoulders",equipment:"Krążek obciążeniowy"},"Wznosy 6-kierunkowe (6-Way Raise)":{steps:["Stań prosto z lekkimi hantlami, ramiona opuszczone wzdłuż ciała.","Faza 1: unieś hantle bokiem do wysokości barków, potem przesuń ramiona do przodu (do wznosu frontalnego).","Faza 2: opuść hantle przed sobą do ud.","Faza 3: unieś hantle w przód do barków, potem rozłóż ramiona na boki.","Opuść hantle bokiem do ud, to jedno powtórzenie 6-kierunkowe; używaj bardzo lekkiego ciężaru."],proTip:"To kompleksowe ćwiczenie wykańczające wszystkie trzy aktony barku, dlatego ciężar musi być symboliczny.",targetMuscles:["Aktony przednie barku","Aktony boczne barku","Aktony tylne barku"],primaryMuscle:"shoulders",equipment:"Hantle"},"Przysiad przedni ze sztangą (Front Squat)":{steps:["Oprzyj sztangę na przednich aktonach barków, łokcie wysoko, chwyt na krzyż lub czysty.","Stopy na szerokość barków, klatka wysoko, napnij brzuch.","Schodź w dół trzymając tułów pionowo, kolana w linii palców.","Zejdź do równoległości ud lub niżej i wypchnij się piętami w górę."],proTip:"Trzymaj łokcie wysoko przez cały ruch, bo opadające łokcie zrzucają sztangę w przód.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Mięśnie głębokie (core)"],primaryMuscle:"quads",equipment:"Sztanga"},"Prasa nożna pozioma (siedząc)":{steps:["Usiądź w maszynie poziomej, plecy oparte o oparcie, stopy na platformie na szerokość bioder.","Zwolnij blokady i kontrolowanie przyciągnij platformę do siebie.","Zegnij kolana do około 90 stopni, nie odrywając pośladków.","Wypchnij platformę napierając piętami, nie blokując kolan na końcu."],proTip:"Poziomy tor zmienia ustawienie względem prasy pod kątem; utrzymuj plecy i miednicę przy oparciu.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Maszyna do prasy poziomej"},"Prasa nożna pionowa (leżąc)":{steps:["Połóż się pod platformą, biodra pod ciężarem, stopy na platformie nad sobą.","Zwolnij blokady i opuść platformę zginając kolana w stronę klatki.","Zatrzymaj się gdy uda dochodzą do tułowia, plecy płasko.","Wypchnij platformę pionowo w górę napierając całą stopą."],proTip:"Pionowa prasa daje duży zakres ruchu, ale wymaga lekkiego ciężaru na start.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Maszyna do prasy pionowej"},"Hack Squat odwrotny (twarzą do oparcia)":{steps:["Ustaw się twarzą do oparcia maszyny hack squat, barki pod poduszkami.","Stopy nieco z przodu platformy, biodra cofnięte.","Schodź w dół zginając kolana i biodra, akcent na pośladki.","Wypchnij się piętami napinając pośladki na górze."],proTip:"Twarzą do oparcia mocniej angażujesz pośladki niż w klasycznym hack squacie.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowy uda"],primaryMuscle:"glutes",equipment:"Maszyna Hack Squat"},"Pendulum Squat (maszyna wahadłowa)":{steps:["Oprzyj barki pod poduszki, plecy o platformę, stopy na podnóżku.","Zwolnij blokady i schodź po łuku zginając kolana.","Zejdź głęboko trzymając pięty na podłożu i plecy przy oparciu.","Wypchnij się po łuku w górę napierając środkiem stopy."],proTip:"Łukowy tor ruchu utrzymuje stałe napięcie na czworogłowych w całym zakresie.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki"],primaryMuscle:"quads",equipment:"Maszyna Pendulum Squat"},"Przysiad Belt Squat (z pasem biodrowym)":{steps:["Załóż pas biodrowy podpięty do obciążenia, stań na podestach maszyny.","Trzymaj uchwyty, tułów pionowo, brzuch napięty.","Schodź w przysiad zginając kolana i biodra, ciężar ciągnie w dół od bioder.","Wypchnij się piętami do wyprostu bioder."],proTip:"Obciążenie jest podpięte do pasa biodrowego; utrzymuj tułów stabilny i kontroluj głębokość przysiadu.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Maszyna Belt Squat"},"Wyprosty nóg na maszynie jednonóż":{steps:["Usiądź w maszynie, wałek na jednej kostce, drugą nogę odstaw.","Trzymaj uchwyty, plecy o oparcie.","Wyprostuj jedną nogę do pełnego wyprostu, napinając czworogłowy na szczycie.","Opuść kontrolowanie i powtórz, potem zmień nogę."],proTip:"Jednonóż wyrównuje dysproporcje siły między udami i poprawia mind-muscle connection.",targetMuscles:["Czworogłowy uda","Mięsień prosty uda"],primaryMuscle:"quads",equipment:"Maszyna do wyprostów nóg"},"Uginanie nóg stojąc jednonóż na maszynie":{steps:["Stań w maszynie, wałek pod łydką jednej nogi, biodro o podpórkę.","Trzymaj uchwyty, tułów stabilny.","Ugnij nogę przyciągając piętę do pośladka, napnij dwugłowy.","Opuść kontrolowanie i powtórz, potem zmień nogę."],proTip:"Wersja stojąca jednonóż daje czysty, izolowany ruch dwugłowego bez kompensacji.",targetMuscles:["Dwugłowy uda","Półścięgnisty","Półbłoniasty"],primaryMuscle:"hamstrings",equipment:"Maszyna do uginania nóg stojąc"},"Przysiad w suwnicy Smitha":{steps:["Ustaw gryf na barkach w suwnicy, stopy lekko z przodu pionu gryfu.","Odblokuj gryf obracając nadgarstki, napnij brzuch.","Schodź w przysiad po prowadnicy zginając kolana i biodra.","Wypchnij się piętami do wyprostu i zablokuj gryf na górze."],proTip:"Stopy z przodu w suwnicy mocniej akcentują czworogłowe i ułatwiają balans.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Suwnica Smitha"},"Wykrok w suwnicy Smitha":{steps:["Ustaw gryf na barkach, jedną nogę wykrocz do przodu pod gryfem.","Odblokuj gryf, tułów pionowy.","Schodź w dół zginając przednie kolano do kąta prostego.","Wypchnij się przednią piętą do góry, powtórz, potem zmień nogę."],proTip:"Suwnica stabilizuje tor, więc skup się na głębokości i pracy przedniej nogi.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Suwnica Smitha"},"Glute-Ham Raise (GHR)":{steps:["Ustaw się na ławce GHD, stopy oparte o płytkę, kolana za poduszką.","Tułów wyprostowany w linii z udami na starcie.","Opuszczaj tułów w przód kontrolowanie aż do poziomu, prostując kolana.","Zegnij kolana i podciągnij tułów w górę siłą dwugłowych."],proTip:"Jeśli pełny GHR za trudny, pomóż sobie odbiciem rąk od podłogi na dole.",targetMuscles:["Dwugłowy uda","Pośladkowy wielki","Łydki"],primaryMuscle:"hamstrings",equipment:"Ławka GHD"},"Nordic Hamstring Curl":{steps:["Klęknij, kostki zablokowane pod ciężarem lub przez partnera.","Tułów i biodra w jednej linii z udami, brzuch napięty.","Opuszczaj się powoli w przód, hamując ruch dwugłowymi jak najdłużej.","Przy utracie napięcia złap upadek dłońmi i odepchnij się do startu."],proTip:"Najważniejsza jest faza ekscentryczna, więc hamuj jak najwolniej, nie spadaj.",targetMuscles:["Dwugłowy uda","Półścięgnisty","Pośladkowy wielki"],primaryMuscle:"hamstrings",equipment:"Masa ciała"},"Przysiad pistolet (jednonóż)":{steps:["Stań na jednej nodze, druga wyprostowana w przód nad podłożem.","Ręce wyciągnij przed siebie dla równowagi.","Schodź w dół na jednej nodze aż udo będzie poniżej równoległości.","Wypchnij się piętą stojącej nogi z powrotem do wyprostu."],proTip:"Zacznij z przytrzymaniem TRX lub na podwyższeniu, zanim opanujesz pełny zakres.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Mięśnie głębokie (core)"],primaryMuscle:"quads",equipment:"Masa ciała"},"Przysiad z masą ciała (Air Squat)":{steps:["Stań na szerokość barków, ręce przed sobą lub na biodrach.","Napnij brzuch, klatka wysoko.","Schodź w dół cofając biodra aż uda będą równoległe do podłoża.","Wypchnij się piętami do pełnego wyprostu."],proTip:"Wykonuj ruch bez obciążenia, kontrolując ustawienie stóp, kolan i tułowia przed przejściem do wersji z ciężarem.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Masa ciała"},"Sissy Squat na maszynie":{steps:["Ustaw nogi pod wałkami maszyny sissy, pięty na podnóżku.","Tułów i uda w jednej linii, brzuch napięty.","Odchylaj się do tyłu zginając kolana, wysuwając je w przód.","Wróć do pionu napinając czworogłowe na końcu ruchu."],proTip:"Maszyna prowadzi ruch po stałym torze; dopasuj ustawienie i zakres do pełnej kontroli ruchu.",targetMuscles:["Czworogłowy uda","Mięsień prosty uda"],primaryMuscle:"quads",equipment:"Maszyna Sissy Squat"},"Wejścia przodem na skrzynię ze sztangielkami":{steps:["Trzymaj hantle wzdłuż ciała, stań przodem do skrzyni lub stepu.","Postaw całą stopę na skrzyni, kolano w linii palców.","Wypchnij się piętą nogi na skrzyni do pełnego wyprostu na górze.","Zejdź kontrolowanie i powtórz, naprzemiennie lub seriami na nogę."],proTip:"Minimalizuj odbicie tylną nogą, cała praca ma iść z nogi na skrzyni.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowy uda"],primaryMuscle:"quads",equipment:"Hantle"},"Przysiad do skrzyni (Box Squat)":{steps:["Ustaw skrzynię za sobą, gryf na barkach, stopy szerzej niż barki.","Cofaj biodra do tyłu schodząc w kierunku skrzyni.","Usiądź lekko na skrzyni nie tracąc napięcia tułowia.","Wybuchowo wypchnij się piętami w górę do wyprostu bioder."],proTip:"Nie opadaj ciężarem na skrzynię, kontroluj zejście i utrzymaj napięcie.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowy uda"],primaryMuscle:"glutes",equipment:"Sztanga"},"Przysiad Zercher (sztanga w zgięciach łokci)":{steps:["Oprzyj gryf w zgięciach łokci przy klatce, dłonie splecione.","Stopy na szerokość barków, tułów pionowy, brzuch napięty.","Schodź głęboko w przysiad, łokcie między kolanami.","Wypchnij się piętami w górę utrzymując klatkę wysoko."],proTip:"Owinięcie gryfu ręcznikiem zmniejsza dyskomfort łokci przy większych ciężarach.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Mięśnie głębokie (core)"],primaryMuscle:"quads",equipment:"Sztanga"},"Przysiad sumo z kettlebell":{steps:["Stań szeroko, palce stóp na zewnątrz, kettlebell trzymaj oburącz między nogami.","Klatka wysoko, brzuch napięty.","Schodź w dół cofając biodra, kolana w linii palców.","Wypchnij się piętami napinając pośladki i przywodziciele na górze."],proTip:"Szeroki rozkrok i palce na zewnątrz mocniej angażują przywodziciele i pośladki.",targetMuscles:["Pośladkowy wielki","Przywodziciele","Czworogłowy uda"],primaryMuscle:"glutes",equipment:"Kettlebell"},"Wykroki chodzone z hantlami (długi krok)":{steps:["Trzymaj hantle wzdłuż ciała, zrób długi wykrok do przodu.","Schodź w dół aż tylne kolano zbliży się do podłogi.","Wypchnij się przednią piętą i przejdź długim krokiem na drugą nogę.","Kontynuuj chód utrzymując tułów pionowo."],proTip:"Dłuższy krok przesuwa akcent na pośladki, krótszy bardziej na czworogłowe.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowy uda"],primaryMuscle:"glutes",equipment:"Hantle"},"Wypychanie bioder na maszynie Glute Drive":{steps:["Usiądź na maszynie i oprzyj plecy o oparcie, wałek umieść nisko na biodrach.","Stopy ustaw na platformie na szerokość bioder, pięty wbij w podłoże.","Wypchnij biodra w górę napinając pośladki do pełnego wyprostu.","Zatrzymaj się na szczycie na sekundę, potem kontrolowanie opuść biodra."],proTip:"Na szczycie ruchu lekko podwiń miednicę (tuck), żeby maksymalnie skrócić pośladek bez przeprostu lędźwi.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Czworogłowe uda"],primaryMuscle:"glutes",equipment:"Maszyna Glute Drive"},"Hip Thrust w maszynie Smith":{steps:["Oprzyj górną część pleców o ławkę, gryf maszyny Smith ułóż nisko na biodrach (użyj poduszki).","Stopy ustaw płasko na szerokość bioder, lekko przed kolanami.","Odbezpiecz gryf i wypchnij biodra w górę aż tułów będzie równoległy do podłogi.","Napnij pośladki na szczycie, następnie opuść biodra kontrolowanie."],proTip:"Prowadzona ścieżka gryfu ogranicza potrzebę balansowania; zwiększaj ciężar stopniowo, utrzymując kontrolę.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Pośladki średnie"],primaryMuscle:"glutes",equipment:"Maszyna Smith"},"Odwodzenie ud na maszynie z pochyleniem tułowia":{steps:["Usiądź na maszynie do odwodzenia i pochyl tułów do przodu, opierając się o poduszki.","Pochylenie tułowia mocniej angażuje górną część pośladków.","Rozsuń kolana na boki przeciw oporowi do pełnego zakresu.","Zatrzymaj się na chwilę, potem kontrolowanie wróć do pozycji startowej."],proTip:"Pochylenie tułowia 30-45 stopni do przodu przenosi nacisk z naprężacza powięzi na pośladki średnie.",targetMuscles:["Pośladki średnie","Pośladki małe","Naprężacz powięzi szerokiej"],primaryMuscle:"glutes",equipment:"Maszyna do odwodzenia"},"Kickback pośladka na maszynie":{steps:["Ustaw stopę na ruchomej platformie maszyny, oprzyj się o poduszki tułowiem.","Złap uchwyty dla stabilizacji i utrzymaj plecy w neutralnej pozycji.","Wypchnij stopę w tył i w górę napinając pośladek do pełnego wyprostu biodra.","Zatrzymaj na szczycie, potem wolno wróć do pozycji startowej."],proTip:"Trzymaj kolano lekko ugięte i prowadź ruch piętą, żeby izolować pośladek bez pomocy lędźwi.",targetMuscles:["Pośladki wielkie","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Maszyna Glute Kickback"},"Przeciąganie linki między nogami (Cable Pull-Through)":{steps:["Ustaw linkę z uchwytem sznurowym nisko, stań tyłem do wyciągu w rozkroku.","Sięgnij między nogami i złap uchwyt, odejdź kilka kroków do przodu.","Wykonaj zawias biodrowy odprowadzając biodra w tył, tułów pochyl.","Wypchnij biodra do przodu napinając pośladki do pełnego wyprostu."],proTip:"Ruch napędzaj biodrami, nie ramionami, ręce tylko trzymają uchwyt, jak haki.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Prostowniki grzbietu"],primaryMuscle:"glutes",equipment:"Wyciąg dolny"},"Mostek pośladkowy na jednej nodze":{steps:["Połóż się na plecach, jedną stopę oprzyj płasko, drugą nogę wyprostuj w górę.","Napnij brzuch i ustaw miednicę w neutralnej pozycji.","Wypchnij biodra w górę przez piętę nogi podporowej, druga noga zostaje uniesiona.","Napnij pośladek na szczycie, potem kontrolowanie opuść biodra."],proTip:"Utrzymuj biodra na równym poziomie, nie pozwól, żeby strona uniesionej nogi opadła.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Mięśnie głębokie brzucha"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Frog Pump (mostek z rozłożonymi kolanami)":{steps:["Połóż się na plecach, złącz podeszwy stóp razem i rozłóż kolana na boki.","Stopy przysuń bliżej pośladków, kolana skierowane na zewnątrz.","Wypchnij biodra w górę napinając mocno pośladki.","Zatrzymaj na szczycie na sekundę, potem opuść biodra kontrolowanie."],proTip:"Pozycja żabki z rozłożonymi kolanami wymusza większą rotację zewnętrzną, mocniej angażując pośladki.",targetMuscles:["Pośladki wielkie","Pośladki średnie"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Wykrok ukośny (Curtsy Lunge)":{steps:["Stań prosto z hantlami w dłoniach, stopy na szerokość bioder.","Zrób krok jedną nogą ukośnie w tył, krzyżując ją za nogą podporową.","Opuść się zginając oba kolana, biodro nogi tylnej rozciąga się.","Odepchnij się przez piętę nogi przedniej wracając do pozycji startowej."],proTip:"Ukośne skrzyżowanie nogi w tył mocno angażuje pośladek średni, kluczowy dla zaokrąglenia boków.",targetMuscles:["Pośladki średnie","Pośladki wielkie","Czworogłowe uda"],primaryMuscle:"glutes",equipment:"Hantle"},"Wysoki step-up z hantlami":{steps:["Stań przed wysoką skrzynią lub ławką z hantlami w dłoniach.","Postaw całą stopę na skrzyni, kolano i biodro mocno ugięte.","Odepchnij się przez piętę nogi na skrzyni wchodząc do pełnego wyprostu.","Kontrolowanie opuść drugą nogę z powrotem na podłogę."],proTip:"Im wyższa skrzynia, tym większe zgięcie biodra i większe zaangażowanie pośladka, nie odbijaj się dolną nogą.",targetMuscles:["Pośladki wielkie","Czworogłowe uda","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Hantle"},"Wykrok w tył z akcentem na pośladek":{steps:["Stań prosto z hantlami, lekko pochyl tułów do przodu z bioder.","Zrób długi krok jedną nogą w tył i opuść się aż tylne kolano zbliży się do podłogi.","Utrzymaj ciężar na pięcie przedniej nogi.","Odepchnij się mocno przez piętę przedniej nogi, napinając pośladek przy wstawaniu."],proTip:"Dłuższy krok w tył i lekkie pochylenie tułowia przenosi pracę z czworogłowego na pośladek.",targetMuscles:["Pośladki wielkie","Czworogłowe uda","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Hantle"},"Rumuński martwy ciąg z akcentem na pośladek":{steps:["Trzymaj sztangę przed udami nachwytem, stopy na szerokość bioder.","Odprowadź biodra mocno w tył, sztanga sunie blisko nóg w dół.","Schodź aż poczujesz napięcie w dwugłowych i pośladkach, plecy proste.","Wypchnij biodra do przodu napinając pośladki do pełnego wyprostu."],proTip:"Świadomie odprowadzaj biodra daleko w tył, im większy zawias, tym mocniejsze rozciągnięcie pośladka.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Prostowniki grzbietu"],primaryMuscle:"glutes",equipment:"Sztanga"},"Wymachy kettlebell":{steps:["Stań w lekkim rozkroku, kettlebell na podłodze nieco przed tobą.","Wykonaj zawias biodrowy i chwyć kettlebell oburącz, zamachnij go między nogi.","Eksplozywnie wypchnij biodra do przodu, napęd wyrzuca kettlebell na wysokość klatki.","Pozwól kettlebellowi opaść, ponownie wykonując zawias biodrowy w dół."],proTip:"Wymach to ruch napędzany biodrami, a nie ramionami, eksplozja w biodrach wyrzuca ciężar.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Prostowniki grzbietu","Mięśnie głębokie brzucha"],primaryMuscle:"glutes",equipment:"Kettlebell"},"Kickback pośladka z gumą oporową":{steps:["Przyjmij pozycję w podporze na dłoniach i kolanach, gumę zaczep za stopę i pod dłonie.","Utrzymaj plecy proste, brzuch napięty, kolano ugięte pod kątem prostym.","Wypchnij nogę w tył i w górę przeciw oporowi gumy, napinając pośladek.","Zatrzymaj na szczycie, potem kontrolowanie wróć do pozycji startowej."],proTip:"Nie przeprostowuj lędźwi, ruch kończy się gdy biodro jest wyprostowane, dalej pracują już plecy.",targetMuscles:["Pośladki wielkie","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Guma oporowa"},"Hip Thrust w rozstawie B-stance":{steps:["Oprzyj górne plecy o ławkę, hantel ułóż na biodrach.","Jedną stopę ustaw płasko jako roboczą, drugą cofnij i oprzyj tylko na pięcie.","Wypchnij biodra w górę głównie przez stopę roboczą, noga cofnięta tylko balansuje.","Napnij pośladek roboczej strony na szczycie, potem opuść biodra kontrolowanie."],proTip:"B-stance to most do pracy jednostronnej, prawie cały ciężar trzymaj na przedniej stopie, by mocniej obciążyć jeden pośladek.",targetMuscles:["Pośladki wielkie","Dwugłowe uda","Pośladki średnie"],primaryMuscle:"glutes",equipment:"Hantle"},"Uginanie skoncentrowane (Concentration Curl)":{steps:["Usiądź, rozstaw nogi i oprzyj łokieć o wewnętrzną stronę uda.","Trzymaj hantlę z ramieniem wyprostowanym w dół.","Uginaj łokieć, prowadząc hantlę w stronę barku z pełną supinacją.","Zatrzymaj na szczycie i napnij biceps, po czym powoli opuść."],proTip:"Trzymaj łokieć przyklejony do uda przez cały ruch, by wyizolować biceps.",targetMuscles:["Biceps (głowa krótka)","Ramienny"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie na pająku (Spider Curl)":{steps:["Połóż się brzuchem na ławce skośnej ustawionej pod kątem ok. 45 stopni.","Pozwól ramionom zwisać pionowo w dół, trzymając sztangę EZ.","Uginaj łokcie, prowadząc sztangę do góry bez ruchu barków.","Napnij biceps na szczycie i powoli wróć do pełnego wyprostu."],proTip:"Pozycja eliminuje rozpęd, zapewniając stałe napięcie w fazie skurczu.",targetMuscles:["Biceps (głowa krótka)","Ramienny"],primaryMuscle:"biceps",equipment:"Sztanga EZ"},"Uginanie z dociąganiem (Drag Curl)":{steps:["Stań prosto, trzymając sztangę nachwytem dołem na szerokość barków.","Odciągaj łokcie do tyłu, prowadząc sztangę blisko tułowia.","Sztanga ma 'sunąć' wzdłuż ciała w górę, a łokcie cofać się za plecy.","Zatrzymaj na szczycie i powoli opuść wzdłuż tej samej linii."],proTip:"Cofanie łokci za linię ciała mocniej angażuje długą głowę bicepsa.",targetMuscles:["Biceps (głowa długa)","Ramienny"],primaryMuscle:"biceps",equipment:"Sztanga"},"Uginanie bayesowskie na wyciągu (Bayesian Cable Curl)":{steps:["Ustaw uchwyt linki nisko i chwyć go jedną ręką, stojąc tyłem do wyciągu.","Zrób krok do przodu, tak by ramię było odciągnięte za linię ciała.","Uginaj łokieć z supinacją, prowadząc dłoń do barku.","Napnij biceps i powoli wróć do pełnego rozciągnięcia za plecami."],proTip:"Ramię za tułowiem maksymalizuje rozciągnięcie długiej głowy pod obciążeniem.",targetMuscles:["Biceps (głowa długa)","Ramienny"],primaryMuscle:"biceps",equipment:"Wyciąg"},"Uginanie hantli na ławce skośnej (Incline Curl)":{steps:["Usiądź na ławce skośnej ustawionej pod kątem ok. 45-60 stopni.","Pozwól ramionom zwisać swobodnie w dół, trzymając hantle neutralnie.","Uginaj łokcie z supinacją, nie odrywając łokci od tułowia.","Napnij biceps na szczycie i powoli opuść do pełnego rozciągnięcia."],proTip:"Odchylenie tułowia rozciąga długą głowę bicepsa w pozycji dolnej.",targetMuscles:["Biceps (głowa długa)","Ramienny"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie Zottmana (Zottman Curl)":{steps:["Stań prosto, trzymając hantle podchwytem wzdłuż ciała.","Uginaj łokcie z supinacją, prowadząc hantle do barków.","Na szczycie obróć nadgarstki do nachwytu (pronacja).","Opuść hantle powoli w nachwycie, po czym wróć do podchwytu."],proTip:"Faza ekscentryczna w nachwycie mocno obciąża przedramiona.",targetMuscles:["Biceps","Ramienno-promieniowy","Prostowniki przedramienia"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie ramion na maszynie wyciąg jednorącz (Single-Arm Cable Curl)":{steps:["Ustaw rolkę wyciągu nisko i chwyć uchwyt jedną ręką.","Stań bokiem do stosu, łokieć przy tułowiu.","Uginaj łokieć z supinacją, prowadząc dłoń do barku.","Napnij biceps i powoli wróć do pełnego wyprostu."],proTip:"Wyciąg daje stałe napięcie również w pozycji dolnej, czego brakuje hantlom.",targetMuscles:["Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Wyciąg"},"Uginanie odwrotne (Reverse Curl)":{steps:["Stań prosto, trzymając sztangę EZ nachwytem na szerokość barków.","Trzymaj łokcie przy tułowiu i nadgarstki proste.","Uginaj łokcie, prowadząc sztangę w górę bez ruchu nadgarstków.","Napnij przedramiona na szczycie i powoli opuść."],proTip:"Nachwyt przenosi obciążenie na ramienno-promieniowy i prostowniki nadgarstka.",targetMuscles:["Ramienno-promieniowy","Prostowniki przedramienia","Ramienny"],primaryMuscle:"forearms",equipment:"Sztanga EZ"},"Uginanie 21-tki (21s)":{steps:["Stań prosto, trzymając sztangę podchwytem na szerokość barków.","Wykonaj 7 powtórzeń od dołu do połowy zakresu (kąt prosty w łokciu).","Wykonaj 7 powtórzeń od połowy zakresu do pełnego skurczu.","Zakończ 7 powtórzeniami pełnego zakresu ruchu."],proTip:"Technika 21 powtórzeń daje ogromną objętość i pompę przy lekkim ciężarze.",targetMuscles:["Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Sztanga"},"Prostowanie ramion zza głowy na wyciągu (Overhead Cable Extension)":{steps:["Przyczep linkę do wyciągu i stań tyłem do stosu, chwytając ją oburącz.","Wykrok do przodu, ręce zgięte za głową, łokcie skierowane do przodu.","Prostuj łokcie, wypychając linkę do góry i do przodu.","Zatrzymaj na pełnym wyproście, po czym powoli wróć za głowę."],proTip:"Pozycja zza głowy rozciąga długą głowę tricepsa pod stałym napięciem.",targetMuscles:["Triceps (głowa długa)","Triceps (głowa boczna)"],primaryMuscle:"triceps",equipment:"Wyciąg"},"Prostowanie ramion z liną na wyciągu (Rope Pushdown)":{steps:["Przyczep linkę do górnego wyciągu i chwyć oba końce neutralnie.","Stań prosto, łokcie przyciśnięte do tułowia.","Prostuj łokcie w dół, rozsuwając końce liny na dole.","Napnij triceps na pełnym wyproście i powoli wróć."],proTip:"Rozsunięcie końców liny na dole zwiększa skurcz głowy bocznej.",targetMuscles:["Triceps (głowa boczna)","Triceps (głowa przyśrodkowa)"],primaryMuscle:"triceps",equipment:"Wyciąg"},"Prostowanie ramienia na wyciągu jednorącz (Single-Arm Pushdown)":{steps:["Przyczep uchwyt do górnego wyciągu i chwyć go podchwytem jedną ręką.","Stań prosto, łokieć przyciśnięty do boku tułowia.","Prostuj łokieć w dół do pełnego wyprostu ramienia.","Napnij triceps i powoli wróć kontrolowanym tempem."],proTip:"Podchwyt jednorącz akcentuje głowę przyśrodkową tricepsa.",targetMuscles:["Triceps (głowa boczna)","Triceps (głowa przyśrodkowa)"],primaryMuscle:"triceps",equipment:"Wyciąg"},"JM Press (wyciskanie JM)":{steps:["Połóż się na ławce poziomej, trzymając sztangę wąsko nad klatką.","Opuszczaj sztangę w stronę górnej części klatki, zginając łokcie do przodu.","Zatrzymaj sztangę tuż nad szyją z łokciami nisko, jak hybryda skull crusher i wyciskania.","Wypchnij sztangę do góry, prostując łokcie."],proTip:"JM Press łączy wyciskanie wąsko ze skull crusherem, mocno obciążając triceps.",targetMuscles:["Triceps","Klatka piersiowa (góra)","Barki przednie"],primaryMuscle:"triceps",equipment:"Sztanga"},"Tate Press (wyciskanie Tate)":{steps:["Połóż się na ławce poziomej, trzymając hantle nad klatką nachwytem.","Zginaj łokcie, opuszczając hantle w stronę środka klatki, łokcie na zewnątrz.","Talerze hantli powinny niemal dotknąć klatki, kierując się do środka.","Wypchnij hantle do góry, prostując łokcie i napinając triceps."],proTip:"Kierowanie hantli do środka klatki izoluje głowę przyśrodkową tricepsa.",targetMuscles:["Triceps (głowa przyśrodkowa)","Triceps (głowa boczna)"],primaryMuscle:"triceps",equipment:"Hantle"},"Dipy na maszynie (Assisted Dip Machine)":{steps:["Usiądź w maszynie do dipów i chwyć uchwyty po bokach.","Ustaw obciążenie i oprzyj dłonie, trzymając tułów wyprostowany.","Prostuj łokcie, wypychając uchwyty w dół do pełnego wyprostu ramion.","Powoli wróć, zginając łokcie do kąta prostego."],proTip:"Maszyna prowadzi ruch po stałej trajektorii; dobierz asystę i zakres do kontrolowanego wykonania.",targetMuscles:["Triceps","Klatka piersiowa (dół)","Barki przednie"],primaryMuscle:"triceps",equipment:"Maszyna do dipów"},"Pompki diamentowe (Diamond Push-up)":{steps:["Przyjmij pozycję podporu, ustawiając dłonie blisko siebie pod klatką.","Kciuki i palce wskazujące stykają się, tworząc kształt diamentu.","Opuszczaj klatkę do dłoni, trzymając łokcie blisko tułowia.","Wypchnij się do góry, prostując łokcie i napinając triceps."],proTip:"Wąskie ustawienie dłoni przenosi nacisk z klatki na triceps.",targetMuscles:["Triceps","Klatka piersiowa (środek)","Barki przednie"],primaryMuscle:"triceps",equipment:"Masa ciała"},"Dipy na ławce (Bench Dips)":{steps:["Usiądź na krawędzi ławki i oprzyj dłonie tuż obok bioder.","Zsuń biodra z ławki, trzymając nogi wyprostowane lub zgięte.","Opuszczaj ciało, zginając łokcie do kąta prostego.","Wypchnij się do góry, prostując łokcie i napinając triceps."],proTip:"Trzymaj plecy blisko ławki, łokcie kieruj do tyłu i kontroluj dolny zakres ruchu.",targetMuscles:["Triceps","Barki przednie","Klatka piersiowa (dół)"],primaryMuscle:"triceps",equipment:"Masa ciała"},"Prostowanie ramion zza głowy z hantlą oburącz (Overhead DB Extension)":{steps:["Usiądź lub stań prosto, trzymając jedną hantlę oburącz nad głową.","Chwyć górny talerz hantli obiema dłońmi, ramiona pionowo w górę.","Opuszczaj hantlę za głowę, zginając łokcie i trzymając je blisko głowy.","Wypchnij hantlę do góry do pełnego wyprostu, napinając triceps."],proTip:"Trzymaj łokcie wąsko i nieruchomo, by w pełni rozciągnąć długą głowę.",targetMuscles:["Triceps (głowa długa)","Triceps (głowa przyśrodkowa)"],primaryMuscle:"triceps",equipment:"Hantle"},"Uginanie nadgarstków ze sztangą (Wrist Curl)":{steps:["Usiądź i oprzyj przedramiona na udach, dłonie skierowane do góry.","Trzymaj sztangę podchwytem, pozwalając jej zsunąć się do końców palców.","Zwiń nadgarstki do góry, podnosząc sztangę pełnym zakresem.","Napnij przedramiona na szczycie i powoli opuść."],proTip:"Pozwól sztandze zsunąć się do palców na dole, by uzyskać pełny zakres.",targetMuscles:["Zginacze nadgarstka","Zginacze przedramienia"],primaryMuscle:"forearms",equipment:"Sztanga"},"Odwrotne uginanie nadgarstków ze sztangą (Reverse Wrist Curl)":{steps:["Usiądź i oprzyj przedramiona na udach, dłonie skierowane w dół.","Trzymaj sztangę nachwytem na szerokość barków.","Unieś grzbiety dłoni do góry, prostując nadgarstki pełnym zakresem.","Napnij prostowniki na szczycie i powoli opuść."],proTip:"Używaj lekkiego ciężaru, bo prostowniki nadgarstka są słabsze niż zginacze.",targetMuscles:["Prostowniki nadgarstka","Prostowniki przedramienia"],primaryMuscle:"forearms",equipment:"Sztanga"},"Izometryczny chwyt farmera (Farmer's Hold)":{steps:["Chwyć ciężkie hantle po bokach i stań prosto.","Trzymaj klatkę uniesioną, barki ściągnięte, plecy proste.","Utrzymuj mocny chwyt i statyczną pozycję przez określony czas.","Postaw hantle kontrolowanym ruchem po upływie czasu."],proTip:"Statyczny chwyt buduje siłę uścisku i wytrzymałość przedramion.",targetMuscles:["Zginacze przedramienia","Mięśnie chwytu","Czworoboczny"],primaryMuscle:"forearms",equipment:"Hantle"},"Uginanie hammer na wyciągu z liną (Cable Rope Hammer Curl)":{steps:["Przyczep linkę do dolnego wyciągu i chwyć oba końce neutralnie.","Stań prosto, łokcie przyciśnięte do tułowia.","Uginaj łokcie, prowadząc linkę w górę chwytem neutralnym (młotkowym).","Napnij na szczycie i powoli wróć do pełnego wyprostu."],proTip:"Chwyt młotkowy na wyciągu mocno angażuje ramienno-promieniowy i grubość ramienia.",targetMuscles:["Ramienno-promieniowy","Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Wyciąg"},"Wyciskanie wąsko w maszynie Smitha (Smith Close-Grip Press)":{steps:["Połóż się na ławce ustawionej pod gryfem maszyny Smitha.","Chwyć gryf wąsko, na szerokość barków, i odblokuj zabezpieczenia.","Opuszczaj gryf do dolnej części klatki, trzymając łokcie blisko ciała.","Wypchnij gryf do góry do pełnego wyprostu, napinając triceps."],proTip:"Prowadnica Smitha stabilizuje tor ruchu, pozwalając skupić się na tricepsie.",targetMuscles:["Triceps","Klatka piersiowa (środek)","Barki przednie"],primaryMuscle:"triceps",equipment:"Maszyna Smitha"},"Brzuszki klasyczne (Crunch)":{steps:["Połóż się na plecach, ugnij kolana, stopy płasko na podłodze.","Dłonie skrzyżuj na klatce lub trzymaj przy skroniach (bez ciągnięcia za głowę).","Unieś łopatki, zwijając tułów w kierunku kolan i napinając brzuch.","Powoli opuść łopatki do podłogi, zachowując napięcie."],proTip:"Skup się na zwijaniu kręgosłupa, nie na unoszeniu całych pleców.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},"Pełne spięcie brzucha (Sit-up)":{steps:["Połóż się na plecach z ugiętymi kolanami, stopy ustabilizowane.","Dłonie przy skroniach lub skrzyżowane na klatce.","Unieś cały tułów do pozycji siedzącej, napinając brzuch.","Kontrolowanie opuść plecy na podłogę."],proTip:"Nie szarp ruchem, kontroluj fazę opadania dla większego efektu.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"Brzuszki rowerek (Bicycle Crunch)":{steps:["Połóż się na plecach, dłonie przy skroniach, nogi uniesione.","Przyciągnij prawy łokieć do lewego kolana, prostując prawą nogę.","Zmień stronę: lewy łokieć do prawego kolana, naprzemiennie jak na rowerze.","Utrzymuj dolne plecy dociśnięte do podłogi przez cały ruch."],proTip:"Obracaj tułów z brzucha, nie ciągnij głowy łokciami.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},"Plank boczny (Side Plank)":{steps:["Połóż się na boku, oprzyj się na przedramieniu pod barkiem.","Ułóż stopy jedna na drugiej, napnij brzuch.","Unieś biodra, tworząc prostą linię od głowy do stóp.","Utrzymaj pozycję wyznaczony czas, potem zmień stronę."],proTip:"Nie pozwól biodrom opadać, utrzymuj jedną linię ciała.",targetMuscles:["Mięśnie skośne brzucha","Mięsień czworoboczny lędźwi","Mięsień poprzeczny brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},"Hollow Rock (Bujanie w łódce)":{steps:["Połóż się na plecach, ramiona wyprostowane za głową, nogi proste.","Unieś łopatki i nogi, tworząc kształt łódki (hollow position).","Utrzymując napięcie brzucha, bujaj się rytmicznie w przód i w tył.","Nie pozwól dolnym plecom oderwać się od linii ruchu."],proTip:"Im niżej trzymasz nogi, tym trudniej, dostosuj do swojego poziomu.",targetMuscles:["Mięsień prosty brzucha","Mięsień poprzeczny brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"V-up (Scyzoryk)":{steps:["Połóż się na plecach, ramiona wyprostowane za głową, nogi proste.","Jednocześnie unieś tułów i wyprostowane nogi do kształtu litery V.","Sięgnij dłońmi w kierunku stóp na szczycie ruchu.","Kontrolowanie opuść tułów i nogi, nie dotykając podłogi."],proTip:"Trzymaj nogi prosto, zginanie kolan ułatwia ćwiczenie.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"Nogi do drążka (Toes to Bar)":{steps:["Zawiśnij na drążku nachwytem, ramiona wyprostowane.","Napnij brzuch i unieś wyprostowane nogi do drążka.","Dotknij palcami stóp drążka między dłońmi.","Kontrolowanie opuść nogi, unikając niekontrolowanego bujania."],proTip:"Aktywuj najszersze grzbietu, by ustabilizować zwis i ograniczyć kołysanie.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder","Najszerszy grzbietu"],primaryMuscle:"core",equipment:"Drążek"},"Unoszenie kolan w zwisie":{steps:["Zawiśnij na drążku nachwytem, ramiona wyprostowane.","Napnij brzuch, by ustabilizować ciało i ograniczyć bujanie.","Przyciągnij kolana do klatki piersiowej, zwijając miednicę.","Powoli opuść nogi do pozycji wyjściowej."],proTip:"Na szczycie zwiń miednicę ku górze, by mocniej zaangażować brzuch.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Drążek"},"Wyciskanie kółka do brzucha z klęku jednorącz":{steps:["Uklęknij i chwyć kółko jedną ręką przed sobą.","Napnij brzuch i wytaczaj kółko w przód, prostując tułów.","Zatrzymaj się przed utratą napięcia, antygrawitacyjnie utrzymując biodra.","Przyciągnij kółko z powrotem, napinając brzuch, zmień rękę po serii."],proTip:"Wersja jednorącz mocno obciąża skośne, zaczynaj od krótkiego zakresu.",targetMuscles:["Mięsień prosty brzucha","Mięsień poprzeczny brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Kółko do brzucha"},"Spięcia brzucha na ławce skośnej (Decline Sit-up)":{steps:["Zaczep stopy o wałki ławki skośnej ustawionej głową w dół.","Dłonie skrzyżuj na klatce lub przy skroniach.","Unieś tułów, napinając brzuch, aż dojdziesz do pozycji siedzącej.","Kontrolowanie opuść plecy, nie odpoczywając całkowicie na dole."],proTip:"Im większy spadek ławki, tym trudniej, dobierz kąt do siły brzucha.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Ławka skośna"},"Modlitewnik klęczący jednostronny (Cable Crunch)":{steps:["Ustaw linę na górnym wyciągu i uklęknij bokiem do stosu.","Chwyć linę oburącz i sprowadź ją obok jednego barku.","Zwiń tułów w dół i w stronę przeciwnego biodra, napinając skośne.","Powoli wróć do pozycji wyjściowej, zmień stronę po serii."],proTip:"Wersja boczna mocno akcentuje skośne, prowadź łokieć do przeciwnego kolana.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Wyciąg"},"Wysoki Woodchopper na wyciągu (z dołu do góry)":{steps:["Ustaw uchwyt na najniższej pozycji wyciągu i stań bokiem.","Chwyć uchwyt oburącz przy biodrze dalej od stosu.","Pociągnij ruchem ukośnym w górę nad przeciwległy bark, rotując tułów.","Kontrolowanie wróć do pozycji wyjściowej, zmień stronę po serii."],proTip:"Siłę generuj z rotacji bioder i brzucha, nie z samych ramion.",targetMuscles:["Mięśnie skośne brzucha","Mięsień poprzeczny brzucha","Naramienne"],primaryMuscle:"core",equipment:"Wyciąg"},"Dead Bug z hantlami (obciążony)":{steps:["Połóż się na plecach, ramiona z hantlami wyprostowane nad klatką.","Unieś nogi, kolana i biodra zgięte pod kątem prostym.","Opuść jednocześnie przeciwległe ramię i nogę nad podłogę.","Wróć do środka i powtórz na drugą stronę, plecy dociśnięte do podłogi."],proTip:"Hantle zwiększają wyzwanie antyrotacyjne, ruszaj się wolno i kontrolowanie.",targetMuscles:["Mięsień poprzeczny brzucha","Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Hantle"},"Pallof Press w przysiadzie (warianty)":{steps:["Ustaw uchwyt wyciągu na wysokości klatki i stań bokiem do stosu.","Chwyć uchwyt oburącz przy klatce i przyjmij półprzysiad.","Wyprostuj ramiona przed siebie, opierając się rotacji generowanej przez linkę.","Przytrzymaj sekundę, wróć do klatki, zmień stronę po serii."],proTip:"Półprzysiad angażuje pośladki i tworzy stabilną bazę antyrotacyjną.",targetMuscles:["Mięśnie skośne brzucha","Mięsień poprzeczny brzucha","Pośladkowe"],primaryMuscle:"core",equipment:"Wyciąg"},"Dragon Flag (Flaga Smoka)":{steps:["Połóż się na ławce i chwyć ją oburącz za głową dla stabilizacji.","Napnij całe ciało i unieś je niemal pionowo, opierając na łopatkach.","Powoli opuszczaj wyprostowane ciało jako jedną sztywną linię.","Zatrzymaj tuż nad ławką i wróć w górę, nie dotykając jej biodrami."],proTip:"Trzymaj ciało sztywne jak deska, najtrudniejsza jest faza opuszczania.",targetMuscles:["Mięsień prosty brzucha","Mięsień poprzeczny brzucha","Najszerszy grzbietu"],primaryMuscle:"core",equipment:"Ławka"},"L-sit (Podpór kątowy)":{steps:["Chwyć poręcze i wypchnij się na wyprostowane ramiona.","Napnij brzuch i unieś wyprostowane nogi do poziomu, tworząc literę L.","Utrzymaj pozycję, ściągając łopatki w dół i napinając całe ciało.","Opuść nogi po wyznaczonym czasie i odpocznij."],proTip:"Jeśli nie utrzymasz prostych nóg, zacznij od ugiętych kolan (tuck L-sit).",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder","Triceps"],primaryMuscle:"core",equipment:"Poręcze"},"Plank z dotykaniem barków":{steps:["Przyjmij pozycję planku na wyprostowanych ramionach, stopy rozstawione.","Napnij brzuch i pośladki, utrzymując biodra nieruchomo.","Oderwij jedną dłoń i dotknij przeciwległego barku, nie obracając bioder.","Wróć dłonią na podłogę i powtórz naprzemiennie."],proTip:"Im szerzej stopy, tym łatwiej ustabilizować biodra przy dotknięciu.",targetMuscles:["Mięsień poprzeczny brzucha","Mięśnie skośne brzucha","Naramienne"],primaryMuscle:"core",equipment:"Masa ciała"},"Superman (Unoszenie tułowia leżąc na brzuchu)":{steps:["Połóż się na brzuchu, ramiona wyciągnięte przed siebie, nogi proste.","Napnij pośladki i dolny grzbiet, jednocześnie unosząc ramiona i nogi.","Zatrzymaj się na szczycie, ściskając mięśnie grzbietu.","Powoli opuść ramiona i nogi do podłogi."],proTip:"To ćwiczenie równoważy brzuch, wzmacniając stabilizatory tylnej taśmy.",targetMuscles:["Prostownik grzbietu","Pośladkowe","Czworoboczny lędźwi"],primaryMuscle:"core",equipment:"Masa ciała"},Burpees:{steps:["Z pozycji stojącej zrób przysiad i połóż dłonie na podłodze.","Wyrzuć nogi dynamicznie do tyłu do pozycji deski (plank).","Wykonaj pompkę lub samo dotknięcie klatką podłoża, potem podciągnij nogi z powrotem pod tułów.","Wyskocz dynamicznie w górę z wyciągnięciem rąk nad głowę i ląduj miękko."],proTip:"Utrzymuj napięty brzuch przez całą fazę deski i nie pozwalaj biodrom opadać.",targetMuscles:["Całe ciało","Mięśnie brzucha","Klatka piersiowa","Nogi"],primaryMuscle:"fullbody",equipment:"Masa ciała"},"Wspięcia na palce na prasie nożnej (Leg Press)":{steps:["Usiądź na prasie nożnej i oprzyj śródstopia o dolną krawędź platformy, pięty w powietrzu.","Wyprostuj nogi w kolanach (lekko ugięte) i zwolnij zabezpieczenia.","Opuść pięty maksymalnie w dół, rozciągając łydki.","Wypchnij platformę palcami, prostując stopy w pełnym zakresie.","Przytrzymaj szczyt sekundę i wróć kontrolowanie."],proTip:"Trzymaj kolana lekko ugięte i nieruchome, aby ruch szedł wyłącznie ze stawu skokowego.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna Leg Press"},"Wspięcia na palce w maszynie Smitha (stojąc)":{steps:["Ustaw gryf Smitha na wysokości barków i podłóż podwyższenie (krążek) pod śródstopia.","Wejdź pod gryf, oprzyj go na karku i odbezpiecz suwnicę.","Opuść pięty poniżej poziomu podwyższenia, rozciągając łydki.","Unieś się jak najwyżej na palcach, napinając łydki.","Wróć powoli do pełnego rozciągnięcia."],proTip:"Tor gryfu prowadzi pion, więc skup się na maksymalnym wzniosie i pełnym rozciągnięciu bez balansowania.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna Smitha"},"Wspięcia na palce jednonóż z hantlą":{steps:["Chwyć hantlę w jedną rękę, drugą złap stabilną podporę dla równowagi.","Stań śródstopiem na podwyższeniu (krążek lub stopień), druga noga uniesiona.","Opuść piętę roboczej nogi poniżej poziomu podwyższenia.","Wespnij się jak najwyżej na palcach jednej nogi.","Wykonaj zaplanowane powtórzenia i zmień stronę."],proTip:"Jednostronna praca wyrównuje dysproporcje siły między łydkami i zwiększa zakres ruchu.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Hantla"},"Wspięcia na palce ze sztangą stojąc":{steps:["Połóż sztangę na karku jak do przysiadu i podłóż krążek pod śródstopia.","Wyprostuj sylwetkę, napnij brzuch i utrzymaj proste plecy.","Opuść pięty poniżej poziomu krążka, rozciągając łydki.","Unieś się na palcach jak najwyżej, napinając łydki na szczycie.","Opuść kontrolowanie do pełnego rozciągnięcia."],proTip:"Bez prowadnicy musisz aktywnie stabilizować korpus, więc dobierz ciężar pozwalający utrzymać równowagę.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Sztanga"},"Wspięcia na palce jednonóż na podwyższeniu (masa ciała)":{steps:["Stań śródstopiem jednej nogi na krawędzi stopnia, piętą w powietrzu.","Drugą stopę zahacz za kostkę nogi roboczej, dłoń oprzyj o ścianę dla balansu.","Opuść piętę poniżej krawędzi stopnia do pełnego rozciągnięcia.","Wespnij się jak najwyżej na palcach jednej nogi.","Wykonaj powtórzenia i zmień nogę."],proTip:"Świetne na rozgrzewkę lub wykończenie serii, bo daje duży zakres bez obciążenia zewnętrznego.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Masa ciała"},"Wznosy palców na piszczel (Tibialis Raise)":{steps:["Oprzyj się plecami i pośladkami o ścianę, pięty około 15-30 cm od niej.","Wyprostuj nogi i postaw stopy płasko na podłodze.","Unieś palce i śródstopie jak najwyżej w stronę piszczeli, pięty pozostają na ziemi.","Przytrzymaj skurcz na szczycie sekundę.","Opuść powoli stopy do pełnego rozciągnięcia przodu goleni."],proTip:"Unoszenie palców angażuje mięsień piszczelowy przedni; prowadź ruch powoli w pełnym kontrolowanym zakresie.",targetMuscles:["Piszczelowy przedni","Prostowniki palców"],primaryMuscle:"calves",equipment:"Masa ciała"},"Skakanka jako trening łydek":{steps:["Chwyć skakankę, łokcie blisko tułowia, stopy razem.","Obracaj skakankę nadgarstkami i odbijaj się nisko ze śródstopia.","Ląduj miękko na palcach, amortyzując łydkami i kostkami.","Utrzymuj równy rytm i sprężystą pracę stawu skokowego przez cały czas trwania serii."],proTip:"Skacz nisko i ląduj miękko na śródstopiu, utrzymując równy rytm i lekko ugięte kolana.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty","Piszczelowy przedni"],primaryMuscle:"calves",equipment:"Skakanka"},"Wspięcia na palce z kettlebell stojąc":{steps:["Trzymaj kettlebell oburącz przed sobą lub po jednej w każdej ręce wzdłuż ciała.","Stań śródstopiami na krążku lub stopniu, pięty w powietrzu.","Opuść pięty poniżej poziomu podwyższenia, rozciągając łydki.","Wespnij się jak najwyżej na palcach, napinając łydki na szczycie.","Opuść kontrolowanie do pełnego rozciągnięcia."],proTip:"Kettlebell trzymany nisko obniża środek ciężkości i ułatwia balans przy dużym zakresie ruchu.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Kettlebell"},"Wspięcia na palce na hack squacie":{steps:["Ustaw się w maszynie hack squat tyłem do oparcia, barki pod poduszkami.","Postaw śródstopia na dolnej krawędzi platformy, pięty w powietrzu, wyprostuj nogi i odbezpiecz.","Opuść pięty maksymalnie w dół, rozciągając łydki.","Wypchnij ciężar palcami, prostując stopy w pełnym zakresie.","Przytrzymaj szczyt i wróć kontrolowanie."],proTip:"Stały kąt oparcia hack squata izoluje łydki bez konieczności stabilizacji korpusu.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Maszyna Hack Squat"},"Wspięcia na palce na suwnicy siedząc (zgięte kolana)":{steps:["Ustaw ławkę pod gryfem suwnicy i usiądź, stopy śródstopiem na krążku przed sobą.","Oprzyj gryf na udach tuż nad kolanami i podłóż ręcznik dla komfortu, odbezpiecz suwnicę.","Opuść pięty poniżej poziomu krążka, rozciągając łydki.","Unieś pięty jak najwyżej, napinając płaszczkowaty na szczycie.","Opuść kontrolowanie do pełnego rozciągnięcia."],proTip:"Zgięte kolano wyłącza brzuchaty i przerzuca pracę na płaszczkowaty, kluczowy dla grubości łydki.",targetMuscles:["Płaszczkowaty","Brzuchaty łydki"],primaryMuscle:"calves",equipment:"Maszyna Smitha"},"Spacer farmera (Farmer's Walk)":{steps:["Ustaw dwa hantle lub uchwyty po bokach stóp i stań między nimi.","Ugnij biodra i kolana, chwyć oba ciężary, a następnie wstań z napiętym brzuchem i wyprostowanym tułowiem.","Opuść barki, trzymaj ręce prosto i patrz przed siebie.","Idź krótkimi, równymi krokami przez wyznaczony dystans lub czas, nie kołysząc ciężarami.","Zatrzymaj się, ugnij biodra i kolana, po czym odłóż oba ciężary pod kontrolą."],proTip:"Dobierz ciężar, przy którym utrzymasz równy krok, stabilny tułów i pewny chwyt przez całą serię.",targetMuscles:["Przedramiona","Mięśnie brzucha","Czworoboczne","Pośladki"],primaryMuscle:"core",equipment:"Hantle lub uchwyty farmera"},"Dipy wspomagane na maszynie":{steps:["Ustaw poziom asysty maszyny; większa asysta ułatwia wykonanie ruchu.","Wejdź na stopień, chwyć poręcze i oprzyj kolana lub stopy na ruchomej platformie.","Opuść barki, napnij brzuch i rozpocznij z wyprostowanymi ramionami.","Ugnij łokcie i opuszczaj tułów powoli tylko do zakresu, w którym zachowujesz kontrolę.","Odepchnij poręcze, wróć do góry bez gwałtownego blokowania łokci, a po serii poczekaj, aż platforma się zatrzyma przed zejściem."],proTip:"Najpierw opanuj równy ruch z większą asystą; zmniejszaj ją dopiero wtedy, gdy każde powtórzenie wygląda tak samo.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Maszyna do dipów z asystą"},"Wyciskanie sztangi z podłogi (Floor Press)":{steps:["Połóż się na podłodze w klatce do przysiadów, gryf nad linią klatki, kolana ugięte lub nogi wyprostowane.","Chwyć gryf nieco szerzej niż barki, ściągnij łopatki i zdejmij sztangę z zabezpieczeń.","Opuść sztangę kontrolowanie, aż tylna część ramion oprze się o podłogę, łokcie ok. 45 stopni od tułowia.","Zatrzymaj się na chwilę bez rozluźniania i wypchnij sztangę w górę do wyprostu ramion."],proTip:"Nie odbijaj łokci od podłogi. Pełna pauza sprawia, że każde powtórzenie zaczynasz z martwego punktu, co buduje siłę w końcowej fazie wyciskania.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Sztanga olimpijska + stojaki"},"Wyciskanie hantli z podłogi (Dumbbell Floor Press)":{steps:["Usiądź na podłodze z hantlami na udach, połóż się na plecach i ustaw hantle nad klatką.","Ugnij kolana, stopy oprzyj na podłodze, ściągnij łopatki.","Opuść hantle kontrolowanie, aż ramiona oprą się o podłogę, łokcie ok. 45 stopni od tułowia.","Wyciśnij hantle w górę, zbliżając je nad środkiem klatki bez stukania."],proTip:"Dobre ćwiczenie do domu bez ławki. Ramiona dotykają podłogi lekko, bez odbijania, a nadgarstki trzymaj nad łokciami.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle"},"Rozpiętki hantlami na skosie":{steps:["Ustaw ławkę pod kątem ok. 30 stopni i połóż się z hantlami wyciśniętymi nad górną częścią klatki.","Obróć dłonie do siebie i lekko ugnij łokcie, utrzymując ten kąt przez całą serię.","Rozłóż ramiona szeroko po łuku, aż poczujesz rozciągnięcie górnej części klatki.","Zbliż hantle z powrotem nad klatkę tym samym łukiem, ściskając mięśnie piersiowe."],proTip:"Wybierz lżejsze hantle niż do wyciskania. Jeśli łokcie zaczynają się zginać coraz mocniej, ruch zamienia się w wyciskanie i czas zakończyć serię.",targetMuscles:["Górna część klatki piersiowej","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle + ławka skośna"},"Rozpiętki hantlami na podłodze (Floor Fly)":{steps:["Połóż się na plecach na podłodze, kolana ugięte, hantle wyciśnięte nad klatką, dłonie zwrócone do siebie.","Lekko ugnij łokcie i zablokuj ten kąt.","Rozłóż ramiona na boki po łuku, aż łokcie lekko dotkną podłogi.","Zbliż hantle nad klatkę, napinając mięśnie piersiowe w górnej pozycji."],proTip:"Podłoga sama wyznacza koniec zakresu, więc możesz skupić się na spięciu klatki. Nie odkładaj ciężaru łokciami na ziemię, tylko ją muśnij.",targetMuscles:["Klatka piersiowa","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Hantle"},"Rozpiętki na wyciągu jednorącz":{steps:["Ustaw bloczek na wysokości barku, chwyć uchwyt dalszą ręką i zrób krok od wyciągu.","Stań w lekkim wykroku, łokieć lekko ugięty, ramię odciągnięte do tyłu do rozciągnięcia klatki.","Przeprowadź uchwyt po łuku przed klatkę, aż dłoń minie środek ciała.","Wróć powoli do pozycji wyjściowej, kontrolując rozciąganie, i dokończ serię przed zmianą strony."],proTip:"Tułów trzymaj nieruchomo i nie skręcaj go razem z ramieniem. Praca jednorącz pozwala wyraźnie poczuć skurcz na końcu ruchu.",targetMuscles:["Klatka piersiowa","Wewnętrzna część klatki piersiowej","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Wyciąg"},"Rozpiętki na wyciągu na ławce skośnej (Incline Cable Fly)":{steps:["Ustaw ławkę skośną (ok. 30 stopni) między dwoma wyciągami z bloczkami na najniższej pozycji.","Chwyć uchwyty, połóż się i unieś je nad klatkę, łokcie lekko ugięte, dłonie do siebie.","Rozłóż ramiona po łuku na boki, aż poczujesz rozciągnięcie górnej części klatki.","Zbliż uchwyty nad klatkę tym samym łukiem i przytrzymaj spięcie przez sekundę."],proTip:"Wyciąg utrzymuje napięcie także w górnej pozycji, w której przy hantlach go brakuje. Nie stukaj uchwytami, zatrzymaj je tuż obok siebie.",targetMuscles:["Górna część klatki piersiowej","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Wyciąg + ławka skośna"},"Pompki na kolanach":{steps:["Uklęknij, oprzyj dłonie na podłodze nieco szerzej niż barki i przesuń biodra do przodu, aż tułów utworzy prostą linię od głowy do kolan.","Napnij brzuch i pośladki, łokcie skieruj ok. 45 stopni od tułowia.","Opuść klatkę kontrolowanie, aż znajdzie się tuż nad podłogą.","Wypchnij się z dłoni do wyprostu ramion, nie wypychając bioder w górę."],proTip:"Gdy zrobisz 3 serie po 12-15 powtórzeń w pełnym zakresie, przejdź do pompek z rękami na podwyższeniu albo klasycznych.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Masa ciała"},"Pompki z rękami na podwyższeniu (Incline Push-up)":{steps:["Oprzyj dłonie na krawędzi ławki lub skrzyni nieco szerzej niż barki, nogi cofnij tak, by ciało tworzyło prostą linię.","Napnij brzuch i pośladki, łokcie skieruj ok. 45 stopni od tułowia.","Opuść klatkę do krawędzi podwyższenia, utrzymując prostą linię ciała.","Wypchnij się do wyprostu ramion i powtórz."],proTip:"Progresję zrobisz, obniżając podparcie: od blatu stołu, przez ławkę, aż do podłogi.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Masa ciała + ławka"},"Pompki z klaśnięciem (Plyometric Push-up)":{steps:["Przyjmij pozycję pompki, dłonie nieco szerzej niż barki, ciało w jednej linii, brzuch napięty.","Opuść klatkę nisko nad podłogę w kontrolowanym tempie.","Wypchnij się z maksymalną siłą, tak by dłonie oderwały się od podłogi, i szybko klaśnij.","Wyląduj na dłoniach z lekko ugiętymi łokciami, zamortyzuj ruch i od razu przejdź do kolejnego powtórzenia albo zresetuj pozycję."],proTip:"To ćwiczenie mocy, nie objętości. Rób krótkie serie po 3-6 powtórzeń i kończ, gdy wybicie traci wysokość.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Masa ciała"},"Wyciskanie z pauzą na klatce (Paused Bench Press)":{steps:["Połóż się na ławce, oczy pod gryfem, łopatki ściągnięte, stopy mocno na podłodze.","Zdejmij sztangę i opuść ją kontrolowanie do dolnej części klatki.","Zatrzymaj sztangę na klatce na 1-2 sekundy, utrzymując napięcie całego ciała.","Wypchnij sztangę w górę do wyprostu ramion bez utraty pozycji łopatek."],proTip:"Weź ok. 10-15% mniej niż do zwykłego wyciskania. Pauza uczy kontroli w najniższym punkcie i odbiera pomoc z odbicia.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Sztanga olimpijska + ławka"},"Wyciskanie Larsena (nogi w powietrzu)":{steps:["Połóż się na ławce, łopatki ściągnięte, chwyć gryf jak do zwykłego wyciskania.","Unieś nogi nad podłogę, wyprostowane lub ugięte, i napnij brzuch, by utrzymać stabilną pozycję.","Zdejmij sztangę i opuść ją kontrolowanie do dolnej części klatki.","Wyciśnij sztangę w górę bez przechylania się na boki i bez podpierania nogami."],proTip:"Użyj wyraźnie mniejszego ciężaru niż zwykle. Każde przechylenie sztangi pokazuje, która strona jest słabsza.",targetMuscles:["Klatka piersiowa","Triceps","Mięśnie głębokie tułowia"],primaryMuscle:"chest",equipment:"Sztanga olimpijska + ławka"},"Wyciskanie hantla jednorącz na ławce płaskiej":{steps:["Połóż się na ławce płaskiej z hantlem w jednej ręce nad klatką, stopy szeroko na podłodze.","Ściągnij łopatki i napnij brzuch, żeby tułów nie obracał się w stronę ciężaru.","Opuść hantel kontrolowanie do boku klatki, łokieć ok. 45 stopni od tułowia.","Wyciśnij hantel w górę nad bark i dokończ serię przed zmianą strony."],proTip:"Ciężar tylko po jednej stronie wymusza pracę mięśni tułowia. Zaczynaj serię słabszą ręką i taką samą liczbę powtórzeń zrób drugą.",targetMuscles:["Klatka piersiowa","Triceps","Mięśnie skośne brzucha"],primaryMuscle:"chest",equipment:"Hantla + ławka"},"Wyciskanie gumą oporową stojąc":{steps:["Zaczep gumę na wysokości klatki za plecami (drzwi, słup, drabinka) i chwyć oba końce.","Stań w lekkim wykroku tyłem do punktu zaczepienia, dłonie przy klatce, łokcie za linią tułowia.","Wypchnij dłonie przed siebie do wyprostu ramion, lekko je do siebie zbliżając.","Wróć powoli do pozycji wyjściowej, kontrolując napięcie gumy."],proTip:"Odejdź na tyle daleko, żeby guma była napięta już na starcie. Na końcu ruchu zatrzymaj się na sekundę i mocno ściśnij klatkę.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Guma oporowa"},"Wyciskanie kettlebell z podłogi jednorącz":{steps:["Połóż się na plecach, przetocz się lekko na bok i chwyć rączkę kettlebell, potem wróć na plecy z ciężarem przy klatce.","Ugnij kolana, stopy oprzyj na podłodze, nadgarstek trzymaj prosto, kula spoczywa na przedramieniu.","Wyciśnij kettlebell w górę nad bark do wyprostu ramienia.","Opuść ciężar kontrolowanie, aż ramię dotknie podłogi, i dokończ serię przed zmianą strony."],proTip:"Do odkładania ciężaru też przetocz się na bok, trzymając kettlebell przy klatce. Nie opuszczaj go prostą ręką nad twarzą.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Kettlebell"},"Wiosłowanie w leżeniu na ławce (Seal Row)":{steps:["Ustaw ławkę płaską na podwyższeniu tak, by z wyprostowanymi rękami sztanga nie dotykała podłogi.","Połóż się przodem, klatka na krawędzi ławki, chwyć sztangę nachwytem nieco szerzej niż barki.","Ściągnij łopatki i przyciągnij sztangę do spodu ławki, prowadząc łokcie w tył.","Opuść sztangę kontrolowanie do pełnego wyprostu ramion i rozciągnięcia pleców."],proTip:"Podparcie klatki wyklucza bujanie tułowiem, więc cała praca zostaje w plecach. Można też wiosłować hantlami.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Tylne aktony barków"],primaryMuscle:"back",equipment:"Sztanga + wysoka ławka"},"Wiosłowanie na wyciągu jednorącz siedząc":{steps:["Usiądź przy wyciągu dolnym, stopy na podpórkach, chwyć pojedynczy uchwyt jedną ręką.","Wyprostuj plecy, pozwól ramieniu wysunąć się do przodu, aż poczujesz rozciągnięcie pleców.","Przyciągnij uchwyt do biodra, prowadząc łokieć blisko tułowia, bez skręcania tułowia.","Wróć powoli do pełnego wyprostu ramienia i dokończ serię przed zmianą strony."],proTip:"Myśl o przyciąganiu łokcia do kieszeni, a nie dłoni do klatki. Tak lepiej czujesz najszerszy grzbietu.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Biceps"],primaryMuscle:"back",equipment:"Wyciąg"},"Ściąganie drążka jednorącz na wyciągu":{steps:["Załóż pojedynczy uchwyt na wyciąg górny, usiądź lub uklęknij na jedno kolano pod wyciągiem.","Chwyć uchwyt, wyprostuj ramię nad głową i pozwól łopatce unieść się do rozciągnięcia.","Ściągnij łokieć w dół do boku tułowia, aż dłoń znajdzie się przy barku.","Wróć powoli do pełnego wyprostu ramienia i dokończ serię przed zmianą strony."],proTip:"Nie przechylaj tułowia, żeby dociągnąć ciężar. Pełne rozciągnięcie u góry to najważniejsza część tego wariantu.",targetMuscles:["Najszerszy grzbietu","Obły większy","Biceps"],primaryMuscle:"back",equipment:"Wyciąg górny"},"Wiosłowanie sztangą podchwytem (Yates Row)":{steps:["Chwyć sztangę podchwytem na szerokość barków i wstań z nią jak do martwego ciągu.","Pochyl tułów do ok. 30-45 stopni od pionu, kolana lekko ugięte, plecy proste.","Przyciągnij sztangę do dolnej części brzucha, prowadząc łokcie blisko tułowia.","Opuść sztangę kontrolowanie do wyprostu ramion, bez zmiany kąta tułowia."],proTip:"Chwyt podchwytem mocniej angażuje biceps i dolną część najszerszego. Nie prostuj tułowia, żeby podrzucić ciężar.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Biceps"],primaryMuscle:"back",equipment:"Sztanga olimpijska"},"Wiosłowanie kettlebell jednorącz":{steps:["Oprzyj jedną dłoń i to samo kolano na ławce, drugą nogę postaw na podłodze, plecy równolegle do podłoża.","Chwyć kettlebell wolną ręką, ramię wyprostowane pod barkiem.","Przyciągnij kettlebell do biodra, prowadząc łokieć blisko tułowia.","Opuść ciężar kontrolowanie do pełnego wyprostu ramienia i dokończ serię przed zmianą strony."],proTip:"Rączka kettlebell pozwala na chwyt neutralny i naturalny tor łokcia. Barki trzymaj równo, bez obracania tułowia do góry.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Tylne aktony barków"],primaryMuscle:"back",equipment:"Kettlebell + ławka"},"Podciąganie szerokim chwytem":{steps:["Chwyć drążek nachwytem ok. 1,5 raza szerzej niż barki i zawiśnij na wyprostowanych rękach.","Ściągnij łopatki w dół i napnij brzuch, nogi trzymaj razem bez bujania.","Podciągnij się, prowadząc łokcie w dół i na boki, aż broda znajdzie się nad drążkiem.","Opuść się powoli do pełnego zwisu i dopiero wtedy zacznij kolejne powtórzenie."],proTip:"Szeroki chwyt skraca zakres i jest trudniejszy niż standardowy. Jeśli nie robisz 8 czystych podciągnięć zwykłym chwytem, zostań przy nim.",targetMuscles:["Najszerszy grzbietu","Obły większy","Biceps"],primaryMuscle:"back",equipment:"Drążek"},"Podciąganie chwytem neutralnym":{steps:["Chwyć równoległe uchwyty drążka, dłonie zwrócone do siebie, i zawiśnij na wyprostowanych rękach.","Ściągnij łopatki w dół i napnij brzuch.","Podciągnij się, prowadząc łokcie w dół wzdłuż tułowia, aż broda znajdzie się nad uchwytami.","Opuść się powoli do pełnego zwisu."],proTip:"Chwyt neutralny zwykle pozwala zrobić więcej powtórzeń niż nachwyt. Dociążenie dodawaj dopiero przy 3 seriach po 8-10 czystych powtórzeń.",targetMuscles:["Najszerszy grzbietu","Biceps","Ramienny"],primaryMuscle:"back",equipment:"Drążek z uchwytami równoległymi"},"Podciąganie z gumą (asysta)":{steps:["Przełóż gumę przez drążek, przeciągnij jeden koniec przez drugi i dociągnij pętlę do drążka.","Chwyć drążek nachwytem na szerokość barków, włóż stopę lub kolano w pętlę i zawiśnij.","Podciągnij się, prowadząc łokcie w dół, aż broda znajdzie się nad drążkiem.","Opuść się powoli do pełnego zwisu i ostrożnie wyjmij nogę z gumy po serii."],proTip:"Zacznij od grubej gumy i zmieniaj ją na cieńszą, gdy zrobisz 3 serie po 8 powtórzeń. Wejdź w gumę ze skrzyni, nie zeskakuj z niej gwałtownie.",targetMuscles:["Najszerszy grzbietu","Biceps","Obły większy"],primaryMuscle:"back",equipment:"Drążek + guma oporowa"},"Podciąganie negatywne (Negative Pull-Up)":{steps:["Postaw skrzynię lub ławkę pod drążkiem i chwyć go nachwytem na szerokość barków.","Wejdź lub podskocz tak, by broda znalazła się nad drążkiem, łokcie przy tułowiu.","Zdejmij nogi ze skrzyni i opuszczaj się powoli przez 3-5 sekund do pełnego zwisu.","Stań z powrotem na skrzyni i powtórz, zamiast podciągać się z dołu."],proTip:"To krok w stronę pierwszego pełnego podciągnięcia. Gdy nie utrzymujesz już wolnego tempa, zakończ serię.",targetMuscles:["Najszerszy grzbietu","Biceps","Przedramiona"],primaryMuscle:"back",equipment:"Drążek + skrzynia"},"Podciąganie łopatek na drążku (Scapular Pull-Up)":{steps:["Zawiśnij na drążku nachwytem na szerokość barków, ręce proste, barki uniesione do uszu.","Napnij brzuch i trzymaj nogi razem.","Ściągnij łopatki w dół i lekko do tyłu, unosząc ciało bez zginania łokci.","Wróć powoli do swobodnego zwisu i powtórz."],proTip:"Ruch jest krótki, ale uczy pierwszej fazy każdego podciągnięcia. Zatrzymaj się na sekundę w górnej pozycji.",targetMuscles:["Czworoboczny","Najszerszy grzbietu","Romboidalne"],primaryMuscle:"back",equipment:"Drążek"},"Wiosłowanie hantlami w opadzie tułowia":{steps:["Stań z hantlami w dłoniach, stopy na szerokość bioder, kolana lekko ugięte.","Pochyl tułów w biodrach do ok. 45 stopni, plecy proste, hantle zwisają pod barkami.","Przyciągnij oba hantle do bioder, prowadząc łokcie w tył blisko tułowia.","Opuść hantle kontrolowanie do wyprostu ramion, utrzymując kąt tułowia."],proTip:"Jeśli czujesz, że tułów się podnosi, weź lżejsze hantle. Dłonie mogą być zwrócone do siebie, to często wygodniejsze dla łokci.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Tylne aktony barków"],primaryMuscle:"back",equipment:"Hantle"},"Wiosłowanie gumą oporową siedząc":{steps:["Usiądź na podłodze z wyprostowanymi nogami, owiń gumę wokół stóp lub zaczep ją o stały punkt na wysokości stóp.","Chwyć końce gumy, wyprostuj plecy, ramiona wyciągnięte przed siebie.","Przyciągnij dłonie do brzucha, ściągając łopatki i prowadząc łokcie blisko tułowia.","Wróć powoli do wyprostu ramion, nie pochylając się do przodu."],proTip:"W końcowej pozycji zatrzymaj się na sekundę ze ściągniętymi łopatkami. Skróć gumę, jeśli brakuje oporu.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Biceps"],primaryMuscle:"back",equipment:"Guma oporowa"},"Ściąganie gumy oporowej do klatki (Band Lat Pulldown)":{steps:["Zaczep gumę wysoko (drążek, górna krawędź drzwi z kotwą) i uklęknij lub usiądź pod nią.","Chwyć końce gumy, ramiona wyprostowane w górę, lekko pochyl tułów do tyłu.","Ściągnij łokcie w dół do boków tułowia, aż dłonie znajdą się przy barkach.","Wróć powoli do wyprostu ramion nad głową."],proTip:"Domowy zamiennik ściągania drążka. Na dole ściągnij łopatki w dół i przytrzymaj pozycję przez sekundę.",targetMuscles:["Najszerszy grzbietu","Obły większy","Biceps"],primaryMuscle:"back",equipment:"Guma oporowa"},"Wiosłowanie na taśmach treningowych (Suspension Row)":{steps:["Chwyć uchwyty taśm, odchyl się do tyłu z wyprostowanymi rękami, stopy oprzyj przed punktem zaczepu.","Napnij brzuch i pośladki, by ciało tworzyło prostą linię od głowy do pięt.","Ściągnij łopatki i przyciągnij klatkę do dłoni, łokcie prowadź blisko tułowia.","Opuść się powoli do pełnego wyprostu rąk, nie pozwalając biodrom opaść."],proTip:"Trudność regulujesz ustawieniem stóp: krok do przodu utrudnia, krok do tyłu ułatwia ruch.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Tylne aktony barków","Biceps"],primaryMuscle:"back",equipment:"Taśmy treningowe podwieszane"},"Szrugi z trap barem":{steps:["Stań w środku trap bara, chwyć uchwyty i podnieś go jak w martwym ciągu.","Wyprostuj się, ręce proste, barki swobodnie opuszczone.","Unieś barki pionowo w górę jak najwyżej, bez zginania łokci.","Zatrzymaj ruch na sekundę u góry i opuść barki powoli do pełnego rozciągnięcia."],proTip:"Nie kręć barkami w kółko. Ruch prosto w górę i w dół wystarcza, a pauza na górze daje więcej niż większy ciężar.",targetMuscles:["Czworoboczny (góra)","Dźwigacz łopatki","Przedramiona"],primaryMuscle:"back",equipment:"Trap bar (gryf heksagonalny)"},"Wiosłowanie na maszynie siedząc (z oparciem klatki)":{steps:["Ustaw wysokość siedziska tak, by uchwyty były na wysokości dolnej części klatki.","Usiądź, oprzyj klatkę o poduszkę i chwyć uchwyty z wyprostowanymi rękami.","Przyciągnij uchwyty do tułowia, prowadząc łokcie do tyłu i ściągając łopatki.","Wróć powoli do wyprostu rąk, pozwalając łopatkom rozsunąć się na końcu ruchu."],proTip:"Nie odrywaj klatki od oparcia. Gdy odchylasz tułów, pracę przejmuje rozpęd zamiast pleców.",targetMuscles:["Najszerszy grzbietu","Romboidalne","Czworoboczny","Biceps"],primaryMuscle:"back",equipment:"Maszyna"},"Ściąganie na maszynie z talerzami (Plate-Loaded Pulldown)":{steps:["Załaduj talerze, usiądź i zablokuj uda pod wałkami.","Chwyć uchwyty z wyprostowanymi rękami, klatka lekko uniesiona.","Ściągnij uchwyty w dół, prowadząc łokcie do bioder, aż dłonie znajdą się przy barkach.","Wróć powoli w górę do pełnego wyprostu rąk i rozciągnięcia pleców."],proTip:"Maszyna pozwala pracować każdą ręką osobno. Jeśli jedna strona jest słabsza, zacznij serię od niej.",targetMuscles:["Najszerszy grzbietu","Obły większy","Biceps"],primaryMuscle:"back",equipment:"Maszyna (plate-loaded)"},"Prostowanie tułowia na maszynie siedząc":{steps:["Ustaw siedzisko tak, by wałek oparcia leżał na środku pleców, stopy oprzyj na podnóżkach.","Skrzyżuj ręce na klatce lub chwyć uchwyty, napnij brzuch.","Odchyl tułów do tyłu, pchając wałek plecami, aż tułów znajdzie się w linii z udami.","Wróć powoli do pozycji wyjściowej, nie pozwalając ciężarowi opaść."],proTip:"Zacznij od lekkiego ciężaru i równego tempa. Ruch ma być płynny, bez wybicia z bioder.",targetMuscles:["Prostowniki grzbietu","Pośladki","Dwugłowe uda"],primaryMuscle:"back",equipment:"Maszyna"},"Wyciskanie hantli nad głowę stojąc":{steps:["Stań w rozkroku na szerokość bioder, hantle trzymaj na wysokości barków, dłonie do przodu.","Napnij brzuch i pośladki, żebra skierowane w dół.","Wyciśnij hantle w górę nad głowę do wyprostu rąk, głowa lekko przechodzi do przodu na końcu.","Opuść hantle powoli do wysokości barków."],proTip:"Jeśli odchylasz się do tyłu, żeby dokończyć powtórzenie, ciężar jest za duży.",targetMuscles:["Przedni akton barku","Aktony boczne barku","Triceps","Mięśnie głębokie tułowia"],primaryMuscle:"shoulders",equipment:"Hantle"},"Wyciskanie hantla nad głowę w klęku jednorącz":{steps:["Uklęknij na jedno kolano, druga stopa z przodu, oba kolana zgięte pod kątem prostym.","Trzymaj hantel przy barku po stronie kolana opartego o ziemię, napnij pośladek tej strony.","Wyciśnij hantel w górę nad bark bez przechylania tułowia na bok.","Opuść hantel powoli do barku i dokończ serię, potem zmień stronę."],proTip:"Pozycja w klęku utrudnia wyginanie lędźwi, więc łatwiej wyczuć, czy tułów zostaje prosty.",targetMuscles:["Przedni akton barku","Triceps","Mięśnie skośne brzucha"],primaryMuscle:"shoulders",equipment:"Hantle"},"Wyciskanie sztangi z wybiciem (Push Press)":{steps:["Stań ze sztangą na przedniej części barków, chwyt nieco szerzej niż barki, łokcie lekko przed gryfem.","Ugnij krótko kolana, tułów pionowo, pięty na podłodze.","Wybij się dynamicznie z nóg i przenieś ten impuls na sztangę, wyciskając ją nad głowę.","Zablokuj ręce nad głową, a następnie opuść sztangę pod kontrolą na barki."],proTip:"Ugięcie ma być płytkie i szybkie. Gdy zejdziesz za nisko, ruch zamienia się w przysiad i traci moc.",targetMuscles:["Przedni akton barku","Triceps","Czworogłowe uda","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Sztanga olimpijska"},"Wyciskanie kettlebell nad głowę jednorącz":{steps:["Ustaw kettlebell przy barku, kula oparta o przedramię, nadgarstek prosty.","Napnij brzuch i pośladki, wolną rękę trzymaj wzdłuż tułowia.","Wyciśnij kettlebell nad głowę, obracając lekko dłoń do przodu, aż ręka się wyprostuje.","Opuść kettlebell powoli z powrotem do pozycji przy barku."],proTip:"Trzymaj nadgarstek prosto, a nie odgięty. Ciężar ma leżeć na przedramieniu, nie ciągnąć dłoni do tyłu.",targetMuscles:["Przedni akton barku","Triceps","Mięśnie skośne brzucha"],primaryMuscle:"shoulders",equipment:"Kettlebell"},"Odwrotne rozpiętki na wyciągu (tył barku)":{steps:["Ustaw bloczki na wysokości barków, chwyć lewą linkę prawą ręką i prawą linkę lewą, bez uchwytów lub z kulkami.","Cofnij się o krok, ręce przed sobą skrzyżowane, łokcie lekko ugięte.","Rozciągnij ramiona szeroko na boki po łuku, aż dłonie znajdą się w linii z barkami.","Wróć powoli do skrzyżowania rąk przed klatką."],proTip:"Myśl o odpychaniu dłoni na boki, a nie o ściąganiu łopatek. Wtedy pracuje tył barku, a nie środek pleców.",targetMuscles:["Tylne aktony barków","Romboidalne","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Wyciąg"},"Wznosy hantli w przód (Front Raise)":{steps:["Stań prosto, hantle przed udami, dłonie skierowane do ciała lub do siebie.","Napnij brzuch i lekko ugnij łokcie.","Unieś hantle przed sobą do wysokości barków.","Opuść je powoli do ud, nie pozwalając im opaść."],proTip:"Przedni akton barku pracuje mocno przy każdym wyciskaniu. Jeśli robisz dużo wyciskań, wystarczą tu 2-3 serie.",targetMuscles:["Przedni akton barku","Aktony boczne barku"],primaryMuscle:"shoulders",equipment:"Hantle"},"Rotacja zewnętrzna ramienia na wyciągu":{steps:["Ustaw bloczek na wysokości łokcia i stań bokiem do wyciągu.","Chwyć uchwyt ręką dalszą od wyciągu, łokieć przyciśnij do boku i zegnij pod kątem prostym.","Obróć przedramię na zewnątrz, nie odrywając łokcia od tułowia.","Wróć powoli do pozycji wyjściowej i dokończ serię, potem zmień stronę."],proTip:"Użyj lekkiego ciężaru i wolnego tempa. Zwinięty ręcznik między łokciem a tułowiem pomaga utrzymać łokieć w miejscu.",targetMuscles:["Rotatory zewnętrzne barku","Tylny akton barku"],primaryMuscle:"shoulders",equipment:"Wyciąg"},"Wznosy Y na wyciągu (Cable Y-Raise)":{steps:["Ustaw bloczki nisko, chwyć linki na krzyż: lewą prawą ręką, prawą lewą.","Cofnij się o krok, lekko pochyl tułów do przodu, ręce skrzyżowane przed biodrami.","Unieś ręce ukośnie w górę i na zewnątrz, aż ciało utworzy literę Y.","Opuść ręce powoli do skrzyżowania przed biodrami."],proTip:"Nie unoś rąk wyżej, niż pozwala ci to zrobić bez zadzierania barków do uszu.",targetMuscles:["Aktony boczne barku","Czworoboczny","Tylne aktony barków"],primaryMuscle:"shoulders",equipment:"Wyciąg"},"Wyciskanie gumy oporowej nad głowę":{steps:["Stań na środku gumy stopami na szerokość bioder, końce gumy trzymaj przy barkach.","Napnij brzuch i pośladki, łokcie pod dłońmi.","Wyciśnij ręce w górę nad głowę do pełnego wyprostu.","Opuść dłonie powoli do barków, utrzymując napięcie gumy."],proTip:"Szerszy rozstaw stóp na gumie zwiększa opór, węższy go zmniejsza.",targetMuscles:["Przedni akton barku","Aktony boczne barku","Triceps"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Rozciąganie gumy przed sobą (Band Pull-Apart)":{steps:["Chwyć gumę nachwytem na szerokość barków, ręce wyprostowane przed sobą na wysokości barków.","Opuść barki i napnij brzuch.","Rozciągnij gumę, prowadząc ręce na boki, aż dotknie klatki.","Wróć powoli do pozycji wyjściowej, nie tracąc napięcia gumy."],proTip:"Węższy chwyt utrudnia ruch. Ćwiczenie dobrze działa jako rozgrzewka przed wyciskaniem.",targetMuscles:["Tylne aktony barków","Romboidalne","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Face Pull z gumą oporową":{steps:["Zaczep gumę na wysokości twarzy i chwyć oba końce nachwytem.","Cofnij się, aż guma będzie napięta przy wyprostowanych rękach.","Przyciągnij końce gumy do twarzy, łokcie wysoko i na boki, dłonie kończą przy uszach.","Wróć powoli do wyprostu rąk."],proTip:"Na końcu ruchu obróć dłonie tak, jakbyś pokazywał biceps. To angażuje tył barku mocniej niż samo przyciąganie.",targetMuscles:["Tylne aktony barków","Rotatory zewnętrzne barku","Czworoboczny"],primaryMuscle:"shoulders",equipment:"Guma oporowa"},"Krążenia kettlebell wokół głowy (Kettlebell Halo)":{steps:["Stań w lekkim rozkroku, chwyć kettlebell oburącz za boki rączki, dnem do góry przed klatką.","Napnij brzuch i pośladki.","Prowadź kettlebell wokół głowy, blisko niej, przechodząc za karkiem i wracając przed klatkę.","Wykonaj zadaną liczbę okrążeń w jedną stronę, potem w drugą."],proTip:"Tułów i biodra mają stać w miejscu. Jeśli całe ciało się kołysze, weź lżejszy kettlebell.",targetMuscles:["Aktony barków","Czworoboczny","Mięśnie głębokie tułowia"],primaryMuscle:"shoulders",equipment:"Kettlebell"},"Przysiad z hantlami":{steps:["Stań w rozkroku na szerokość barków, hantle trzymaj po bokach ciała.","Napnij brzuch, wzrok przed siebie.","Zejdź w przysiad, kolana prowadź w linii stóp, aż uda będą co najmniej równoległe do podłogi.","Wstań, pchając podłogę całymi stopami."],proTip:"Gdy hantle zaczynają ograniczać ciężar przez chwyt, przejdź na przysiad goblet albo użyj pasków.",targetMuscles:["Czworogłowe uda","Pośladki","Przywodziciele"],primaryMuscle:"quads",equipment:"Hantle"},"Przysiad przedni z hantlami":{steps:["Unieś hantle i oprzyj ich końce na przedniej części barków, łokcie skierowane do przodu.","Stań w rozkroku na szerokość barków, napnij brzuch.","Zejdź w przysiad z tułowiem jak najbardziej pionowym, kolana w linii stóp.","Wstań, utrzymując łokcie wysoko przez cały ruch."],proTip:"Opadające łokcie ciągną tułów do przodu. Pilnuj ich wysokości, zwłaszcza przy wstawaniu.",targetMuscles:["Czworogłowe uda","Pośladki","Mięśnie głębokie tułowia"],primaryMuscle:"quads",equipment:"Hantle"},"Przysiad ze sztangą z pauzą (Pause Squat)":{steps:["Ustaw sztangę na górze pleców, zdejmij ją ze stojaków i stań w rozkroku jak do przysiadu.","Weź głęboki wdech i napnij brzuch.","Zejdź w przysiad do swojej pełnej głębokości i zatrzymaj się na 2-3 sekundy, utrzymując napięcie.","Wstań dynamicznie bez odbicia, wydychając powietrze na górze."],proTip:"Użyj ok. 70-80% ciężaru z normalnego przysiadu. Pauza uczy utrzymania pozycji w najtrudniejszym punkcie.",targetMuscles:["Czworogłowe uda","Pośladki","Prostowniki grzbietu"],primaryMuscle:"quads",equipment:"Sztanga olimpijska"},"Przysiad landmine":{steps:["Umieść jeden koniec sztangi w uchwycie landmine, drugi chwyć oburącz przy klatce.","Stań w rozkroku na szerokość barków, lekko pochylony w stronę sztangi.","Zejdź w przysiad, kolana w linii stóp, tułów pionowo.","Wstań, pchając podłogę, i wypchnij biodra na górze."],proTip:"Sztanga prowadzi tor ruchu, więc to dobre ćwiczenie do nauki przysiadu przed sztangą na plecach.",targetMuscles:["Czworogłowe uda","Pośladki","Mięśnie głębokie tułowia"],primaryMuscle:"quads",equipment:"Sztanga w gnieździe (landmine)"},"Wykroki w tył ze sztangą":{steps:["Ustaw sztangę na górze pleców i stań prosto, stopy na szerokość bioder.","Zrób długi krok w tył jedną nogą.","Opuść się, aż tylne kolano prawie dotknie podłogi, przednie kolano w linii stopy.","Odepchnij się przednią nogą i wróć do pozycji wyjściowej."],proTip:"Krok w tył jest łatwiejszy do kontrolowania niż w przód. Ustaw stopy na szerokość bioder, jak na torach, a nie na jednej linii.",targetMuscles:["Czworogłowe uda","Pośladki","Przywodziciele"],primaryMuscle:"quads",equipment:"Sztanga olimpijska"},"Wykrok boczny (Lateral Lunge)":{steps:["Stań prosto, stopy razem, ręce przed klatką albo hantel trzymany oburącz.","Zrób szeroki krok w bok, stopy skierowane do przodu.","Przenieś ciężar na nogę kroczną, cofając biodra i uginając kolano, druga noga zostaje prosta.","Odepchnij się nogą kroczną i wróć do pozycji wyjściowej."],proTip:"Pięta nogi, na którą schodzisz, cały czas na podłodze. Głębokość zwiększaj stopniowo.",targetMuscles:["Czworogłowe uda","Przywodziciele","Pośladki"],primaryMuscle:"quads",equipment:"Masa ciała lub hantle"},"Przysiad rozkroczny statyczny (Split Squat)":{steps:["Stań w wykroku, jedna stopa z przodu, druga z tyłu na palcach, hantle po bokach.","Ustaw stopy na szerokość bioder, tułów prosto.","Opuść się pionowo, aż tylne kolano prawie dotknie podłogi.","Wróć w górę, pchając przednią stopą, i dokończ serię przed zmianą nogi."],proTip:"Stopy nie zmieniają pozycji przez całą serię, więc łatwiej skupić się na przedniej nodze niż w wykrokach chodzonych.",targetMuscles:["Czworogłowe uda","Pośladki"],primaryMuscle:"quads",equipment:"Hantle"},"Prasa nożna jednonóż":{steps:["Usiądź w maszynie i ustaw jedną stopę na środku platformy, drugą oprzyj na podłodze lub ramie maszyny.","Zwolnij blokadę i trzymaj uchwyty boczne.","Opuść platformę, zginając kolano, aż biodro zacznie się odrywać od oparcia, i zatrzymaj tuż przed tym.","Wypchnij platformę do wyprostu bez blokowania kolana i zmień nogę po serii."],proTip:"Zacznij od około połowy ciężaru, którego używasz obunóż. Praca jedną nogą szybko pokazuje różnice między stronami.",targetMuscles:["Czworogłowe uda","Pośladki","Dwugłowe uda"],primaryMuscle:"quads",equipment:"Maszyna Leg Press"},"Martwy ciąg rumuński z hantlami":{steps:["Stań prosto, hantle przed udami, stopy na szerokość bioder.","Lekko ugnij kolana i napnij brzuch.","Przesuń biodra w tył, prowadząc hantle wzdłuż nóg, aż poczujesz mocne rozciągnięcie z tyłu ud.","Wróć do wyprostu, wypychając biodra do przodu."],proTip:"Zakres kończy się tam, gdzie plecy zaczynają się zaokrąglać, zwykle w okolicy połowy piszczeli.",targetMuscles:["Dwugłowe uda","Pośladki","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Hantle"},"Martwy ciąg rumuński jednonóż z hantlem":{steps:["Stań na jednej nodze z lekko ugiętym kolanem, hantel trzymaj w ręce po przeciwnej stronie.","Napnij brzuch, wolna noga lekko za tobą.","Pochyl tułów do przodu, unosząc wolną nogę w tył, aż tułów i noga utworzą prawie poziomą linię.","Wróć do pionu, dociskając stopę nogi podporowej do podłogi."],proTip:"Pilnuj, żeby biodro wolnej nogi nie obracało się w górę. Palce tej stopy kieruj w podłogę.",targetMuscles:["Dwugłowe uda","Pośladki","Pośladki średnie"],primaryMuscle:"hamstrings",equipment:"Hantla"},"Martwy ciąg na prostych nogach (Stiff-Leg Deadlift)":{steps:["Stań ze sztangą przed sobą, chwyt na szerokość barków, kolana tylko lekko ugięte.","Napnij brzuch i ustaw plecy prosto.","Opuść sztangę wzdłuż nóg, przesuwając biodra w tył, aż do granicy, w której plecy zostają proste.","Wróć do wyprostu, wypychając biodra do przodu, sztanga blisko nóg."],proTip:"Od martwego ciągu rumuńskiego różni się mniejszym ugięciem kolan i większym rozciągnięciem tyłu ud. Zacznij od lżejszego ciężaru.",targetMuscles:["Dwugłowe uda","Pośladki","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Sztanga olimpijska"},"Martwy ciąg z trap barem":{steps:["Wejdź w środek trap bara, stopy na szerokość bioder, środek stopy pod osią uchwytów.","Zegnij biodra i kolana, chwyć uchwyty, ściągnij łopatki i napnij brzuch.","Wstań, pchając podłogę nogami, aż biodra i kolana wyprostują się jednocześnie.","Opuść gryf pod kontrolą tym samym torem, najpierw cofając biodra, potem uginając kolana."],proTip:"Przed każdym powtórzeniem weź wdech i napnij brzuch, dopiero potem odrywaj ciężar od podłogi.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowe uda","Prostowniki grzbietu"],primaryMuscle:"quads",equipment:"Trap bar (gryf heksagonalny)"},"Martwy ciąg z hantlami":{steps:["Postaw hantle po zewnętrznej stronie stóp, stopy na szerokość bioder.","Zegnij biodra i kolana, chwyć hantle chwytem neutralnym, wyprostuj plecy i napnij brzuch.","Wstań do pełnego wyprostu, prowadząc hantle blisko nóg.","Cofnij biodra i ugnij kolana, odkładając hantle pod kontrolą obok stóp."],proTip:"Trzymaj ramiona proste i luźne, hantle mają wisieć jak haki, a pracę wykonują nogi i biodra.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Czworogłowy uda","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Hantle"},"Martwy ciąg z kettlebell":{steps:["Stań nad kettlebell, stopy nieco szerzej niż biodra, uchwyt na linii środka stóp.","Cofnij biodra, ugnij kolana i chwyć uchwyt oburącz, plecy proste, brzuch napięty.","Wstań, prostując biodra i kolana, aż staniesz wyprostowany z napiętymi pośladkami.","Cofnij biodra i odłóż kettlebell pod kontrolą między stopy."],proTip:"Ściągnij łopatki w dół, jakbyś chciał wcisnąć uchwyt w uda, wtedy tułów nie zaokrągla się przy starcie.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Prostowniki grzbietu"],primaryMuscle:"hamstrings",equipment:"Kettlebell"},"Martwy ciąg z pauzą (Paused Deadlift)":{steps:["Ustaw się jak do klasycznego martwego ciągu: gryf nad środkiem stopy, plecy proste, brzuch napięty.","Oderwij sztangę i zatrzymaj ją na 1-2 s kilka centymetrów nad podłogą lub tuż pod kolanami.","Po pauzie dokończ ruch do pełnego wyprostu bioder i kolan.","Opuść sztangę pod kontrolą, prowadząc ją blisko nóg."],proTip:"Użyj ok. 70-80% ciężaru z klasycznego martwego ciągu, pauza ma uczyć pozycji, a nie walki z ciężarem.",targetMuscles:["Dwugłowe uda","Pośladkowy wielki","Prostowniki grzbietu","Czworoboczny"],primaryMuscle:"hamstrings",equipment:"Sztanga olimpijska"},"Uginanie nóg leżąc na piłce (Stability Ball Leg Curl)":{steps:["Połóż się na plecach, pięty oprzyj na piłce, ręce rozłóż na podłodze wzdłuż tułowia.","Unieś biodra, aby ciało tworzyło linię od barków do pięt.","Utrzymując biodra wysoko, ugnij kolana i przyciągnij piłkę piętami do pośladków.","Powoli wyprostuj nogi, odtaczając piłkę, bez opuszczania bioder."],proTip:"Gdy ruch stanie się łatwy, wykonuj fazę powrotu na jednej nodze.",targetMuscles:["Dwugłowe uda","Pośladkowy wielki","Mięśnie głębokie tułowia"],primaryMuscle:"hamstrings",equipment:"Piłka gimnastyczna"},"Przywodzenie nogi na wyciągu":{steps:["Załóż mankiet na kostkę nogi bliższej wyciągu dolnego i stań bokiem, trzymając się stelaża.","Odsuń się, aby linka była napięta, a noga z mankietem lekko odwiedziona w bok.","Przeciągnij nogę w kierunku drugiej nogi i nieco przed nią, trzymając tułów prosto.","Powoli wróć do pozycji startowej, nie pozwalając ciężarowi szarpnąć nogą."],proTip:"Nie przechylaj tułowia, ruch ma wychodzić z biodra, a nie z bujania całym ciałem.",targetMuscles:["Przywodziciele uda","Mięśnie głębokie tułowia"],primaryMuscle:"quads",equipment:"Wyciąg dolny z mankietem na kostkę"},"Przywodzenie nogi w leżeniu bokiem":{steps:["Połóż się na boku, głowę oprzyj na ramieniu, dolna noga prosta.","Ugnij górną nogę i postaw stopę na podłodze przed dolnym kolanem.","Unieś dolną nogę kilka centymetrów w górę, prowadząc ruch wewnętrzną stroną uda.","Zatrzymaj na chwilę i powoli opuść nogę bez odkładania jej całkowicie."],proTip:"Palce stopy dolnej nogi kieruj przed siebie, a nie w sufit, wtedy lepiej czujesz pracę wewnętrznej strony uda.",targetMuscles:["Przywodziciele uda"],primaryMuscle:"quads",equipment:"Masa ciała"},"Deska kopenhaska (Copenhagen Plank)":{steps:["Połóż się bokiem przy ławce, oprzyj przedramię pod barkiem, a górną nogę połóż na ławce (kolano lub stopa).","Unieś biodra, aby ciało tworzyło prostą linię od głowy do stóp.","Dolną nogę trzymaj w powietrzu pod ławką lub lekko przyciągniętą.","Utrzymaj pozycję przez zadany czas i opuść biodra pod kontrolą, potem zmień stronę."],proTip:"Zacznij od wersji z kolanem na ławce, oparcie stopy wyraźnie zwiększa trudność.",targetMuscles:["Przywodziciele uda","Mięśnie skośne brzucha","Mięśnie głębokie tułowia"],primaryMuscle:"quads",equipment:"Ławka"},"Przysiad jednonóż do ławki (Box Pistol)":{steps:["Stań tyłem do ławki, przenieś ciężar na jedną nogę, drugą wysuń lekko do przodu.","Wyciągnij ręce przed siebie dla równowagi i cofając biodra, powoli usiądź na ławce.","Dotknij ławki pośladkami bez rozluźniania całego ciała.","Wstań na jednej nodze, pchając podłogę całą stopą, kolano prowadź nad palcami."],proTip:"Im wyższa ławka, tym łatwiej. Obniżaj ją stopniowo, aż zejdziesz do pełnego przysiadu jednonóż.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Pośladki średnie"],primaryMuscle:"quads",equipment:"Ławka"},"Przysiad przy ścianie (Wall Sit)":{steps:["Oprzyj plecy o ścianę i odsuń stopy na ok. pół kroku, na szerokość bioder.","Zsuń się po ścianie, aż uda będą mniej więcej równoległe do podłogi.","Ustaw kolana nad kostkami, plecy i głowę trzymaj przy ścianie.","Utrzymaj pozycję przez zadany czas, oddychając spokojnie, i wstań, przesuwając się w górę."],proTip:"Nie opieraj dłoni na udach. Jeśli czas jest za długi, zacznij od wyższej pozycji.",targetMuscles:["Czworogłowy uda","Pośladki"],primaryMuscle:"quads",equipment:"Masa ciała"},"Skok na skrzynię (Box Jump)":{steps:["Stań przed skrzynią na odległość ok. stopy, stopy na szerokość bioder.","Cofnij ręce i wykonaj szybkie ugięcie bioder i kolan.","Wyskocz dynamicznie, wymachując rękami do przodu, i wyląduj na skrzyni na ugiętych nogach.","Wyprostuj się na skrzyni i zejdź na podłogę krok po kroku."],proTip:"Wybierz skrzynię, na którą lądujesz w płytkim przysiadzie. Każde powtórzenie zaczynaj od nowa, bez pośpiechu.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Mięśnie łydek"],primaryMuscle:"quads",equipment:"Skrzynia plyometryczna"},"Skok w dal z miejsca (Broad Jump)":{steps:["Stań ze stopami na szerokość bioder, ręce swobodnie przy tułowiu.","Cofnij ręce i ugnij biodra oraz kolana w szybkim ruchu w dół.","Wyskocz jak najdalej do przodu, wymachując rękami przed siebie.","Wyląduj na obu stopach w półprzysiadzie, zatrzymaj się i wróć na start."],proTip:"Liczy się jakość lądowania. Jeśli po wylądowaniu tracisz równowagę, skróć skok.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowe uda","Mięśnie łydek"],primaryMuscle:"quads",equipment:"Masa ciała"},"Przysiad z wyskokiem (Jump Squat)":{steps:["Stań ze stopami na szerokość barków, ręce przed klatką lub przy tułowiu.","Zejdź do płytkiego przysiadu, biodra w tył, kolana nad palcami.","Wyskocz dynamicznie w górę, prostując biodra, kolana i stawy skokowe.","Wyląduj miękko na przedniej części stóp, przechodząc płynnie w kolejny przysiad."],proTip:"Lądowanie ma być ciche. Głośne lądowanie oznacza, że nie amortyzujesz ruchu nogami.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Mięśnie łydek"],primaryMuscle:"quads",equipment:"Masa ciała"},"Wykroki z przeskokiem (Jumping Lunge)":{steps:["Ustaw się w wykroku: jedna noga z przodu, druga z tyłu, oba kolana ugięte.","Wyskocz dynamicznie w górę, pomagając sobie rękami.","W powietrzu zamień nogi miejscami.","Wyląduj miękko w wykroku na drugą nogę i od razu wykonaj kolejny wyskok."],proTip:"Jeśli tracisz równowagę, zrób krótką pauzę po każdym lądowaniu zamiast ciągłej serii.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Dwugłowe uda"],primaryMuscle:"quads",equipment:"Masa ciała"},"Uginanie sztangi łamanej (EZ) stojąc":{steps:["Stań prosto, chwyć gryf łamany podchwytem na wewnętrznych lub zewnętrznych zagięciach.","Przyciśnij łokcie do boków tułowia i napnij brzuch.","Uginaj ramiona, unosząc sztangę do wysokości barków bez przesuwania łokci do przodu.","Opuść sztangę powoli do pełnego wyprostu ramion."],proTip:"Skośny chwyt ustawia nadgarstki w pozycji pośredniej, więc łatwiej utrzymać równe tempo bez zginania nadgarstków.",targetMuscles:["Biceps","Ramienny","Ramienno-promieniowy"],primaryMuscle:"biceps",equipment:"Sztanga EZ"},"Uginanie hantla jednorącz na modlitewniku":{steps:["Usiądź lub stań przy modlitewniku, połóż tył ramienia płasko na pulpicie, hantel w dłoni podchwytem.","Zacznij z niemal wyprostowanym łokciem, bark opuszczony.","Uginaj rękę, unosząc hantel do momentu, gdy przedramię jest prawie pionowe.","Opuść hantel powoli, zatrzymując się tuż przed pełnym wyprostem łokcia."],proTip:"Najtrudniejsza jest dolna część ruchu, więc tam zwolnij, zamiast rzucać ciężar w dół.",targetMuscles:["Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Hantla + modlitewnik"},"Uginanie młotkowe w poprzek tułowia (Cross-Body Hammer Curl)":{steps:["Stań prosto z hantlami wzdłuż tułowia, kciuki skierowane do przodu.","Uginaj jedną rękę, prowadząc hantel skośnie przed tułowiem w stronę przeciwnego barku.","Zatrzymaj się, gdy hantel znajdzie się na wysokości klatki, łokieć blisko tułowia.","Opuść hantel powoli tą samą drogą i powtórz drugą ręką."],proTip:"Nie obracaj nadgarstka w trakcie ruchu. Stały chwyt neutralny utrzymuje pracę na mięśniu ramiennym.",targetMuscles:["Ramienny","Ramienno-promieniowy","Biceps"],primaryMuscle:"biceps",equipment:"Hantle"},"Uginanie ramion z gumą oporową":{steps:["Stań na środku gumy stopami na szerokość bioder, chwyć jej końce podchwytem.","Przyciśnij łokcie do boków tułowia, ramiona wyprostowane.","Uginaj ramiona, aż dłonie znajdą się na wysokości barków.","Wróć powoli do wyprostu, nie pozwalając gumie szarpnąć rąk w dół."],proTip:"Szerszy rozstaw stóp na gumie zwiększa opór bez zmiany gumy.",targetMuscles:["Biceps","Ramienny"],primaryMuscle:"biceps",equipment:"Guma oporowa"},"Prostowanie ramion na wyciągu podchwytem":{steps:["Stań przodem do wyciągu górnego, chwyć prosty drążek podchwytem na szerokość barków.","Przyciśnij łokcie do boków tułowia, przedramiona uniesione mniej więcej poziomo.","Wyprostuj ramiona, prowadząc drążek w dół do ud.","Wróć powoli do pozycji wyjściowej, łokcie nie ruszają się z miejsca."],proTip:"Podchwyt ogranicza ciężar, więc zacznij lżej niż przy klasycznym pushdownie i skup się na pełnym wyproście.",targetMuscles:["Triceps","Triceps (głowa przyśrodkowa)"],primaryMuscle:"triceps",equipment:"Wyciąg"},"Prostowanie ramienia w opadzie na wyciągu (Cable Kickback)":{steps:["Ustaw wyciąg dolny, chwyć uchwyt bez nasadki lub linkę jedną ręką i pochyl tułów do przodu.","Unieś ramię tak, by było równoległe do tułowia, łokieć zgięty pod kątem prostym.","Wyprostuj łokieć, prowadząc dłoń do tyłu, ramię pozostaje nieruchome.","Wróć powoli do zgięcia łokcia, po serii zmień stronę."],proTip:"Wyciąg daje napięcie także w zgięciu łokcia, więc nie skracaj ruchu na dole.",targetMuscles:["Triceps","Triceps (głowa boczna)"],primaryMuscle:"triceps",equipment:"Wyciąg"},"Wyciskanie francuskie hantlami leżąc":{steps:["Połóż się na ławce płaskiej i wyprostuj ramiona z hantlami nad barkami, dłonie zwrócone do siebie.","Ustaw ramiona lekko skośnie w stronę głowy i utrzymaj je nieruchomo.","Zegnij łokcie, opuszczając hantle powoli obok głowy.","Wyprostuj łokcie, wracając hantlami nad barki."],proTip:"Lekki skos ramion w stronę głowy utrzymuje napięcie tricepsa także w górnej fazie ruchu.",targetMuscles:["Triceps","Triceps (głowa długa)"],primaryMuscle:"triceps",equipment:"Hantle + ławka"},"Prostowanie ramion z gumą oporową":{steps:["Zaczep gumę wysoko, np. o drążek lub drzwi z kotwą, i chwyć jej końce nachwytem.","Przyciśnij łokcie do boków tułowia, przedramiona uniesione.","Wyprostuj ramiona, prowadząc dłonie w dół do ud.","Wróć powoli do zgięcia łokci, bez odrywania ich od tułowia."],proTip:"Krok w tył od punktu zaczepienia zwiększa opór w dolnej fazie ruchu.",targetMuscles:["Triceps"],primaryMuscle:"triceps",equipment:"Guma oporowa"},"Dipy z gumą (asysta)":{steps:["Rozepnij gumę między poręczami, chwyć poręcze i oprzyj kolana lub stopy na gumie.","Wyprostuj ramiona, barki opuszczone, tułów lekko pochylony do przodu.","Opuszczaj ciało, zginając łokcie, aż ramiona będą mniej więcej równoległe do podłogi.","Wypchnij się w górę do wyprostu ramion, nie unosząc barków do uszu."],proTip:"Schodź tylko tak nisko, jak potrafisz kontrolować ruch. Cieńsza guma to kolejny krok progresji.",targetMuscles:["Triceps","Klatka piersiowa","Przedni akton barku"],primaryMuscle:"triceps",equipment:"Poręcze + guma oporowa"},"Zwis na drążku (Dead Hang)":{steps:["Chwyć drążek nachwytem na szerokość barków, możesz stanąć na podwyższeniu, aby łatwiej go złapać.","Unieś stopy i zawiśnij na prostych ramionach, nogi razem.","Utrzymuj mocny chwyt i napięty brzuch, nie bujaj się.","Wytrzymaj zadany czas, potem postaw stopy na podwyższeniu lub podłodze pod kontrolą."],proTip:"Ściskaj drążek całą dłonią, także kciukiem. Czas wydłużaj o kilka sekund z tygodnia na tydzień.",targetMuscles:["Przedramiona","Najszerszy grzbietu"],primaryMuscle:"forearms",equipment:"Drążek"},"Chwyt szczypcowy talerzy (Plate Pinch)":{steps:["Złóż dwa talerze gładkimi stronami na zewnątrz i postaw je pionowo przy stopie.","Przysiądź, chwyć talerze szczypcowo: palce po jednej stronie, kciuk po drugiej.","Wstań z prostymi plecami i trzymaj talerze wzdłuż tułowia na prostej ręce.","Utrzymaj chwyt przez zadany czas, odłóż talerze kucając i zmień rękę."],proTip:"Stój nad miękkim podłożem albo blisko podłogi, bo talerze wypadają z dłoni bez ostrzeżenia.",targetMuscles:["Przedramiona","Zginacze palców"],primaryMuscle:"forearms",equipment:"Talerze"},"Nawijanie ciężarka na drążek (Wrist Roller)":{steps:["Chwyć drążek z linką nachwytem na szerokość barków, ciężarek wisi na podłodze.","Wyprostuj ramiona przed sobą na wysokości barków.","Obracaj drążek naprzemiennie nadgarstkami, nawijając linkę, aż ciężarek dotknie drążka.","Odwijaj linkę powoli tym samym ruchem, aż ciężarek wróci na podłogę."],proTip:"Jedno pełne nawinięcie i odwinięcie liczy się jako jedno powtórzenie. Zmieniaj kierunek obrotu między seriami.",targetMuscles:["Przedramiona","Prostowniki przedramienia","Aktony przednie barku"],primaryMuscle:"forearms",equipment:"Drążek z linką i talerz"},"Uginanie nadgarstków z hantlami":{steps:["Usiądź na ławce i oprzyj przedramiona na udach, dłonie z hantlami podchwytem poza kolanami.","Opuść hantle, prostując nadgarstki w dół, możesz rozluźnić palce.","Zegnij nadgarstki w górę jak najwyżej, zaciskając dłonie.","Opuść hantle powoli do pełnego rozciągnięcia."],proTip:"Przedramiona nie odrywają się od ud. Lekki ciężar i pełny zakres dają tu więcej niż duże obciążenie.",targetMuscles:["Przedramiona","Zginacze nadgarstka"],primaryMuscle:"forearms",equipment:"Hantle + ławka"},"Odwrotne uginanie nadgarstków z hantlami":{steps:["Usiądź na ławce i oprzyj przedramiona na udach, hantle nachwytem poza kolanami.","Opuść hantle, zginając nadgarstki w dół.","Unieś grzbiety dłoni w górę jak najwyżej, przedramiona nieruchome.","Opuść hantle powoli do pozycji wyjściowej."],proTip:"Prostowniki są słabsze niż zginacze, więc weź wyraźnie lżejsze hantle niż do klasycznego uginania.",targetMuscles:["Przedramiona","Prostowniki przedramienia"],primaryMuscle:"forearms",equipment:"Hantle + ławka"},"Unoszenie nóg leżąc":{steps:["Połóż się na plecach, ręce wzdłuż tułowia lub pod pośladkami, nogi proste.","Dociśnij lędźwie do podłogi i napnij brzuch.","Unieś nogi do pionu, możesz lekko ugiąć kolana.","Opuść nogi powoli, zatrzymując się tuż nad podłogą, zanim lędźwie się oderwą."],proTip:"Jeśli lędźwie odrywają się od podłogi, skróć zakres opuszczania albo ugnij kolana.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Masa ciała"},"Unoszenie kolan na poręczach (Captain's Chair)":{steps:["Oprzyj przedramiona na podpórkach stojaka, chwyć uchwyty i dociśnij plecy do oparcia.","Zwolnij stopy ze stopni i zawiśnij, barki opuszczone.","Unieś kolana w stronę klatki, lekko podwijając miednicę.","Opuść nogi powoli do pionu, bez bujania."],proTip:"Końcówka ruchu to podwinięcie miednicy, nie samo uniesienie ud. Dociążenie dodawaj hantlem między stopami.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Stojak z poręczami"},"Bird Dog (unoszenie ręki i nogi w klęku podpartym)":{steps:["Uklęknij w podporze: dłonie pod barkami, kolana pod biodrami, plecy płaskie.","Napnij brzuch i wyprostuj jednocześnie jedną rękę w przód i przeciwną nogę w tył.","Zatrzymaj się na 1-2 sekundy, gdy ręka i noga są w jednej linii z tułowiem.","Wróć powoli do klęku i powtórz na drugą stronę."],proTip:"Wyobraź sobie szklankę wody na lędźwiach. Miednica ma się nie obracać ani nie opadać.",targetMuscles:["Mięśnie głębokie tułowia","Prostowniki grzbietu","Pośladkowy wielki"],primaryMuscle:"core",equipment:"Masa ciała"},"Wiosłowanie w podporze (Renegade Row)":{steps:["Przyjmij podpór przodem na prostych rękach, dłonie na hantlach, stopy szerzej niż biodra.","Napnij brzuch i pośladki, ciało w jednej linii.","Przyciągnij jeden hantel do biodra, drugą ręką mocno dociskając hantel do podłogi.","Odłóż hantel pod kontrolą i powtórz drugą ręką."],proTip:"Szerszy rozstaw stóp ułatwia utrzymanie bioder w miejscu. Użyj hantli o płaskich głowach, które nie toczą się.",targetMuscles:["Mięśnie głębokie tułowia","Najszerszy grzbietu","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Hantle"},"Obroty landmine (Landmine 180)":{steps:["Stań przodem do landmine, stopy na szerokość barków, chwyć koniec sztangi oburącz przed klatką.","Wyprostuj ręce i napnij brzuch.","Prowadź sztangę łukiem w dół do jednego biodra, obracając tułów i stopy.","Przenieś sztangę przez środek łukiem do drugiego biodra i kontynuuj naprzemiennie."],proTip:"Tempo kontroluj brzuchem. Jeśli sztanga ciągnie cię w bok, zmniejsz ciężar.",targetMuscles:["Mięśnie skośne brzucha","Mięśnie głębokie tułowia","Barki"],primaryMuscle:"core",equipment:"Sztanga w gnieździe (landmine)"},"Spacer walizkowy (Suitcase Carry)":{steps:["Postaw hantel lub kettlebell przy stopie, przysiądź i chwyć go jedną ręką.","Wstań z prostymi plecami, barki na tej samej wysokości.","Idź równym krokiem przez zadany dystans lub czas, nie przechylając tułowia w stronę ciężaru.","Odłóż ciężar pod kontrolą i powtórz z drugą ręką."],proTip:"Wolną rękę trzymaj luźno wzdłuż tułowia albo wyprostuj w bok, żeby łatwiej zauważyć przechył.",targetMuscles:["Mięśnie skośne brzucha","Mięśnie głębokie tułowia","Przedramiona"],primaryMuscle:"core",equipment:"Hantla lub kettlebell"},"Spacer z ciężarem nad głową (Overhead Carry)":{steps:["Wyciśnij hantle lub kettlebell nad głowę, ramię przy uchu, łokieć zablokowany.","Napnij brzuch i pośladki, żebra nie wypychaj do przodu.","Idź krótkimi, równymi krokami przez zadany dystans lub czas.","Opuść ciężar pod kontrolą do barku, a potem na podłogę."],proTip:"Zacznij od lżejszego ciężaru niż przy wyciskaniu. Gdy ramię zaczyna uciekać do przodu, zakończ serię.",targetMuscles:["Mięśnie głębokie tułowia","Barki","Czworoboczny"],primaryMuscle:"core",equipment:"Hantle lub kettlebell"},"Skłony boczne z hantlem":{steps:["Stań prosto z hantlem w jednej ręce, druga ręka na biodrze lub za głową.","Pochyl tułów w bok w stronę hantla, bez skręcania i pochylania do przodu.","Wróć do pionu, napinając skośne mięśnie brzucha po przeciwnej stronie.","Wykonaj wszystkie powtórzenia i zmień rękę."],proTip:"Trzymaj hantel tylko w jednej ręce. Dwa hantle wzajemnie się równoważą i ćwiczenie traci sens.",targetMuscles:["Mięśnie skośne brzucha","Czworoboczny lędźwi"],primaryMuscle:"core",equipment:"Hantla"},"Wycieraczki leżąc (Windshield Wipers)":{steps:["Połóż się na plecach, ręce rozłożone na boki dłońmi w dół, nogi uniesione do pionu.","Napnij brzuch i złącz nogi, kolana mogą być lekko ugięte.","Opuść nogi powoli w jedną stronę, zatrzymując się, zanim przeciwna łopatka oderwie się od podłogi.","Wróć nogami do pionu siłą brzucha i opuść je na drugą stronę."],proTip:"Mniejszy zakres z pełną kontrolą daje więcej niż opuszczanie nóg do samej podłogi.",targetMuscles:["Mięśnie skośne brzucha","Mięsień prosty brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},"Wstawanie z ziemi z kettlebell (Turkish Get-up)":{steps:["Połóż się na plecach, wyciśnij kettlebell prawą ręką nad bark, prawa noga ugięta, lewa ręka i noga odsunięte w bok na podłodze.","Przejdź na lewy łokieć, potem na lewą dłoń, a następnie unieś biodra w mostek, trzymając ramię z ciężarem pionowo.","Przełóż lewą nogę pod sobą do klęku, wyprostuj tułów i wstań z wykroku do pełnej pozycji stojącej.","Wróć na podłogę dokładnie tą samą drogą w odwrotnej kolejności, bez pośpiechu na żadnym etapie."],proTip:"Naucz się sekwencji najpierw bez ciężaru albo z butem na pięści. Ciężar dokładaj dopiero, gdy każdy etap jest płynny.",targetMuscles:["Barki","Mięśnie głębokie tułowia","Pośladki","Mięśnie skośne brzucha"],primaryMuscle:"fullbody",equipment:"Kettlebell"},"Pallof Press z gumą oporową":{steps:["Przypnij gumę do stabilnego punktu na wysokości klatki i stań bokiem, stopy na szerokość bioder.","Chwyć gumę oburącz przy mostku i odsuń się, aż poczujesz wyraźne napięcie.","Wypchnij ręce prosto przed siebie i przytrzymaj 1-2 sekundy, trzymając biodra i barki przodem.","Wróć dłońmi do mostka pod kontrolą i powtórz, po serii zmień stronę."],proTip:"Im dalej od punktu zaczepienia stoisz, tym trudniej. Zwiększaj odległość, zanim sięgniesz po grubszą gumę.",targetMuscles:["Mięśnie skośne brzucha","Mięśnie głębokie tułowia","Mięsień poprzeczny brzucha"],primaryMuscle:"core",equipment:"Guma oporowa"},"Brzuszki na piłce (Stability Ball Crunch)":{steps:["Usiądź na piłce gimnastycznej i przejdź stopami do przodu, aż lędźwie i środek pleców oprą się o piłkę.","Stopy rozstaw na szerokość bioder, dłonie przy skroniach albo skrzyżowane na klatce.","Zwiń tułów, przybliżając żebra do miednicy, aż łopatki uniosą się z piłki.","Opuść się powoli do lekkiego odchylenia na piłce, czując rozciągnięcie brzucha, i powtórz."],proTip:"Nie ciągnij głowy dłońmi. Szersze ustawienie stóp daje stabilniejszą pozycję na początek.",targetMuscles:["Mięsień prosty brzucha","Mięśnie skośne brzucha"],primaryMuscle:"core",equipment:"Piłka gimnastyczna"},"Dotykanie pięt leżąc (Heel Touches)":{steps:["Połóż się na plecach, ugnij kolana i postaw stopy na podłodze nieco szerzej niż biodra.","Unieś głowę i łopatki kilka centymetrów nad podłogę, ręce wyprostowane wzdłuż ciała.","Zegnij tułów w prawo i dotknij prawej pięty prawą dłonią, bez opuszczania łopatek.","Wróć do środka i sięgnij lewą dłonią do lewej pięty, kontynuując naprzemiennie."],proTip:"Liczy się zgięcie w bok, a nie szarpanie głową. Stopy postawione dalej od pośladków utrudniają ruch.",targetMuscles:["Mięśnie skośne brzucha","Mięsień prosty brzucha"],primaryMuscle:"core",equipment:"Masa ciała"},"Nożyce leżąc (Flutter Kicks)":{steps:["Połóż się na plecach, dłonie pod pośladkami albo wzdłuż ciała, nogi wyprostowane.","Dociśnij lędźwie do podłogi i unieś obie stopy kilkanaście centymetrów nad ziemię.","Naprzemiennie unoś i opuszczaj nogi krótkimi ruchami, nie dotykając stopami podłogi.","Oddychaj równo i utrzymuj dociśnięte lędźwie do końca serii, po czym opuść nogi."],proTip:"Gdy lędźwie odrywają się od podłogi, unieś nogi wyżej. Wysokość nóg reguluje trudność.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Masa ciała"},"Przyciąganie kolan siedząc na ławce (Seated Knee Tuck)":{steps:["Usiądź na brzegu ławki płaskiej i chwyć jej krawędzie dłońmi po bokach bioder.","Odchyl tułów lekko do tyłu i wyprostuj nogi przed sobą, stopy tuż nad podłogą.","Przyciągnij kolana do klatki, jednocześnie zbliżając do nich tułów.","Wyprostuj nogi pod kontrolą z powrotem do pozycji wyjściowej, nie odkładając stóp na podłogę."],proTip:"Wykonuj ruch spokojnie, bez bujania tułowiem. Na początek możesz dotykać stopami podłogi między powtórzeniami.",targetMuscles:["Mięsień prosty brzucha","Zginacze bioder"],primaryMuscle:"core",equipment:"Ławka"},"Skręty tułowia na maszynie (Rotary Torso)":{steps:["Usiądź na maszynie, zablokuj nogi pod wałkami i ustaw zakres obrotu na wybraną stronę.","Oprzyj klatkę o poduszkę albo chwyć uchwyty, plecy wyprostowane.","Obróć tułów w stronę ruchu, spinając mięśnie skośne, biodra pozostają nieruchome.","Wróć powoli do pozycji wyjściowej, po serii przestaw maszynę i wykonaj drugą stronę."],proTip:"Ruch ma być wolny w obie strony. Jeśli ciężar ciągnie Cię z powrotem, użyj lżejszego ciężaru.",targetMuscles:["Mięśnie skośne brzucha","Mięśnie głębokie tułowia"],primaryMuscle:"core",equipment:"Maszyna"},"Hip Thrust jednonóż":{steps:["Usiądź przed ławką i oprzyj o nią dolną część łopatek.","Postaw jedną stopę na podłodze, drugą nogę unieś ugiętą lub wyprostowaną.","Wypchnij biodra w górę, dociskając piętę, aż tułów i udo utworzą linię.","Zatrzymaj na chwilę z napiętym pośladkiem i powoli opuść biodra."],proTip:"Trzymaj brodę lekko przyciągniętą i żebra w dół, żeby ruch kończył pośladek, a nie wygięcie lędźwi.",targetMuscles:["Pośladkowy wielki","Pośladki średnie","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Ławka"},"Mostek biodrowy ze sztangą (Barbell Glute Bridge)":{steps:["Usiądź na podłodze, przetocz sztangę (z nakładką na gryf) nad biodra i połóż się na plecach.","Ugnij kolana, stopy postaw płasko na szerokość bioder blisko pośladków.","Wypchnij biodra w górę, dociskając pięty, aż ciało utworzy linię od barków do kolan.","Zatrzymaj na chwilę na górze i opuść biodra pod kontrolą do podłogi."],proTip:"Użyj nakładki lub ręcznika na gryf i trzymaj sztangę rękami, żeby się nie przetaczała.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda"],primaryMuscle:"glutes",equipment:"Sztanga olimpijska"},"Odwodzenie ud z gumą w siadzie":{steps:["Załóż minigumę tuż nad kolanami i usiądź na krawędzi ławki lub krzesła.","Postaw stopy na szerokość bioder, dłonie oprzyj po bokach.","Rozsuń kolana na boki najszerzej, jak potrafisz, bez odrywania stóp.","Zatrzymaj na chwilę i powoli pozwól kolanom wrócić, utrzymując napięcie gumy."],proTip:"Zmieniaj pochylenie tułowia (wyprost, lekki skłon), żeby rozłożyć pracę na różne części pośladków.",targetMuscles:["Pośladki średnie","Naprężacz powięzi szerokiej"],primaryMuscle:"glutes",equipment:"Guma oporowa (miniguma)"},"Odwodzenie nogi w leżeniu bokiem":{steps:["Połóż się na boku, głowę oprzyj na ramieniu, dolną nogę lekko ugnij dla stabilności.","Wyprostuj górną nogę i ustaw ją w linii z tułowiem lub odrobinę za nim.","Unieś górną nogę w górę, prowadząc ruch piętą, bez rotowania stopy w stronę sufitu.","Zatrzymaj na chwilę i powoli opuść nogę, nie dotykając nią dolnej nogi."],proTip:"Nie przetaczaj miednicy do tyłu. Mniejszy zakres z dobrym ustawieniem daje więcej niż wysoki wymach.",targetMuscles:["Pośladki średnie","Naprężacz powięzi szerokiej"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Muszelka z gumą (Clamshell)":{steps:["Załóż minigumę nad kolanami i połóż się na boku, biodra i kolana ugięte pod kątem ok. 45 stopni.","Ustaw biodra jedno nad drugim, głowę oprzyj na ramieniu.","Trzymając stopy razem, unieś górne kolano jak najwyżej bez odchylania miednicy.","Zatrzymaj na chwilę i powoli opuść kolano, nie tracąc napięcia gumy."],proTip:"Oprzyj wolną dłoń na biodrze i pilnuj, żeby miednica nie odchylała się w tył przy otwieraniu kolana.",targetMuscles:["Pośladki średnie","Mięśnie pośladkowe"],primaryMuscle:"glutes",equipment:"Guma oporowa (miniguma)"},"Wymachy nóg w leżeniu przodem (Reverse Hyperextension)":{steps:["Połóż się przodem na maszynie lub wysokiej ławce tak, by biodra były na krawędzi, a nogi zwisały.","Chwyć uchwyty lub krawędź ławki, napnij brzuch.","Unieś nogi razem w górę, aż znajdą się mniej więcej w linii z tułowiem, napinając pośladki.","Opuść nogi pod kontrolą, bez bujania i wymachu."],proTip:"Zatrzymaj nogi na górze na sekundę. Jeśli musisz bujać, użyj lżejszego ciężaru.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Prostowniki grzbietu"],primaryMuscle:"glutes",equipment:"Maszyna do reverse hyper lub wysoka ławka"},"Wykrok w tył z deficytu":{steps:["Stań na stabilnym podwyższeniu o wysokości 5-10 cm z hantlami w dłoniach, ręce wzdłuż tułowia.","Zrób długi krok jedną nogą w tył na podłogę, ciężar zostaw na przedniej pięcie.","Opuść biodra, aż tylne kolano znajdzie się tuż nad podłogą, tułów lekko pochylony do przodu.","Odepchnij się przednią nogą i wróć stopą na podwyższenie, zanim zmienisz stronę."],proTip:"Lekki pochył tułowia i nacisk na piętę przedniej nogi przenoszą pracę na pośladek.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowy uda"],primaryMuscle:"glutes",equipment:"Hantle + podwyższenie"},"Martwy ciąg sumo z hantlem":{steps:["Stań szerzej niż na szerokość barków, palce stóp skierowane lekko na zewnątrz, hantel pionowo między stopami.","Cofnij biodra i ugnij kolana na zewnątrz, chwyć hantel oburącz za górną główkę przy prostych plecach.","Wstań, wypychając podłogę stopami i prostując biodra, hantel prowadź blisko ciała.","Na górze napnij pośladki, potem opuść hantel tą samą drogą do lekkiego dotknięcia podłogi."],proTip:"Kolana kieruj nad palce stóp przez cały ruch, nie pozwól im schodzić do środka.",targetMuscles:["Pośladkowy wielki","Przywodziciele ud","Czworogłowy uda"],primaryMuscle:"glutes",equipment:"Hantla"},"Wspięcia na palce z hantlami stojąc":{steps:["Stań przodami stóp na stopniu lub talerzu, pięty poza krawędzią, hantle trzymaj wzdłuż tułowia.","Opuść pięty jak najniżej, aż poczujesz rozciągnięcie łydek.","Wznieś się na palce jak najwyżej, kolana proste, ale nie zablokowane.","Zatrzymaj się na sekundę w górze i powoli wróć do pełnego rozciągnięcia."],proTip:"Nie odbijaj się z dołu. Krótka pauza w rozciągnięciu sprawia, że pracują łydki, a nie ścięgno.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Hantle"},"Wspięcia na palce siedząc z hantlami":{steps:["Usiądź na ławce, przody stóp połóż na talerzu lub stopniu, kolana zgięte pod kątem prostym.","Połóż hantle na udach tuż nad kolanami i przytrzymaj je dłońmi.","Opuść pięty do pełnego rozciągnięcia, potem wznieś je jak najwyżej.","Zatrzymaj się na sekundę w szczycie i opuść pięty powoli."],proTip:"Zgięte kolana przenoszą akcent na mięsień płaszczkowaty, dlatego tu dobrze sprawdza się więcej powtórzeń.",targetMuscles:["Płaszczkowaty","Brzuchaty łydki"],primaryMuscle:"calves",equipment:"Hantle + ławka"},"Podskoki na palcach (Pogo Jumps)":{steps:["Stań prosto, stopy na szerokość bioder, ręce luźno lub na biodrach.","Odbij się z przodów stóp, pracując głównie w stawach skokowych, kolana prawie proste.","Ląduj cicho na przodach stóp, pięty nie dotykają podłogi.","Od razu wykonaj kolejne odbicie, utrzymując równy, szybki rytm przez całą serię."],proTip:"Myśl o podłodze jak o gorącej płycie: jak najkrótszy kontakt stopy z ziemią.",targetMuscles:["Brzuchaty łydki","Płaszczkowaty"],primaryMuscle:"calves",equipment:"Masa ciała"},"Rzut piłką lekarską sprzed klatki (Chest Pass)":{steps:["Stań ok. 1-2 m przed solidną ścianą, stopy na szerokość bioder, piłka lekarska przy klatce.","Łokcie skieruj na boki, lekko ugnij kolana i napnij brzuch.","Wypchnij piłkę dynamicznie przed siebie o ścianę, prostując ramiona do końca.","Złap odbitą piłkę, zamortyzuj ją przy klatce i wykonaj kolejny rzut."],proTip:"Liczy się prędkość, nie ciężar. Wybierz piłkę 3-6 kg i kończ serię, gdy rzuty wyraźnie zwalniają.",targetMuscles:["Klatka piersiowa","Triceps","Przednie aktony barków"],primaryMuscle:"chest",equipment:"Piłka lekarska"},"Zarzut siłowy sztangi (Power Clean)":{steps:["Ustaw się jak do martwego ciągu, chwyt nieco szerzej niż barki, barki nad gryfem.","Oderwij sztangę spokojnie do wysokości kolan, trzymając plecy proste.","Nad kolanami wyprostuj gwałtownie biodra i kolana, unieś barki i ciągnij sztangę blisko ciała.","Szybko podsuń łokcie do przodu i odbierz sztangę na przodzie barków w płytkim półprzysiadzie, potem wstań."],proTip:"Sztanga ma lecieć blisko ciała. Ucz się z lekkim ciężarem, zanim zaczniesz go dokładać.",targetMuscles:["Pośladkowy wielki","Czworogłowy uda","Dwugłowe uda","Czworoboczny"],primaryMuscle:"fullbody",equipment:"Sztanga olimpijska"},"Zarzut sztangi z zawieszenia (Hang Clean)":{steps:["Stań ze sztangą w rękach, chwyt nieco szerzej niż barki, ramiona proste.","Cofnij biodra i zsuń sztangę do połowy ud lub tuż nad kolana, plecy proste.","Gwałtownie wyprostuj biodra i kolana, unieś barki i ciągnij sztangę blisko tułowia.","Szybko podsuń łokcie do przodu i odbierz sztangę na przodzie barków w półprzysiadzie, potem wstań."],proTip:"Ruch zaczyna się z bioder, a nie z rąk. Ramiona są prowadnicą, dopóki biodra się nie wyprostują.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Czworoboczny","Czworogłowy uda"],primaryMuscle:"fullbody",equipment:"Sztanga olimpijska"},"Zarzut i wyciskanie sztangi (Clean and Press)":{steps:["Wykonaj zarzut: z podłogi lub z zawieszenia dynamicznie przenieś sztangę na przód barków.","Wstań i ustabilizuj pozycję: stopy na szerokość bioder, brzuch i pośladki napięte.","Wyciśnij sztangę nad głowę po prostej linii, przesuwając głowę lekko w tył, a potem pod gryf.","Opuść sztangę na barki, a następnie pod kontrolą na uda i podłogę."],proTip:"Traktuj to jako dwa osobne ruchy. Nie wyciskaj, zanim nie złapiesz równowagi po zarzucie.",targetMuscles:["Przednie aktony barków","Pośladkowy wielki","Czworoboczny","Triceps"],primaryMuscle:"fullbody",equipment:"Sztanga olimpijska"},"Rwanie hantla jednorącz (Dumbbell Snatch)":{steps:["Stań nad hantlem ustawionym między stopami, cofnij biodra i chwyć go jedną ręką.","Wyprostuj gwałtownie biodra i kolana, prowadząc hantel blisko ciała w górę.","Gdy hantel mija klatkę, podsuń łokieć i wypchnij rękę do prostego ramienia nad głową.","Ustabilizuj hantel nad głową, a potem opuść go pod kontrolą najpierw na bark, potem do podłogi."],proTip:"Siła ma iść z bioder. Jeśli ciągniesz głównie ręką, zmniejsz ciężar.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Aktony boczne barku","Czworoboczny"],primaryMuscle:"fullbody",equipment:"Hantla"},"Zarzut kettlebell jednorącz (Kettlebell Clean)":{steps:["Stań nad kettlebell, cofnij biodra i chwyć uchwyt jedną ręką.","Przerzuć kettlebell między nogami jak przy wymachu.","Dynamicznie wyprostuj biodra i prowadź kettlebell blisko tułowia, łokieć przy ciele.","Obróć dłoń i przyjmij kettlebell w pozycji przy barku, z przedramieniem pionowo, potem opuść do kolejnego zamachu."],proTip:"Wsuń dłoń w uchwyt, zanim kettlebell dojdzie do góry, wtedy nie przewraca się na przedramię.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Prostowniki grzbietu","Przedramiona"],primaryMuscle:"fullbody",equipment:"Kettlebell"},"Rwanie kettlebell jednorącz (Kettlebell Snatch)":{steps:["Stań nad kettlebell, cofnij biodra i chwyć uchwyt jedną ręką.","Przerzuć kettlebell między nogami i dynamicznie wyprostuj biodra.","Prowadź kettlebell blisko ciała w górę, a na wysokości głowy wsuń dłoń w uchwyt i wypchnij rękę w górę.","Ustabilizuj kettlebell nad głową, potem opuść go łukiem przed sobą do kolejnego zamachu."],proTip:"Opanuj najpierw wymach i zarzut kettlebell. Rwanie łączy oba ruchy i wymaga pewnego chwytu.",targetMuscles:["Pośladkowy wielki","Dwugłowe uda","Aktony boczne barku","Przedramiona"],primaryMuscle:"fullbody",equipment:"Kettlebell"},"Thruster z hantlami (przysiad z wyciskaniem)":{steps:["Stań ze stopami na szerokość barków, hantle przy barkach, łokcie lekko z przodu.","Zejdź do przysiadu, trzymając tułów wyprostowany, a hantle przy barkach.","Wstań dynamicznie i wykorzystaj ten ruch, by wypchnąć hantle nad głowę do prostych ramion.","Opuść hantle z powrotem na barki i od razu przejdź w kolejny przysiad."],proTip:"Nie rób pauzy między przysiadem a wyciskaniem, wstawanie ma napędzać ruch rąk.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Przednie aktony barków","Triceps"],primaryMuscle:"fullbody",equipment:"Hantle"},"Rzut piłką lekarską o ścianę (Wall Ball)":{steps:["Stań twarzą do ściany w odległości ok. pół metra, piłkę trzymaj przy klatce.","Zejdź do przysiadu z wyprostowanym tułowiem i łokciami pod piłką.","Wstań dynamicznie i wyrzuć piłkę w górę w wyznaczony punkt na ścianie.","Złap piłkę na wysokości klatki i od razu zejdź w kolejny przysiad."],proTip:"Rzut ma wynikać z wyprostu nóg. Jeśli rzucasz głównie rękami, piłka jest za ciężka.",targetMuscles:["Czworogłowy uda","Pośladkowy wielki","Przednie aktony barków"],primaryMuscle:"fullbody",equipment:"Piłka lekarska"},"Rzut rotacyjny piłką lekarską o ścianę":{steps:["Stań bokiem do ściany w odległości około metra, piłka lekarska przy biodrze dalszym od ściany.","Ugnij lekko kolana i obróć tułów od ściany, przenosząc ciężar na tylną nogę.","Dynamicznie obróć biodra i tułów w stronę ściany, wyrzucając piłkę na wysokości klatki.","Złap odbitą piłkę, wróć do pozycji wyjściowej i wykonaj kolejny rzut, po serii zmień stronę."],proTip:"Tylna stopa ma obracać się na palcach razem z biodrami. Jeśli rzucasz samymi rękami, zmniejsz ciężar piłki.",targetMuscles:["Mięśnie skośne brzucha","Mięśnie głębokie tułowia","Barki","Pośladki"],primaryMuscle:"core",equipment:"Piłka lekarska"},"Slam piłką lekarską (Medball Slam)":{steps:["Stań w lekkim rozkroku z piłką lekarską (najlepiej bez odbicia) trzymaną oburącz przed sobą.","Unieś piłkę nad głowę, wyprostuj ciało i wespnij się lekko na palce.","Uderz piłką o podłogę przed stopami, napinając brzuch i uginając biodra oraz kolana.","Podnieś piłkę z przysiadu z prostymi plecami i od razu przejdź do kolejnego powtórzenia."],proTip:"Rzucaj całym ciałem, nie samymi rękami. Piłka odbijająca się wysoko potrafi wrócić w twarz, dlatego wybierz model bez odbicia.",targetMuscles:["Mięsień prosty brzucha","Najszerszy grzbietu","Barki","Pośladki"],primaryMuscle:"fullbody",equipment:"Piłka lekarska"},"Wioślarz (ergometr wioślarski)":{steps:["Usiądź na siodełku, zapnij stopy w podnóżkach i chwyć rączkę nachwytem, ręce proste.","Odepchnij się nogami, a gdy kolana są prawie proste, odchyl tułów lekko do tyłu.","Na końcu przyciągnij rączkę do dolnej części klatki, łokcie prowadź blisko tułowia.","Wróć w odwrotnej kolejności: ręce, tułów, dopiero potem ugnij kolana, i płynnie zacznij kolejny ruch."],proTip:"Większość mocy pochodzi z nóg. Ustaw opór na średni poziom i pracuj tempem, zamiast ciągnąć rękami.",targetMuscles:["Czworogłowy uda","Pośladki","Najszerszy grzbietu","Mięśnie głębokie tułowia"],primaryMuscle:"fullbody",equipment:"Wioślarz (ergometr)"},"Rower stacjonarny":{steps:["Ustaw wysokość siodełka tak, by przy pedale w dolnym położeniu kolano było lekko ugięte.","Usiądź, chwyć kierownicę bez zaciskania i ustaw stopy na środku pedałów.","Rozpocznij od kilku minut spokojnego tempa, potem ustaw opór zgodny z planem.","Utrzymuj równe tempo przez zadany czas, a na koniec zmniejsz opór i zwolnij."],proTip:"W interwałach zmieniaj opór, a nie tylko tempo. Biodra mają pozostać stabilne na siodełku.",targetMuscles:["Czworogłowy uda","Pośladki","Dwugłowe uda","Mięśnie łydek"],primaryMuscle:"quads",equipment:"Rower stacjonarny"},"Rower powietrzny (Air Bike)":{steps:["Ustaw siodełko tak, by kolano było lekko ugięte w dolnym położeniu pedału.","Chwyć ruchome uchwyty, stopy ustaw na pedałach, tułów lekko pochylony do przodu.","Pedałuj, jednocześnie pchając i ciągnąc uchwyty naprzemiennie z nogami.","Utrzymuj założone tempo przez czas serii, potem zwolnij i odpocznij zgodnie z planem."],proTip:"Opór zależy od prędkości, więc krótkie interwały bywają bardzo intensywne. Zacznij od umiarkowanego tempa w pierwszych rundach.",targetMuscles:["Czworogłowy uda","Pośladki","Barki","Mięśnie łydek"],primaryMuscle:"fullbody",equipment:"Rower powietrzny"},"Marsz pod górę na bieżni":{steps:["Wejdź na bieżnię, uruchom ją na wolnym tempie marszu i przypnij klips awaryjnego zatrzymania, jeśli jest.","Stopniowo zwiększ nachylenie do wartości z planu i ustaw tempo, przy którym idziesz swobodnie.","Idź wyprostowany, ręce pracują naturalnie, bez opierania się o poręcze.","Pod koniec serii zmniejsz nachylenie i tempo, a zejdź dopiero po zatrzymaniu pasa."],proTip:"Trzymanie się poręczy zmniejsza pracę nóg. Jeśli musisz się trzymać, obniż nachylenie albo tempo.",targetMuscles:["Pośladki","Mięśnie łydek","Czworogłowy uda","Dwugłowe uda"],primaryMuscle:"quads",equipment:"Bieżnia"},"Bieg na bieżni":{steps:["Uruchom bieżnię na tempie marszu i przez 2-3 minuty rozgrzej się, stopniowo przyspieszając.","Ustaw prędkość biegu z planu i ewentualnie nachylenie 1 procent.","Biegnij wyprostowany, lądując stopą pod biodrem, ręce ugięte pracują wzdłuż tułowia.","Na koniec serii zwolnij do marszu na kilka minut, a zejdź dopiero po zatrzymaniu pasa."],proTip:"Tempo dobierz tak, by przy spokojnym biegu dało się mówić pełnymi zdaniami. W interwałach przyspieszaj stopniowo.",targetMuscles:["Czworogłowy uda","Dwugłowe uda","Mięśnie łydek","Pośladki"],primaryMuscle:"quads",equipment:"Bieżnia"},Orbitrek:{steps:["Wejdź na orbitrek, postaw stopy płasko na płozach i chwyć ruchome uchwyty.","Rozpocznij ruch w wolnym tempie i po 2-3 minutach ustaw opór z planu.","Pchaj i ciągnij uchwyty w rytmie nóg, tułów wyprostowany, wzrok przed siebie.","Utrzymuj równe tempo przez czas serii, a na koniec zmniejsz opór i zwolnij."],proTip:"Nie opieraj się ciężarem ciała o uchwyty. Pięty mają pozostać na płozach przez cały ruch.",targetMuscles:["Czworogłowy uda","Pośladki","Dwugłowe uda","Barki"],primaryMuscle:"fullbody",equipment:"Orbitrek"},"Ergometr narciarski":{steps:["Stań przodem do urządzenia, stopy na szerokość bioder, chwyć uchwyty nad głową.","Zacznij ruch od ściągnięcia uchwytów w dół prostymi rękami, jednocześnie zginając biodra.","Dokończ ruch przy biodrach, lekko uginając kolana, z napiętym brzuchem.","Wyprostuj się i unieś ręce z powrotem nad głowę, płynnie przechodząc do kolejnego ruchu."],proTip:"Moc daje zgięcie bioder i ciężar ciała, nie same ręce. Plecy trzymaj proste na dole ruchu.",targetMuscles:["Najszerszy grzbietu","Triceps","Mięśnie głębokie tułowia","Pośladki"],primaryMuscle:"fullbody",equipment:"Ergometr narciarski"},"Stepper (wchodzenie po schodach)":{steps:["Wejdź na maszynę, chwyć poręcze tylko dla równowagi i uruchom ją na wolnym tempie.","Stawiaj całą stopę na stopniu i wchodź, prostując nogę w kolanie i biodrze.","Po 2-3 minutach ustaw tempo z planu, tułów wyprostowany, dłonie luźno na poręczach.","Na koniec serii zwolnij, a zejdź dopiero po zatrzymaniu schodów."],proTip:"Opieranie się na poręczach z pochylonym tułowiem zabiera pracę nogom. Lepiej zwolnij, niż się podpierać.",targetMuscles:["Pośladki","Czworogłowy uda","Mięśnie łydek"],primaryMuscle:"quads",equipment:"Stepper (schody)"},"Liny bojowe (Battle Ropes)":{steps:["Chwyć końce liny oburącz i odsuń się od zaczepu, aż lina będzie lekko luźna.","Stań w lekkim półprzysiadzie, stopy na szerokość barków, tułów lekko pochylony.","Unoś i opuszczaj ręce naprzemiennie szybkim rytmem, tworząc fale docierające do zaczepu.","Utrzymuj rytm i pozycję przez czas serii, a potem odłóż liny."],proTip:"Fale mają dochodzić do zaczepu. Gdy słabną, podejdź bliżej zamiast zwalniać do zera.",targetMuscles:["Barki","Przedramiona","Mięśnie głębokie tułowia","Czworogłowy uda"],primaryMuscle:"fullbody",equipment:"Liny treningowe"},"Pchanie sań (Sled Push)":{steps:["Załaduj sanie, chwyć wysokie albo niskie uchwyty i odsuń stopy tak, by tułów był pochylony.","Napnij brzuch, ręce trzymaj mocno wyprostowane albo lekko ugięte.","Pchaj sanie krótkimi, mocnymi krokami, odpychając się przodostopiem.","Utrzymuj stałe tempo do końca dystansu i zatrzymaj sanie przed odpoczynkiem."],proTip:"Gdy sanie stają, zmniejsz ciężar. Płynny ruch na całym dystansie daje więcej niż szarpanie za dużym ładunkiem.",targetMuscles:["Czworogłowy uda","Pośladki","Mięśnie łydek","Mięśnie głębokie tułowia"],primaryMuscle:"quads",equipment:"Sanie treningowe"},"Ciągnięcie sań (Sled Drag)":{steps:["Przypnij linę lub pasy do sań, chwyć uchwyty i odejdź, aż lina się napnie.","Przy ciągnięciu tyłem stań twarzą do sań, lekko ugnij kolana i odchyl tułów.","Idź krótkimi krokami, odpychając się stopami od podłogi, ręce trzymaj proste.","Pokonaj zadany dystans w równym tempie i zatrzymaj się, zanim puścisz linę."],proTip:"Ciągnięcie tyłem mocno angażuje uda przy małym ruchu w kolanach. Dobry wybór na rozgrzewkę albo zakończenie treningu.",targetMuscles:["Czworogłowy uda","Pośladki","Mięśnie łydek","Przedramiona"],primaryMuscle:"quads",equipment:"Sanie treningowe"},"Pajacyki (Jumping Jacks)":{steps:["Stań prosto, stopy razem, ręce wzdłuż ciała.","Podskocz, rozstawiając stopy szerzej niż barki i unosząc ręce bokiem nad głowę.","Kolejnym podskokiem złącz stopy i opuść ręce wzdłuż ciała.","Powtarzaj w równym rytmie przez czas serii, lądując miękko na śródstopiu."],proTip:"Bez skakania możesz wykonywać wersję krokową: dostawiaj nogę w bok naprzemiennie, ręce pracują tak samo.",targetMuscles:["Mięśnie łydek","Barki","Czworogłowy uda","Pośladki średnie"],primaryMuscle:"fullbody",equipment:"Masa ciała"},"Bieg w miejscu z wysokim unoszeniem kolan (High Knees)":{steps:["Stań prosto, stopy na szerokość bioder, ręce ugięte w łokciach.","Zacznij biec w miejscu, unosząc na zmianę kolana do wysokości bioder.","Ląduj na śródstopiu, tułów trzymaj wyprostowany, ręce pracują w rytmie nóg.","Utrzymuj szybkie tempo przez czas serii, potem zwolnij do marszu."],proTip:"Wysokość kolan jest ważniejsza niż prędkość. Gdy kolana opadają, zwolnij i wróć do pełnego zakresu.",targetMuscles:["Zginacze bioder","Czworogłowy uda","Mięśnie łydek","Mięśnie głębokie tułowia"],primaryMuscle:"fullbody",equipment:"Masa ciała"},"Przeskoki łyżwiarza (Skater Jumps)":{steps:["Stań na prawej nodze z lekko ugiętym kolanem, lewa stopa uniesiona za tobą.","Odepchnij się prawą nogą i skocz w bok w lewo.","Wyląduj miękko na lewej nodze, prawą zakładając za nią, i zatrzymaj się na chwilę.","Odbij się w prawo i kontynuuj naprzemienne przeskoki przez całą serię."],proTip:"Zacznij od krótkich skoków i pewnego lądowania. Długość skoku zwiększaj, gdy kolano ląduje stabilnie nad stopą.",targetMuscles:["Pośladki średnie","Pośladki","Czworogłowy uda","Mięśnie łydek"],primaryMuscle:"glutes",equipment:"Masa ciała"},"Chód niedźwiedzia (Bear Crawl)":{steps:["Zejdź do klęku podpartego: dłonie pod barkami, kolana pod biodrami.","Unieś kolana kilka centymetrów nad podłogę, plecy płaskie, brzuch napięty.","Przesuń do przodu prawą dłoń i lewą stopę, potem lewą dłoń i prawą stopę.","Poruszaj się krótkimi krokami przez czas serii, utrzymując biodra nisko i stabilnie."],proTip:"Biodra nie powinny unosić się wyżej niż barki. Krótsze kroki pomagają utrzymać stabilny tułów.",targetMuscles:["Mięśnie głębokie tułowia","Barki","Czworogłowy uda","Triceps"],primaryMuscle:"fullbody",equipment:"Masa ciała"}};let n=null;const L=async()=>{if(n)return;n=(await f(()=>import("./exercise-details-en-C5RoNW93.js"),[])).exerciseDetailsEn},v=(i,t="pl")=>i?t==="en"?(n==null?void 0:n[i])??m[i]??null:m[i]??null:null,E={chest:"chest",back:"back",shoulders:"shoulders",legs:"quads",arms:"biceps",core:"core",glutes:"glutes",calves:"calves",conditioning:"fullbody"};export{E as c,v as g,L as p,A as u};
